import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import {
  AuditQueryDto,
  AuditRetentionPolicyDto,
} from '../dto/enterprise-admin.dto';

@Injectable()
export class AuditAdminService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async queryAuditLogs(
    companyId: string,
    dto: AuditQueryDto,
    isSuperAdmin: boolean = false,
  ) {
    const {
      page = 1,
      limit = 50,
      entity,
      userId,
      actionPrefix,
      startDate,
      endDate,
    } = dto;
    const where: any = {};
    if (!isSuperAdmin || companyId !== 'GLOBAL') {
      where.companyId = companyId;
    }
    if (entity) where.entity = entity;
    if (userId) where.userId = userId;
    if (actionPrefix) {
      where.action = { startsWith: actionPrefix };
    }
    if (startDate || endDate) {
      where.createdAt = {};
      if (startDate) where.createdAt.gte = new Date(startDate);
      if (endDate) where.createdAt.lte = new Date(endDate);
    }

    const [data, total] = await Promise.all([
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.findMany({
          where,
          orderBy: { createdAt: 'desc' },
          skip: (page - 1) * limit,
          take: limit,
          include: {
            user: {
              select: {
                id: true,
                firstName: true,
                lastName: true,
                email: true,
              },
            },
          },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({ where }),
      ),
    ]);

    return { data, total, page, limit, totalPages: Math.ceil(total / limit) };
  }

  async getUserTimeline(
    companyId: string,
    userId: string,
    page: number = 1,
    limit: number = 50,
  ) {
    return this.queryAuditLogs(companyId, { userId, page, limit });
  }

  async getSecurityEvents(
    companyId: string,
    page: number = 1,
    limit: number = 50,
  ) {
    const where = {
      companyId,
      OR: [
        { action: { startsWith: 'auth:' } },
        { action: { startsWith: 'security:' } },
        { action: { startsWith: 'sso:' } },
        { action: { startsWith: 'mfa:' } },
        { action: { startsWith: 'admin:security:' } },
        { action: { startsWith: 'admin:user:lock' } },
        { action: { startsWith: 'admin:user:suspend' } },
      ],
    };

    const [data, total] = await Promise.all([
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.findMany({
          where,
          orderBy: { createdAt: 'desc' },
          skip: (page - 1) * limit,
          take: limit,
          include: {
            user: {
              select: {
                id: true,
                firstName: true,
                lastName: true,
                email: true,
              },
            },
          },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({ where }),
      ),
    ]);

    return { data, total, page, limit, totalPages: Math.ceil(total / limit) };
  }

  async getComplianceReport(companyId: string) {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    const [totalEvents, authFailures, adminMutations, securityChanges] =
      await Promise.all([
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.auditLog.count({
            where: { companyId, createdAt: { gte: thirtyDaysAgo } },
          }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.auditLog.count({
            where: {
              companyId,
              createdAt: { gte: thirtyDaysAgo },
              OR: [
                { action: 'auth:login:failed' },
                { action: 'auth:mfa:failed' },
                { action: 'auth:brute_force_lock' },
              ],
            },
          }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.auditLog.count({
            where: {
              companyId,
              createdAt: { gte: thirtyDaysAgo },
              action: { startsWith: 'admin:' },
            },
          }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.auditLog.count({
            where: {
              companyId,
              createdAt: { gte: thirtyDaysAgo },
              action: { startsWith: 'security:' },
            },
          }),
        ),
      ]);

    const config = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfiguration.findUnique({ where: { companyId } }),
    );
    const policies = (config?.policies || {}) as Record<string, any>;

    return {
      companyId,
      reportGeneratedAt: now.toISOString(),
      periodDays: 30,
      metrics: {
        totalAuditEvents: totalEvents,
        authenticationFailures: authFailures,
        administrativeMutations: adminMutations,
        securityPolicyModifications: securityChanges,
      },
      compliancePosture: {
        mfaRequired: !!policies.requireMfa,
        auditRetentionDays: policies.auditRetentionDays || 365,
        passwordExpiryDays: policies.passwordExpiryDays || 90,
        compliant:
          !!policies.requireMfa && (policies.auditRetentionDays || 365) >= 90,
      },
    };
  }

  async getRetentionPolicy(companyId: string) {
    const config = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfiguration.findUnique({ where: { companyId } }),
    );
    const policies = (config?.policies || {}) as Record<string, any>;
    return {
      companyId,
      auditRetentionDays: policies.auditRetentionDays || 365,
      autoArchiveEnabled: true,
    };
  }

  async updateRetentionPolicy(
    companyId: string,
    dto: AuditRetentionPolicyDto,
    adminUserId: string,
  ) {
    const config = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfiguration.findUnique({ where: { companyId } }),
    );
    if (!config)
      throw new NotFoundException(
        `Tenant configuration for ${companyId} not found`,
      );

    const currentPolicies = (config.policies || {}) as Record<string, any>;
    const updatedPolicies = {
      ...currentPolicies,
      auditRetentionDays: dto.auditRetentionDays,
    };

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfiguration.update({
        where: { companyId },
        data: { policies: updatedPolicies },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:audit:update_retention',
      entity: 'TenantConfiguration',
      entityId: config.id,
      userId: adminUserId,
      companyId,
      details: { auditRetentionDays: dto.auditRetentionDays },
    });

    return { companyId, auditRetentionDays: dto.auditRetentionDays };
  }

  async purgeExpiredLogs(companyId: string, adminUserId: string) {
    const policy = await this.getRetentionPolicy(companyId);
    const cutoffDate = new Date(
      Date.now() - policy.auditRetentionDays * 24 * 60 * 60 * 1000,
    );

    const result = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.auditLog.deleteMany({
        where: { companyId, createdAt: { lt: cutoffDate } },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:audit:purge_expired',
      entity: 'AuditLog',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: {
        purgedCount: result.count,
        cutoffDate: cutoffDate.toISOString(),
      },
    });

    return { purgedCount: result.count, cutoffDate: cutoffDate.toISOString() };
  }
}

import { Injectable, Logger } from '@nestjs/common';

@Injectable()
export class AuditLoggerService {
  private readonly logger = new Logger(AuditLoggerService.name);

  async logAction(payload: {
    tenantId: string;
    userId: string;
    action: string;
    resource: string;
    oldValue?: any;
    newValue?: any;
    ipAddress?: string;
    deviceInfo?: string;
  }) {
    this.logger.log(
      `Audit Log [${payload.tenantId}]: User ${payload.userId} performed ${payload.action} on ${payload.resource}`,
    );
    // Scaffolded: Push to immutable WORM storage (e.g. AWS QLDB or Kafka -> S3)
    return { success: true, timestamp: new Date().toISOString() };
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';

@Injectable()
export class DashboardAdminService {
  constructor(
    private readonly prisma: PrismaService,
    // @ts-ignore: DI dependency reserved for future use
    private readonly _audit: AuditService,
  ) {}

  async getDashboardSummary(companyId: string, isSuperAdmin: boolean = false) {
    const now = new Date();
    const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

    const whereTenant: any =
      !isSuperAdmin || companyId !== 'GLOBAL' ? { companyId } : {};
    const whereCompany: any =
      !isSuperAdmin || companyId !== 'GLOBAL' ? { id: companyId } : {};

    const [
      totalTenants,
      activeTenants,
      suspendedTenants,
      totalUsers,
      activeUsers,
      invitedUsers,
      suspendedUsers,
      lockedUsers,
      mfaUsers,
      auditTodayCount,
      failedLogins24h,
      failedLogins7d,
      apiKeysCount,
      activeRoles,
    ] = await Promise.all([
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.company.count({ where: whereCompany }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.company.count({ where: { ...whereCompany, status: 'ACTIVE' } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.company.count({ where: { ...whereCompany, status: 'SUSPENDED' } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({ where: { ...whereTenant } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({
          where: { ...whereTenant, status: 'ACTIVE' },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({
          where: { ...whereTenant, status: 'INVITED' },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({
          where: { ...whereTenant, status: 'SUSPENDED' },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({
          where: { ...whereTenant, status: 'LOCKED' },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({
          where: { ...whereTenant, mfaEnabled: true },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: { ...whereTenant, createdAt: { gte: twentyFourHoursAgo } },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            ...whereTenant,
            createdAt: { gte: twentyFourHoursAgo },
            OR: [
              { action: 'auth:login:failed' },
              { action: 'auth:mfa:failed' },
            ],
          },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            ...whereTenant,
            createdAt: { gte: sevenDaysAgo },
            OR: [
              { action: 'auth:login:failed' },
              { action: 'auth:mfa:failed' },
            ],
          },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.apiKey.count({ where: { ...whereTenant, isActive: true } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.role.findMany({
          where: whereTenant,
          select: { id: true, name: true, permissions: true },
        }),
      ),
    ]);

    // Calculate Security Score (0-100)
    let securityScore = 50; // base score
    const mfaAdoptionRate =
      totalUsers > 0 ? (mfaUsers / totalUsers) * 100 : 100;
    if (mfaAdoptionRate >= 80) securityScore += 20;
    else if (mfaAdoptionRate >= 50) securityScore += 10;
    else securityScore -= 10;

    // Check for overprivileged roles
    const wildcardRoles = activeRoles.filter(
      (r) =>
        Array.isArray(r.permissions) &&
        (r.permissions as string[]).includes('*'),
    );
    if (wildcardRoles.length <= 2) securityScore += 15;
    else securityScore -= 10;

    if (failedLogins24h === 0) securityScore += 15;
    else if (failedLogins24h < 5) securityScore += 5;
    else securityScore -= 10;

    securityScore = Math.max(0, Math.min(100, securityScore));

    // License & Quotas
    const config = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.findFirst({ where: whereTenant }),
    );
    const maxUsers = config?.maxUsers ?? 50;
    const storageQuotaMb = config?.storageQuotaMb ?? 10000;
    const apiRateLimit = config?.apiRateLimit ?? 1000;

    return {
      timestamp: now.toISOString(),
      scope:
        isSuperAdmin && companyId === 'GLOBAL'
          ? 'GLOBAL_SUPER_ADMIN'
          : `TENANT_${companyId}`,
      securityScore,
      tenantOverview: {
        total: totalTenants,
        active: activeTenants,
        suspended: suspendedTenants,
        trial: 0,
        mrrDistribution: { USD: totalTenants * 499 },
      },
      userStatistics: {
        total: totalUsers,
        active: activeUsers,
        invited: invitedUsers,
        suspended: suspendedUsers,
        locked: lockedUsers,
        mfaEnabledCount: mfaUsers,
        mfaAdoptionPercentage: Math.round(mfaAdoptionRate),
      },
      licenseUsage: {
        seatsUsed: activeUsers,
        seatsLimit: maxUsers,
        storageUsedMb: 350,
        storageLimitMb: storageQuotaMb,
        apiRateLimitPerMinute: apiRateLimit,
      },
      systemHealth: {
        database: 'ONLINE',
        redis: process.env.REDIS_URL ? 'ONLINE' : 'FALLBACK_MEMORY',
        queueDepth: 0,
        memoryUsageMb: Math.round(process.memoryUsage().rss / 1024 / 1024),
        uptimeSeconds: Math.round(process.uptime()),
      },
      apiUsage: {
        totalRequests24h: auditTodayCount * 12 + 1450, // simulated metrics based on logs
        errorRatePercentage: 0.12,
        p95LatencyMs: 42,
        activeApiKeys: apiKeysCount,
      },
      failedLogins: {
        last24Hours: failedLogins24h,
        last7Days: failedLogins7d,
      },
      alerts: [
        ...(lockedUsers > 0
          ? [
              {
                id: 'alert-lock',
                severity: 'HIGH',
                type: 'SECURITY',
                message: `${lockedUsers} user accounts are currently locked due to failed authentication.`,
              },
            ]
          : []),
        ...(mfaAdoptionRate < 50
          ? [
              {
                id: 'alert-mfa',
                severity: 'MEDIUM',
                type: 'COMPLIANCE',
                message: `MFA adoption is low (${Math.round(mfaAdoptionRate)}%). Consider requiring MFA in security policies.`,
              },
            ]
          : []),
        ...(activeUsers >= maxUsers * 0.9
          ? [
              {
                id: 'alert-quota',
                severity: 'WARNING',
                type: 'LICENSE',
                message: `Seat utilization is at or above 90% of your plan quota.`,
              },
            ]
          : []),
      ],
      auditMetrics: {
        recordedToday: auditTodayCount,
        topActions: [
          'auth:login:success',
          'dispatch:trip:create',
          'admin:user:invite',
        ],
      },
    };
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import {
  CreateEnterpriseFlagDto,
  UpdateEnterpriseFlagDto,
} from '../dto/enterprise-admin.dto';

@Injectable()
export class FeatureFlagAdminService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async getFlags(companyId: string) {
    const flags = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.featureFlag.findMany({
        where: {
          OR: [{ companyId }, { companyId: 'GLOBAL' }],
        },
        orderBy: { key: 'asc' },
      }),
    );

    return flags.map((f) => {
      const rules = (f.rules || {}) as Record<string, any>;
      return {
        id: f.id,
        companyId: f.companyId,
        key: f.key,
        name: f.name,
        description: f.description,
        isEnabled: f.isEnabled,
        isGlobal: f.companyId === 'GLOBAL' || !!rules.isGlobal,
        percentageRollout:
          typeof rules.percentageRollout === 'number'
            ? rules.percentageRollout
            : 100,
        killSwitch: !!rules.killSwitch,
        targetEnvironments: Array.isArray(rules.targetEnvironments)
          ? rules.targetEnvironments
          : ['production', 'staging', 'development'],
        rules: f.rules,
      };
    });
  }

  async upsertFlag(
    companyId: string,
    dto: CreateEnterpriseFlagDto,
    adminUserId: string,
  ) {
    const targetCompanyId = dto.isGlobal ? 'GLOBAL' : companyId;
    const rules = {
      isGlobal: !!dto.isGlobal,
      percentageRollout: dto.percentageRollout ?? 100,
      killSwitch: !!dto.killSwitch,
      targetEnvironments: dto.targetEnvironments ?? [
        'production',
        'staging',
        'development',
      ],
    };

    const flag = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.featureFlag.upsert({
        where: { companyId_key: { companyId: targetCompanyId, key: dto.key } },
        update: {
          name: dto.name,
          description: dto.description,
          isEnabled: dto.isEnabled ?? false,
          rules: rules as any,
        },
        create: {
          companyId: targetCompanyId,
          key: dto.key,
          name: dto.name,
          description: dto.description || dto.key,
          isEnabled: dto.isEnabled ?? false,
          rules: rules as any,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:feature_flag:upsert',
      entity: 'FeatureFlag',
      entityId: flag.id,
      userId: adminUserId,
      companyId: targetCompanyId,
      details: { dto, rules },
    });

    return flag;
  }

  async updateFlag(
    companyId: string,
    flagId: string,
    dto: UpdateEnterpriseFlagDto,
    adminUserId: string,
  ) {
    const flag = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.featureFlag.findFirst({
        where: { id: flagId, OR: [{ companyId }, { companyId: 'GLOBAL' }] },
      }),
    );
    if (!flag) throw new NotFoundException(`Feature flag ${flagId} not found`);

    const currentRules = (flag.rules || {}) as Record<string, any>;
    const updatedRules = {
      ...currentRules,
      percentageRollout:
        dto.percentageRollout ?? currentRules.percentageRollout ?? 100,
      killSwitch: dto.killSwitch ?? currentRules.killSwitch ?? false,
      targetEnvironments: dto.targetEnvironments ??
        currentRules.targetEnvironments ?? [
          'production',
          'staging',
          'development',
        ],
    };

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.featureFlag.update({
        where: { id: flagId },
        data: {
          isEnabled: dto.isEnabled ?? flag.isEnabled,
          rules: updatedRules as any,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:feature_flag:update',
      entity: 'FeatureFlag',
      entityId: flagId,
      userId: adminUserId,
      companyId: flag.companyId,
      details: { dto },
    });

    return updated;
  }

  async triggerKillSwitch(
    companyId: string,
    flagId: string,
    adminUserId: string,
  ) {
    return this.updateFlag(
      companyId,
      flagId,
      { isEnabled: false, killSwitch: true },
      adminUserId,
    );
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import {
  AssignPlanDto,
  SetTruckLimitDto,
  SetDriverLimitDto,
  SetBoostDto,
  SetUnlimitedModeDto,
} from '../dto/enterprise-admin.dto';

// ─── Default capacity per plan code ──────────────────────────────────────────
const PLAN_DEFAULTS: Record<
  string,
  { maxVehicles: number; maxDrivers: number }
> = {
  STARTER: { maxVehicles: 20, maxDrivers: 50 },
  GROWTH: { maxVehicles: 50, maxDrivers: 100 },
  PROFESSIONAL: { maxVehicles: 100, maxDrivers: 200 },
  BUSINESS: { maxVehicles: 250, maxDrivers: 500 },
  ENTERPRISE: { maxVehicles: 500, maxDrivers: 1000 },
  ENTERPRISE_PLUS: { maxVehicles: 1000, maxDrivers: 2000 },
  CUSTOM: { maxVehicles: 99999, maxDrivers: 99999 },
};

@Injectable()
export class LicenseAdminService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  // ─── Get full license overview for a tenant ─────────────────────────────────
  async getLicenseOverview(companyId: string) {
    const [
      company,
      config,
      tenantConfig,
      activeUsersCount,
      totalUsersCount,
      vehicleCount,
      driverCount,
    ] = await Promise.all([
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.company.findUnique({
          where: { id: companyId },
          include: { subscriptionPlan: true },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.tenantConfiguration.findUnique({ where: { companyId } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.tenantConfig.findUnique({ where: { companyId } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({ where: { companyId, status: 'ACTIVE' } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.user.count({ where: { companyId } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.vehicle.count({ where: { companyId } }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.driver.count({ where: { companyId } }),
      ),
    ]);

    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    const maxUsers = tenantConfig?.maxUsers ?? 50;
    const maxVehicles = tenantConfig?.maxVehicles ?? 20;
    const maxDrivers = tenantConfig?.maxDrivers ?? 50;
    const storageQuotaMb = tenantConfig?.storageQuotaMb ?? 10000;
    const apiRateLimit = tenantConfig?.apiRateLimit ?? 1000;
    const unlimitedMode = tenantConfig?.unlimitedMode ?? false;
    const boostExpiresAt = tenantConfig?.boostExpiresAt ?? null;
    const boostMaxVehicles = tenantConfig?.boostMaxVehicles ?? null;

    const now = new Date();
    const isInBoostPeriod = boostExpiresAt && boostExpiresAt > now;
    const effectiveVehicleLimit =
      isInBoostPeriod && boostMaxVehicles ? boostMaxVehicles : maxVehicles;

    const settings = (config?.settings || {}) as Record<string, any>;

    return {
      companyId,
      subscriptionPlan: company.subscriptionPlan || {
        id: 'default',
        name: 'Standard Enterprise',
        planCode: 'ENTERPRISE',
        price: 0,
      },
      capacity: {
        vehicles: {
          used: vehicleCount,
          limit: maxVehicles,
          effectiveLimit: effectiveVehicleLimit,
          utilizationPct: unlimitedMode
            ? 0
            : Math.round((vehicleCount / effectiveVehicleLimit) * 100),
          unlimitedMode,
          boost: isInBoostPeriod ? { boostMaxVehicles, boostExpiresAt } : null,
        },
        drivers: {
          used: driverCount,
          limit: maxDrivers,
          utilizationPct: Math.round((driverCount / maxDrivers) * 100),
        },
        users: {
          used: activeUsersCount,
          total: totalUsersCount,
          limit: maxUsers,
          utilizationPct: Math.round((activeUsersCount / maxUsers) * 100),
        },
        storage: {
          quotaMb: storageQuotaMb,
          usedMb: settings.storageUsedMb || 0,
          utilizationPct: Math.round(
            ((settings.storageUsedMb || 0) / storageQuotaMb) * 100,
          ),
        },
        api: {
          rateLimitPerMinute: apiRateLimit,
        },
      },
      trialMode: {
        isTrial: !!settings.isTrial,
        trialEndsAt: settings.trialEndsAt || null,
      },
      gracePeriod: {
        inGracePeriod: !!settings.inGracePeriod,
        gracePeriodDays: settings.gracePeriodDays || 14,
        gracePeriodEndsAt: settings.gracePeriodEndsAt || null,
      },
    };
  }

  // ─── Assign subscription plan ───────────────────────────────────────────────
  async assignPlan(companyId: string, dto: AssignPlanDto, adminUserId: string) {
    const company = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.findUnique({
        where: { id: companyId },
        include: { subscriptionPlan: true },
      }),
    );
    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    // Resolve capacity from plan defaults if not explicitly provided
    const plan = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.subscriptionPlan.findUnique({ where: { id: dto.subscriptionPlanId } }),
    );

    const planCode = plan?.planCode || 'STARTER';
    const planDefaults = PLAN_DEFAULTS[planCode] || PLAN_DEFAULTS['STARTER'];

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.update({
        where: { id: companyId },
        data: { subscriptionPlanId: dto.subscriptionPlanId },
      }),
    );

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.upsert({
        where: { companyId },
        update: {
          maxUsers: dto.seats ?? undefined,
          apiRateLimit: dto.apiRateLimit ?? undefined,
          storageQuotaMb: dto.storageQuotaMb ?? undefined,
          maxVehicles: plan?.defaultMaxVehicles ?? planDefaults.maxVehicles,
          maxDrivers: plan?.defaultMaxDrivers ?? planDefaults.maxDrivers,
          unlimitedMode: planCode === 'CUSTOM',
        },
        create: {
          companyId,
          maxUsers: dto.seats ?? 50,
          apiRateLimit: dto.apiRateLimit ?? 1000,
          storageQuotaMb: dto.storageQuotaMb ?? 10000,
          maxVehicles: plan?.defaultMaxVehicles ?? planDefaults.maxVehicles,
          maxDrivers: plan?.defaultMaxDrivers ?? planDefaults.maxDrivers,
          unlimitedMode: planCode === 'CUSTOM',
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:license:assign_plan',
      entity: 'Company',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: { planId: dto.subscriptionPlanId, planCode, planDefaults },
    });

    return this.getLicenseOverview(companyId);
  }

  // ─── Set truck/vehicle capacity override ────────────────────────────────────
  async setTruckLimit(
    companyId: string,
    dto: SetTruckLimitDto,
    adminUserId: string,
  ) {
    const company = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.findUnique({ where: { id: companyId } }),
    );
    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.upsert({
        where: { companyId },
        update: { maxVehicles: dto.maxVehicles },
        create: { companyId, maxVehicles: dto.maxVehicles },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:license:set_truck_limit',
      entity: 'TenantConfig',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: { maxVehicles: dto.maxVehicles, reason: dto.reason },
    });

    return this.getLicenseOverview(companyId);
  }

  // ─── Set driver capacity override ───────────────────────────────────────────
  async setDriverLimit(
    companyId: string,
    dto: SetDriverLimitDto,
    adminUserId: string,
  ) {
    const company = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.findUnique({ where: { id: companyId } }),
    );
    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.upsert({
        where: { companyId },
        update: { maxDrivers: dto.maxDrivers },
        create: { companyId, maxDrivers: dto.maxDrivers },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:license:set_driver_limit',
      entity: 'TenantConfig',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: { maxDrivers: dto.maxDrivers, reason: dto.reason },
    });

    return this.getLicenseOverview(companyId);
  }

  // ─── Set temporary capacity boost ──────────────────────────────────────────
  async setBoost(companyId: string, dto: SetBoostDto, adminUserId: string) {
    const company = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.findUnique({ where: { id: companyId } }),
    );
    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    const boostExpiresAt = new Date(dto.boostExpiresAt);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.upsert({
        where: { companyId },
        update: { boostMaxVehicles: dto.boostMaxVehicles, boostExpiresAt },
        create: {
          companyId,
          boostMaxVehicles: dto.boostMaxVehicles,
          boostExpiresAt,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:license:set_boost',
      entity: 'TenantConfig',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: {
        boostMaxVehicles: dto.boostMaxVehicles,
        boostExpiresAt: dto.boostExpiresAt,
        reason: dto.reason,
      },
    });

    return this.getLicenseOverview(companyId);
  }

  // ─── Toggle unlimited mode ──────────────────────────────────────────────────
  async setUnlimitedMode(
    companyId: string,
    dto: SetUnlimitedModeDto,
    adminUserId: string,
  ) {
    const company = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.company.findUnique({ where: { id: companyId } }),
    );
    if (!company) throw new NotFoundException(`Tenant ${companyId} not found`);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.upsert({
        where: { companyId },
        update: { unlimitedMode: dto.unlimited },
        create: { companyId, unlimitedMode: dto.unlimited },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:license:set_unlimited',
      entity: 'TenantConfig',
      entityId: companyId,
      userId: adminUserId,
      companyId,
      details: { unlimited: dto.unlimited, reason: dto.reason },
    });

    return this.getLicenseOverview(companyId);
  }

  // ─── List all subscription plans ────────────────────────────────────────────
  async listPlans() {
    return this.prisma.runAsSystem(
      '[LicenseAdminService.listPlans] Internal service operation bypass',
      async (tx) =>
        tx.subscriptionPlan.findMany({
          orderBy: { defaultMaxVehicles: 'asc' },
        }),
    );
  }

  // ─── Get tenant usage dashboard ─────────────────────────────────────────────
  async getUsageDashboard(companyId: string) {
    return this.getLicenseOverview(companyId);
  }

  // ─── List all tenants with license summary (for Super Admin Center) ──────────
  async listAllTenantsWithLicense() {
    const companies = await this.prisma.runAsSystem(
      '[LicenseAdminService.listAllTenantsWithLicense] Internal service operation bypass',
      async (tx) =>
        tx.company.findMany({
          include: {
            subscriptionPlan: true,
            tenantConfiguration: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 200,
        }),
    );

    const companyIds = companies.map((c) => c.id);

    const configs = await this.prisma.runAsSystem(
      '[LicenseAdminService.listAllTenantsWithLicense] Internal service operation bypass',
      async (tx) =>
        tx.tenantConfig.findMany({ where: { companyId: { in: companyIds } } }),
    );
    const configMap = new Map(configs.map((c) => [c.companyId, c]));

    const vehicleCounts = await this.prisma.runAsSystem(
      '[LicenseAdminService.listAllTenantsWithLicense] Internal service operation bypass',
      async (tx) =>
        tx.vehicle.groupBy({
          by: ['companyId'],
          where: { companyId: { in: companyIds } },
          _count: true,
        }),
    );
    const vehicleCountMap = new Map(
      vehicleCounts.map((v) => [v.companyId, v._count]),
    );

    const driverCounts = await this.prisma.runAsSystem(
      '[LicenseAdminService.listAllTenantsWithLicense] Internal service operation bypass',
      async (tx) =>
        tx.driver.groupBy({
          by: ['companyId'],
          where: { companyId: { in: companyIds } },
          _count: true,
        }),
    );
    const driverCountMap = new Map(
      driverCounts.map((d) => [d.companyId, d._count]),
    );

    const summaries = companies.map((company) => {
      const config = configMap.get(company.id);
      const vehicleCount = vehicleCountMap.get(company.id) ?? 0;
      const driverCount = driverCountMap.get(company.id) ?? 0;

      return {
        id: company.id,
        name: company.name,
        status: company.status,
        plan: company.subscriptionPlan?.name || 'No Plan',
        planCode: company.subscriptionPlan?.planCode || 'NONE',
        maxVehicles: config?.maxVehicles ?? 20,
        vehicleCount,
        maxDrivers: config?.maxDrivers ?? 50,
        driverCount,
        unlimitedMode: config?.unlimitedMode ?? false,
        boostExpiresAt: config?.boostExpiresAt ?? null,
        createdAt: company.createdAt,
      };
    });

    return summaries;
  }
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { AuditService } from '../../platform/audit/audit.service';
import {
  CreateDepartmentDto,
  UpdateDepartmentDto,
  CreateTeamDto,
  UpdateTeamDto,
  CreateCostCenterDto,
  UpdateCostCenterDto,
} from '../dto/enterprise-admin.dto';

@Injectable()
export class OrgAdminService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  async getOrgOverview(companyId: string) {
    const [branches, warehouses, departments, teams, costCenters] =
      await Promise.all([
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.branch.findMany({ where: { companyId } }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.warehouse.findMany({ where: { companyId } }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.department.findMany({ where: { companyId } }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.team.findMany({ where: { companyId } }),
        ),
        this.prisma.runAsTenant(companyId, async (tx) =>
          tx.costCenter.findMany({ where: { companyId } }),
        ),
      ]);

    return {
      companyId,
      branches,
      warehouses,
      departments,
      teams,
      costCenters,
    };
  }

  async getDepartments(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.findMany({
        where: { companyId },
        include: { _count: { select: { users: true, teams: true } } },
        orderBy: { name: 'asc' },
      }),
    );
  }

  async createDepartment(
    companyId: string,
    dto: CreateDepartmentDto,
    adminUserId: string,
  ) {
    const existing = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.findFirst({
        where: { companyId, name: dto.name },
      }),
    );
    if (existing)
      throw new ConflictException(
        `Department ${dto.name} already exists in tenant`,
      );

    const dept = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.create({
        data: {
          companyId,
          name: dto.name,
          code: dto.code,
          description: dto.description,
          managerId: dto.managerId,
        },
      }),
    );

    await this.audit.logEvent({
      action: 'admin:org:create_department',
      entity: 'Department',
      entityId: dept.id,
      userId: adminUserId,
      companyId,
      details: { department: dto },
    });

    return dept;
  }

  async updateDepartment(
    companyId: string,
    deptId: string,
    dto: UpdateDepartmentDto,
    adminUserId: string,
  ) {
    const existing = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.findFirst({
        where: { id: deptId, companyId },
      }),
    );
    if (!existing)
      throw new NotFoundException(`Department ${deptId} not found`);

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.update({
        where: { id: deptId },
        data: dto,
      }),
    );

    await this.audit.logEvent({
      action: 'admin:org:update_department',
      entity: 'Department',
      entityId: deptId,
      userId: adminUserId,
      companyId,
      details: { dto },
    });

    return updated;
  }

  async deleteDepartment(
    companyId: string,
    deptId: string,
    adminUserId: string,
  ) {
    const existing = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.findFirst({
        where: { id: deptId, companyId },
      }),
    );
    if (!existing)
      throw new NotFoundException(`Department ${deptId} not found`);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.department.delete({ where: { id: deptId } }),
    );

    await this.audit.logEvent({
      action: 'admin:org:delete_department',
      entity: 'Department',
      entityId: deptId,
      userId: adminUserId,
      companyId,
      details: { name: existing.name },
    });

    return { success: true };
  }

  async getTeams(companyId: string, departmentId?: string) {
    const where: any = { companyId };
    if (departmentId) where.departmentId = departmentId;
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.team.findMany({
        where,
        include: {
          department: { select: { id: true, name: true } },
          _count: { select: { users: true } },
        },
        orderBy: { name: 'asc' },
      }),
    );
  }

  async createTeam(companyId: string, dto: CreateTeamDto, adminUserId: string) {
    const existing = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.team.findFirst({
        where: { companyId, name: dto.name },
