      action: 'admin:security_policy:update',
      entity: 'TenantConfiguration',
      entityId: updated.id,
      userId: adminUserId,
      companyId,
      details: { policies: dto },
    });

    return {
      companyId,
      policies: updatedPolicies,
      updatedAt: updated.updatedAt,
    };
  }
}

