        },
      ],
      exception_handling: [
        {
          stepId: 'step_1',
          name: 'Exception Classification',
          description: 'Classify the exception type and severity level',
          requiresApproval: false,
          status: 'PENDING',
        },
        {
          stepId: 'step_2',
