import { Processor, WorkerHost, OnWorkerEvent } from '@nestjs/bullmq';
import { Logger } from '@nestjs/common';
import { Job } from 'bullmq';
import { PrismaService } from '../../prisma/prisma.service';
import axios from 'axios';
import { validateSsrfSafeUrl } from '../../platform/security/ssrf-protector.util';
import * as crypto from 'crypto';
import { URL } from 'url';

// @ts-ignore: reserved for future use
function _validateWebhookUrl(targetUrl: string) {
  const parsed = new URL(targetUrl);
  const blockedHosts = [
    'localhost',
    '127.0.0.1',
    '0.0.0.0',
    '169.254.169.254',
    '::1',
  ];
  if (
    blockedHosts.includes(parsed.hostname) ||
    parsed.hostname.endsWith('.internal')
  ) {
    throw new Error(
      'SSRF Blocked: Cannot dispatch webhooks to internal infrastructure.',
    );
  }
}

@Processor('webhooks_v2', { concurrency: 50 })
export class WebhookProcessor extends WorkerHost {
  private readonly logger = new Logger(WebhookProcessor.name);

  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async process(job: Job<any, any, string>): Promise<any> {
    if (job.name === 'deliver_webhook') {
      // @ts-ignore: reserved for future use
      const { _endpointId, url, secret, payload, companyId } = job.data;
      const signature = this.generateSignature(payload, secret);

      // 1. Create a WebhookDelivery record (or update if retrying)
      const deliveryId = await this.recordDeliveryAttempt(
        job,
        companyId,
        url,
        payload.eventType,
        payload,
      );

      try {
        if (!(await validateSsrfSafeUrl(url))) {
          throw new Error(
            'SSRF attempt blocked: Webhook URL is invalid or targets restricted internal IPs',
          );
        }

        const response = await axios.post(url, payload, {
          headers: {
            'Content-Type': 'application/json',
            'X-PariLink-Signature': signature,
            'X-PariLink-Delivery': deliveryId,
            'X-PariLink-Event': payload.eventType,
            'X-PariLink-Retry-Count': job.attemptsMade,
          },
          timeout: 10000, // 10s timeout
          maxRedirects: 0, // Prevent SSRF bypass via HTTP redirects to internal IPs
        });

        // 2. Mark Delivery Success
        await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.webhookDelivery.update({
            where: { id: deliveryId },
            data: {
              status: 'SUCCESS',
              httpStatus: response.status,
              responseBody: JSON.stringify(response.data).substring(0, 1000), // Trim body
            },
          }),
        );

        this.logger.log(`Webhook delivery ${deliveryId} SUCCESS to ${url}`);
        return { deliveryId, status: 'SUCCESS' };
      } catch (error: any) {
        // 3. Handle Failure and Retries
        const httpStatus = error.response?.status || 500;
        const responseBody = error.response?.data
          ? JSON.stringify(error.response.data)
          : error.message;

        const isLastAttempt = job.attemptsMade >= job.opts.attempts! - 1;
        const newStatus = isLastAttempt ? 'DEAD_LETTER' : 'FAILED';

        await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.webhookDelivery.update({
            where: { id: deliveryId },
            data: {
              status: newStatus,
              httpStatus,
              responseBody: responseBody.substring(0, 1000),
              retryCount: job.attemptsMade + 1,
            },
          }),
        );

        this.logger.error(
          `Webhook delivery ${deliveryId} FAILED to ${url}. Attempt ${job.attemptsMade + 1}`,
        );

        if (!isLastAttempt) {
          throw error; // Throwing triggers BullMQ to retry (Exponential Backoff)
        }
      }
    }
  }

  private generateSignature(payload: any, secret: string): string {
    const stringifiedPayload = JSON.stringify(payload);
    return crypto
      .createHmac('sha256', secret)
      .update(stringifiedPayload)
      .digest('hex');
  }

  private async recordDeliveryAttempt(
    job: Job,
    companyId: string,
    url: string,
    eventTopic: string,
    payload: any,
  ): Promise<string> {
    const endpointId = job.data.endpointId;

    if (job.attemptsMade === 0) {
      // 1. Verify tenant ownership (IDOR protection for background workers)
      if (endpointId) {
        const endpoint = await this.prisma.runAsTenant(companyId, async (tx) =>
          tx.webhookEndpoint.findFirst({
            where: { id: endpointId, companyId },
          }),
        );
        if (!endpoint) {
          throw new Error(
            `Unauthorized: Endpoint ${endpointId} does not belong to company ${companyId}`,
          );
        }
      }

      // First attempt
      const delivery = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.webhookDelivery.create({
          data: {
            companyId,
            direction: 'OUTGOING',
            endpointUrl: url,
            eventTopic,
            payload,
            status: 'PENDING',
            retryCount: 0,
          },
        }),
      );
      // Store deliveryId in job data for retries
      await job.updateData({ ...job.data, deliveryId: delivery.id });
      return delivery.id;
    } else {
      // Retry attempt
      return job.data.deliveryId;
    }
  }

  @OnWorkerEvent('failed')
  onFailed(job: Job, error: Error) {
    this.logger.error(`Job ${job.id} failed: ${error.message}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../../prisma/prisma.service';
import { OnEvent } from '@nestjs/event-emitter';
import * as crypto from 'crypto';
import { AuditService } from '../../platform/audit/audit.service';

const SUPPORTED_EVENTS = [
  'load.created',
  'load.updated',
  'load.completed',
  'trip.created',
  'trip.started',
  'trip.completed',
  'driver.created',
  'driver.updated',
  'invoice.created',
  'invoice.paid',
  'workflow.rule.passed',
  'workflow.rule.failed',
  'dispatch.created',
  'dispatch.updated',
];

@Injectable()
export class WebhookService {
  private readonly logger = new Logger(WebhookService.name);

  constructor(
    @InjectQueue('webhooks_v2') private readonly webhookQueue: Queue,
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  @OnEvent('**')
  async handleDomainEvent(event: string, payload: any) {
    if (!SUPPORTED_EVENTS.includes(event)) {
      return;
    }

    const companyId = payload?.companyId || payload?.data?.companyId;
    if (!companyId) {
      this.logger.warn(
        `Event ${event} missing companyId, cannot dispatch webhooks.`,
      );
      return;
    }

    this.logger.log(`Dispatching event ${event} for company ${companyId}`);

    const endpoints = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.webhookEndpoint.findMany({
        where: {
          companyId,
          isActive: true,
        },
      }),
    );

    const jobs = [];

    for (const endpoint of endpoints) {
      const subscribedEvents = endpoint.events as string[];
      if (subscribedEvents.includes('*') || subscribedEvents.includes(event)) {
        // Construct the Payload
        const webhookPayload = {
          eventId: crypto.randomUUID(),
          eventType: event,
          timestamp: new Date().toISOString(),
          companyId,
          data: payload,
        };

        jobs.push({
          name: 'deliver_webhook',
          data: {
            endpointId: endpoint.id,
            url: endpoint.url,
            secret: endpoint.secret,
            payload: webhookPayload,
            companyId,
          },
          opts: {
            attempts: endpoint.retryCount > 0 ? endpoint.retryCount : 5,
            backoff: { type: 'exponential', delay: 2000 },
          },
        });
      }
    }

    if (jobs.length > 0) {
      await this.webhookQueue.addBulk(jobs);
      this.logger.log(
        `Queued ${jobs.length} webhook deliveries for event ${event}`,
      );
    }
  }

  // --- CRUD Operations ---

  async createWebhook(
    companyId: string,
    userId: string,
    data: { url: string; events: string[] },
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const secret = `whsec_${crypto.randomBytes(24).toString('hex')}`;

      const endpoint = await tx.webhookEndpoint.create({
        data: {
          companyId,
          url: data.url,
          secret,
          events: data.events,
        },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'WebhookEndpoint',
        entityId: endpoint.id,
        action: 'CREATE',
        afterValue: endpoint,
      });

      return endpoint;
    });
  }

  async getWebhooks(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.webhookEndpoint.findMany({
        where: { companyId },
      }),
    );
  }

  async deleteWebhook(companyId: string, userId: string, endpointId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const endpoint = await tx.webhookEndpoint.update({
        where: { id: endpointId },
        data: { isActive: false },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'WebhookEndpoint',
        entityId: endpoint.id,
        action: 'DELETE',
        afterValue: { isActive: false },
      });

      return endpoint;
    });
  }
}

