import { Injectable, BadRequestException } from '@nestjs/common';
import { Issuer, Client, TokenSet } from 'openid-client';
import type { Request } from 'express';
import * as crypto from 'crypto';

@Injectable()
export class OidcService {
  async getClient(idp: any): Promise<Client> {
    if (!idp.issuer || !idp.clientId || !idp.clientSecret) {
      throw new BadRequestException('OIDC configuration incomplete');
    }

    const issuer = await Issuer.discover(idp.issuer).catch(() => {
      // Fallback if discovery fails but endpoints are provided manually
      return new Issuer({
        issuer: idp.issuer,
        authorization_endpoint: idp.authorizationEndpoint,
        token_endpoint: idp.tokenEndpoint,
        userinfo_endpoint: idp.userinfoEndpoint,
        jwks_uri: idp.jwksUri,
      });
    });

    return new issuer.Client({
      client_id: idp.clientId,
      client_secret: idp.clientSecret,
      redirect_uris: [
        `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/oidc/${idp.id}`,
      ],
      response_types: ['code'],
    });
  }

  async generateLoginUrl(idp: any, req: Request): Promise<string> {
    const client = await this.getClient(idp);

    // Generate cryptographically secure nonce — stored in session for validation
    const nonce = crypto.randomUUID();
    const state = (req.query.state as string) || crypto.randomUUID();

    // Store nonce and state in session for callback validation
    (req as any).session = (req as any).session || {};
    (req as any).session.oidcNonce = nonce;
    (req as any).session.oidcState = state;

    const url = client.authorizationUrl({
      scope: 'openid email profile',
      state,
      nonce,
    });

    return url;
  }

  async validateCallback(idp: any, _input: any, req: Request) {
    const client = await this.getClient(idp);
    const params = client.callbackParams(req);

    // Retrieve nonce from session — prevents replay and CSRF
    const sessionNonce = (req as any).session?.oidcNonce;
    if (!sessionNonce) {
      throw new BadRequestException(
        'OIDC session state missing — possible CSRF',
      );
    }

    const tokenSet: TokenSet = await client.callback(
      `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/oidc/${idp.id}`,
      params,
      { nonce: sessionNonce },
    );

    // Clear session nonce after use (one-time use)
    delete (req as any).session.oidcNonce;
    delete (req as any).session.oidcState;

    const claims = tokenSet.claims();

    return {
      id: claims.sub,
      email: claims.email,
      firstName: claims.given_name || claims.name?.split(' ')[0],
      lastName: claims.family_name || claims.name?.split(' ')[1],
      sessionId: claims.sid || tokenSet.session_state,
      groups: claims.groups || claims.roles, // Entra ID/Okta usually puts this in roles or groups claim
    };
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { SAML } from '@node-saml/node-saml';
import type { Request } from 'express';

@Injectable()
export class SamlService {
  getSamlStrategy(idp: any): SAML {
    if (!idp.entryPoint || !idp.cert) {
      throw new BadRequestException('SAML configuration incomplete');
    }

    return new SAML({
      callbackUrl: `${process.env.APP_URL || 'http://localhost:3000'}/api/v1/auth/sso/callback/saml/${idp.id}`,
      entryPoint: idp.entryPoint,
      issuer: process.env.APP_URL || 'http://localhost:3000',
      cert: idp.cert, // The IdP public certificate
      identifierFormat:
        idp.identifierFormat ||
        'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress',
      authnContext: idp.authnContext
        ? [idp.authnContext]
        : ['urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport'],
    } as any);
  }

  async generateLoginUrl(idp: any, req: Request): Promise<string> {
    const saml = this.getSamlStrategy(idp);
    try {
      return await saml.getAuthorizeUrlAsync(
        (req.query.state as string) || '',
        undefined,
        {},
      );
    } catch (err: any) {
      throw err instanceof Error
        ? err
        : new Error(err?.message || 'Failed to generate SAML authorize URL');
    }
  }

  async validateResponse(idp: any, samlResponse: string, _req: Request) {
    const saml = this.getSamlStrategy(idp);
    const proxyReq = {
      body: { SAMLResponse: samlResponse },
    };

    try {
      const { profile } = await saml.validatePostResponseAsync(proxyReq.body);
      if (!profile) {
        throw new Error('No profile in SAML response');
      }
      return {
        id: profile.nameID || profile.nameIDFormat,
        email: profile.email || profile.nameID,
        firstName: profile.firstName || profile.givenName,
        lastName: profile.lastName || profile.surname,
        sessionId: profile.sessionIndex,
        groups: profile.groups || profile.role,
      };
    } catch (err: any) {
      throw err instanceof Error
        ? err
        : new Error(err?.message || 'SAML Validation Failed');
    }
  }
}

import { CreateSsoDto } from '../dto/sso.dto';
import {
  Controller,
  Get,
  Post,
  Req,
  Res,
  Param,
  Query,
  Body,
} from '@nestjs/common';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { SsoService } from './sso.service';
import type { Request, Response } from 'express';

@ApiTags('auth/sso')
@Controller('auth/sso')
export class SsoController {
  constructor(private readonly ssoService: SsoService) {}

  @Get('login/:idpId')
  @ApiOperation({ summary: 'Initiate SSO Login' })
  async initiateLogin(
    @Param('idpId') idpId: string,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const redirectUrl = await this.ssoService.generateLoginUrl(idpId, req);
    return res.redirect(redirectUrl);
  }

  @Post('callback/saml/:idpId')
  @ApiOperation({ summary: 'SAML Callback URL' })
  async samlCallback(
    @Param('idpId') idpId: string,
    @Body() body: CreateSsoDto,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleSamlCallback(idpId, body, req);
    return this.handleAuthResult(result, res);
  }

  @Get('callback/oidc/:idpId')
  @ApiOperation({ summary: 'OIDC Callback URL' })
  async oidcCallback(
    @Param('idpId') idpId: string,
    @Query() query: any,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleOidcCallback(idpId, query, req);
    return this.handleAuthResult(result, res);
  }

  @Post('callback/oidc/:idpId')
  @ApiOperation({ summary: 'OIDC Callback URL (POST)' })
  async oidcCallbackPost(
    @Param('idpId') idpId: string,
    @Body() body: CreateSsoDto,
    @Res() res: Response,
    @Req() req: Request,
  ) {
    const result = await this.ssoService.handleOidcCallback(idpId, body, req);
    return this.handleAuthResult(result, res);
  }

  private handleAuthResult(result: any, res: Response) {
    if (result.error) {
      return res.redirect(`/login?error=${encodeURIComponent(result.error)}`);
    }

    if (result.requiresMfa) {
      // Need a way to pass the partial token to frontend. Usually URL params or cookie.
      res.cookie('mfa_token', result.mfaToken, {
        domain: process.env.COOKIE_DOMAIN || undefined,
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        maxAge: 15 * 60 * 1000,
      });
      return res.redirect(`/login/mfa?userId=${result.user.id}`);
    }

    // Set refresh token
    res.cookie('refresh_token', result.refresh_token, {
      domain: process.env.COOKIE_DOMAIN || undefined,
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });

    // Pass access token in URL fragment or a secure cookie. Standard is returning to a success page.
    return res.redirect(`/sso-success?token=${result.access_token}`);
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';

/**
 * Interface representing a Digital Worker capable of executing a graph node.
 */
export interface IDigitalWorker {
  name: string; // e.g. 'Dispatcher_AI', 'Finance_AI'
  executeTask(taskId: string, inputs: any): Promise<any>;
  rollbackTask(taskId: string, context: any): Promise<void>;
}

@Injectable()
export class DigitalWorkerRegistry {
  private readonly logger = new Logger(DigitalWorkerRegistry.name);
  private workers: Map<string, IDigitalWorker> = new Map();

  registerWorker(worker: IDigitalWorker) {
    if (this.workers.has(worker.name)) {
      this.logger.warn(`Worker ${worker.name} is already registered.`);
      return;
    }
    this.workers.set(worker.name, worker);
    this.logger.log(`Registered Digital Worker: ${worker.name}`);
  }

  getWorker(name: string): IDigitalWorker {
    const worker = this.workers.get(name);
    if (!worker) {
      throw new NotFoundException(
        `Digital Worker '${name}' not found in registry.`,
      );
    }
    return worker;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { DigitalWorkerRegistry } from './digital-worker.registry';
import { EventService } from '../../platform/events/event.service';

@Injectable()
export class ExecutionService {
  private readonly logger = new Logger(ExecutionService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly registry: DigitalWorkerRegistry,
    private readonly eventService: EventService,
  ) {}

  /**
   * Initializes the execution of a Graph-based Workflow (AI Decision converted to Action)
   */
  async startExecution(executionId: string) {
    this.logger.log(`Starting WorkflowExecution: ${executionId}`);

    // In a real DAG, we would identify root nodes and execute them.
    // For MVP, we fetch PENDING steps and execute them sequentially or in parallel based on graph dependencies.
    const steps = await this.prisma.runAsSystem(
      '[ExecutionService.startExecution] Internal service operation bypass',
      async (tx) =>
        tx.workflowExecutionStep.findMany({
          where: { executionId, status: 'PENDING' },
          orderBy: { executedAt: 'asc' }, // Simplified execution order
        }),
    );

    for (const step of steps) {
      await this.executeStep(step.id);
    }
  }

  /**
   * Executes a single step using the assigned Digital Worker
   */
  private async executeStep(stepId: string) {
    const step = await this.prisma.runAsSystem(
      '[ExecutionService.executeStep] Internal service operation bypass',
      async (tx) =>
        tx.workflowExecutionStep.findUnique({
          where: { id: stepId },
          include: { execution: true },
        }),
    );

    if (!step) return;

    this.logger.log(`Executing step ${step.nodeId} for worker ${step.owner}`);

    try {
      // Find the specific AI Worker responsible for this node
      const worker = this.registry.getWorker(step.owner || 'System_Default');

      const outputs = await worker.executeTask(step.nodeId, step.inputs);

      await this.prisma.runAsSystem(
        '[ExecutionService.executeStep] Internal service operation bypass',
        async (tx) =>
          tx.workflowExecutionStep.update({
            where: { id: stepId },
            data: { status: 'SUCCESS', outputs },
          }),
      );

      // Realtime Progress Tracking update
      this.eventService.publish('Execution.StepUpdated', {
        tenantId: step.execution.companyId,
        payload: { stepId, status: 'SUCCESS', executionId: step.executionId },
      });
    } catch (error) {
      this.logger.error(
        `Execution failed for step ${step.nodeId}: ${(error as Error).message}`,
      );
      await this.handleStepFailure(step, (error as Error).message);
    }
  }

  /**
   * Handles failure through Retry limits, then cascades to Rollback Compensation
   */
  private async handleStepFailure(step: any, errorMessage: string) {
    // 1. Retry Strategy
    const maxRetries = 3;
    if (step.retryCount < maxRetries) {
      this.logger.warn(
        `Retrying step ${step.nodeId} (Attempt ${step.retryCount + 1})`,
      );
      await this.prisma.runAsSystem(
        '[ExecutionService.handleStepFailure] Internal service operation bypass',
        async (tx) =>
          tx.workflowExecutionStep.update({
            where: { id: step.id },
            data: { retryCount: step.retryCount + 1, error: errorMessage },
          }),
      );
      // Exponential Backoff in real implementation, here we re-execute immediately
      return this.executeStep(step.id);
    }

    // 2. Rollback Strategy (Compensation)
    this.logger.error(
      `Max retries reached for step ${step.nodeId}. Initiating Rollback.`,
    );
    await this.prisma.runAsSystem(
      '[ExecutionService.handleStepFailure] Internal service operation bypass',
      async (tx) =>
        tx.workflowExecutionStep.update({
          where: { id: step.id },
          data: { status: 'FAILED', error: errorMessage },
        }),
    );

    if (step.rollbackAction) {
      try {
        const worker = this.registry.getWorker(step.owner || 'System_Default');
        await worker.rollbackTask(step.nodeId, step.inputs);
        this.logger.log(`Successfully rolled back step ${step.nodeId}`);
      } catch (rollbackError) {
        this.logger.error(
          `CRITICAL: Rollback failed for ${step.nodeId}: ${(rollbackError as Error).message}`,
        );
      }
    }

    // Fail the entire execution
    await this.prisma.runAsSystem(
      '[ExecutionService.handleStepFailure] Internal service operation bypass',
      async (tx) =>
        tx.workflowExecution.update({
          where: { id: step.executionId },
          data: { status: 'FAILED', error: errorMessage },
        }),
    );

    this.eventService.publish('Execution.StepUpdated', {
      tenantId: step.execution.companyId,
      payload: {
        stepId: step.id,
        status: 'FAILED',
        executionId: step.executionId,
      },
    });
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class BackgroundJobsService {
  constructor(private prisma: PrismaService) {}

  async createJob(
    companyId: string,
    userId: string,
    type: string,
    metadata: any = {},
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.create({
        data: {
          companyId,
          userId,
          type,
          status: 'PENDING',
          progress: 0,
          metadata,
        },
      }),
    );
  }

  async getJobs(companyId: string, userId: string, limit: number = 20) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.findMany({
        where: { companyId, userId },
        orderBy: { createdAt: 'desc' },
        take: limit,
      }),
    );
  }

  async getActiveJobs(companyId: string, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.backgroundJob.findMany({
        where: {
          companyId,
          userId,
          status: { in: ['PENDING', 'PROCESSING'] },
        },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }

  async updateJobProgress(
    jobId: string,
    progress: number,
    status: string = 'PROCESSING',
  ) {
    return this.prisma.runAsSystem(
      '[BackgroundJobsService.updateJobProgress] Background job bypass',
      async (tx) =>
        tx.backgroundJob.update({
          where: { id: jobId },
          data: {
            progress,
            status,
            ...(status === 'PROCESSING' && progress === 0
              ? { startedAt: new Date() }
              : {}),
          },
        }),
    );
  }

  async completeJob(jobId: string, result: any = {}) {
    return this.prisma.runAsSystem(
      '[BackgroundJobsService.completeJob] Background job bypass',
      async (tx) =>
        tx.backgroundJob.update({
          where: { id: jobId },
          data: {
            status: 'COMPLETED',
            progress: 100,
            completedAt: new Date(),
            result,
          },
        }),
    );
  }

  async failJob(jobId: string, error: string) {
    return this.prisma.runAsSystem(
      '[BackgroundJobsService.failJob] Background job bypass',
      async (tx) =>
        tx.backgroundJob.update({
          where: { id: jobId },
          data: {
            status: 'FAILED',
            completedAt: new Date(),
            error,
          },
        }),
    );
  }

  async cancelJob(jobId: string) {
    return this.prisma.runAsSystem(
      '[BackgroundJobsService.cancelJob] Background job bypass',
      async (tx) =>
        tx.backgroundJob.update({
          where: { id: jobId },
          data: {
            status: 'CANCELLED',
            completedAt: new Date(),
          },
        }),
    );
  }
}

