// @ts-nocheck
import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { AuditService } from '../platform/audit/audit.service';
import { EventStoreService } from '../platform/digital-twin/event-store.service';

import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';

@Injectable()
export class BrokerService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: AuditService,
    private readonly eventStore: EventStoreService,
  ) {}

  async createCarrier(companyId: string, data: any, userId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const carrier = await tx.externalCarrier.create({
        data: {
          companyId,
          name: data.name,
          dotNumber: data.dotNumber,
          mcNumber: data.mcNumber,
          contactName: data.contactName,
          email: data.email,
          phone: data.phone,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Broker',
          entityType: 'ExternalCarrier',
          entityId: carrier.id,
          action: 'CREATE',
          details: { name: carrier.name },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'EXTERNAL_CARRIER',
        streamId: carrier.id,
        eventType: 'CarrierCreated',
        payload: { name: carrier.name },
        userId,
      });

      return carrier;
    });
  }

  async getCarriers(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.externalCarrier.findMany({ where: { companyId } }),
    );
  }

  async postToLoadBoard(
    companyId: string,
    tripId: string,
    data: any,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Check if trip exists
      const trip = await tx.trip.findUnique({
        where: { id: tripId, companyId },
      });
      if (!trip) throw new NotFoundException('Trip not found');

      const boardItem = await tx.loadBoardItem.create({
        data: {
          companyId,
          tripId,
          origin: data.origin,
          destination: data.destination,
          pickupTime: new Date(data.pickupTime),
          deliveryTime: new Date(data.deliveryTime),
          weight: data.weight,
          equipmentType: data.equipmentType,
          maxRate: data.maxRate,
          status: 'OPEN',
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Broker',
          entityType: 'LoadBoardItem',
          entityId: boardItem.id,
          action: 'CREATE',
          details: { tripId: boardItem.tripId },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'LOAD_BOARD_ITEM',
        streamId: boardItem.id,
        eventType: 'LoadBoardItemCreated',
        payload: { tripId: boardItem.tripId },
        userId,
      });

      return boardItem;
    });
  }

  async getLoadBoard(companyId: string, status?: string, page = 1, limit = 10) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { skip, take } = getPaginationParams(page, limit);

      const where: any = { companyId };
      if (status) where.status = status;

      const [data, total] = await Promise.all([
        tx.loadBoardItem.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: { trip: true, bids: true },
        }),
        tx.loadBoardItem.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async submitBid(
    companyId: string,
    loadBoardItemId: string,
    carrierId: string,
    data: any,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const bid = await tx.carrierBid.create({
        data: {
          companyId,
          loadBoardItemId,
          carrierId,
          bidAmount: data.bidAmount,
          notes: data.notes,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Broker',
          entityType: 'CarrierBid',
          entityId: bid.id,
          action: 'CREATE',
          details: { carrierId, loadBoardItemId, bidAmount: data.bidAmount },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'CARRIER_BID',
        streamId: bid.id,
        eventType: 'CarrierBidSubmitted',
        payload: { carrierId, loadBoardItemId, bidAmount: data.bidAmount },
        userId,
      });

      return bid;
    });
  }

  async acceptBid(companyId: string, bidId: string, userId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const bid = await tx.carrierBid.findUnique({
        where: { id: bidId, companyId },
        include: { loadBoardItem: true },
      });

      if (!bid) throw new NotFoundException('Bid not found');
      if (bid.status !== 'PENDING')
        throw new BadRequestException('Bid is not pending');

      // Reject all other bids for this load
      await tx.carrierBid.updateMany({
        where: {
          companyId,
          loadBoardItemId: bid.loadBoardItemId,
          id: { not: bidId },
        },
        data: { status: 'REJECTED' },
      });

      // Accept this bid
      const acceptedBid = await tx.carrierBid.update({
        where: { id: bidId, companyId },
        data: { status: 'ACCEPTED' },
      });

      // Update Load Board Item
      const load = await tx.loadBoardItem.update({
        where: { id: bid.loadBoardItemId, companyId },
        data: {
          status: 'ASSIGNED',
          assignedToId: bid.carrierId,
          assignedRate: bid.bidAmount,
          margin: (bid.loadBoardItem.maxRate || 0) - bid.bidAmount,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Broker',
          entityType: 'CarrierBid',
          entityId: bid.id,
          action: 'ACCEPT',
          details: { loadBoardItemId: bid.loadBoardItemId },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'CARRIER_BID',
        streamId: bid.id,
        eventType: 'CarrierBidAccepted',
        payload: { loadBoardItemId: bid.loadBoardItemId },
        userId,
      });

      return { bid: acceptedBid, load };
    });
  }
}

import {
  Controller,
  Post,
  Get,
  Param,
  UseInterceptors,
  UploadedFile,
  Res,
  BadRequestException,
  Req,
  UseGuards,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import type { Response, Request } from 'express';
import { BulkImportService, ImportType } from './bulk-import.service';
import { ApiTags, ApiConsumes, ApiBody, ApiBearerAuth } from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';

const VALID_TYPES: ImportType[] = [
  'vehicles',
  'drivers',
  'customers',
  'vendors',
  'opening-balances',
];

@ApiTags('Bulk Import')
@ApiBearerAuth('JWT-auth')
@UseGuards(JwtAuthGuard)
@Controller('import')
export class BulkImportController {
  constructor(private readonly importService: BulkImportService) {}

  /**
   * Download a template .xlsx file with the correct column headers.
   * GET /api/v1/import/:type/template
   */
  @Get(':type/template')
  downloadTemplate(@Param('type') type: string, @Res() res: Response) {
    if (!VALID_TYPES.includes(type as ImportType)) {
      throw new BadRequestException(
        `Invalid import type "${type}". Valid types: ${VALID_TYPES.join(', ')}`,
      );
    }

    const buffer = this.importService.getTemplate(type as ImportType);
    res.set({
      'Content-Type':
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition': `attachment; filename="${type}-template.xlsx"`,
      'Content-Length': buffer.length,
    });
    res.end(buffer);
  }

  /**
   * Upload and process an import file (.xlsx or .csv).
   * POST /api/v1/import/:type
   * Multipart field: file
   */
  @Post(':type')
  @UseInterceptors(
    FileInterceptor('file', {
      limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB max
      fileFilter: (_req, file, cb) => {
        const allowed = [
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'application/vnd.ms-excel',
          'text/csv',
          'application/csv',
        ];
        if (
          !allowed.includes(file.mimetype) &&
          !file.originalname.match(/\.(xlsx|xls|csv)$/i)
        ) {
          cb(
            new BadRequestException(
              'Only .xlsx, .xls, and .csv files are accepted',
            ),
            false,
          );
        } else {
          cb(null, true);
        }
      },
    }),
  )
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: { type: 'string', format: 'binary' },
      },
    },
  })
  async importFile(
    @Param('type') type: string,
    @UploadedFile() file: Express.Multer.File,
    @Req() req: Request,
  ) {
    if (!VALID_TYPES.includes(type as ImportType)) {
      throw new BadRequestException(
        `Invalid import type "${type}". Valid types: ${VALID_TYPES.join(', ')}`,
      );
    }
    if (!file) {
      throw new BadRequestException(
        'No file uploaded. Use multipart/form-data with field "file".',
      );
    }

    // Extract companyId from JWT claims (attached by auth guard)
    const user = (req as any).user;
    const companyId = user?.companyId || user?.cid;
    const userId = user?.id || user?.sub;

    if (!companyId) {
      throw new BadRequestException(
        'Cannot determine company from token. Ensure you are authenticated.',
      );
    }

    const report = await this.importService.import(
      companyId,
      userId,
      type as ImportType,
      file.buffer,
      file.originalname,
    );

    return report;
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import * as XLSX from 'xlsx';

// ─── Types ───────────────────────────────────────────────────────────────────

export type ImportType =
  'vehicles' | 'drivers' | 'customers' | 'vendors' | 'opening-balances';

export interface ImportRowResult {
  row: number;
  status: 'imported' | 'skipped';
  reason?: string;
  data?: Record<string, unknown>;
}

export interface ImportReport {
  importType: ImportType;
  totalRows: number;
  imported: number;
  skipped: number;
  results: ImportRowResult[];
}

// ─── Column Templates ─────────────────────────────────────────────────────────

export const TEMPLATES: Record<ImportType, string[]> = {
  vehicles: [
    'licensePlate',
    'make',
    'model',
    'year',
    'type',
    'capacityWeight',
    'vin',
  ],
  drivers: [
    'firstName',
    'lastName',
    'phone',
    'email',
    'licenseNumber',
    'licenseState',
    'licenseExpiry',
  ],
  customers: [
    'name',
    'email',
    'phone',
    'taxId',
    'billingAddress',
    'creditLimit',
    'paymentTerms',
  ],
  vendors: [
    'name',
    'email',
    'phone',
    'taxId',
    'billingAddress',
    'type',
    'paymentTerms',
  ],
  'opening-balances': [
    'entityType',
    'entityRef',
    'amount',
    'currency',
    'description',
    'date',
  ],
};

// ─── Validators ───────────────────────────────────────────────────────────────

const GST_REGEX = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
const PHONE_REGEX = /^(\+91[-\s]?)?[6-9]\d{9}$/;
const TRUCK_PLATE_REGEX = /^[A-Z]{2}[0-9]{1,2}[A-Z]{1,3}[0-9]{4}$/;

function validatePhone(phone: string | undefined): string | null {
  if (!phone) return null;
  const cleaned = phone.replace(/[\s\-]/g, '');
  if (!PHONE_REGEX.test(cleaned))
    return `Phone "${phone}" is not a valid Indian mobile number`;
  return null;
}

function validateGst(gst: string | undefined): string | null {
  if (!gst) return null;
  if (!GST_REGEX.test(gst.toUpperCase()))
    return `GST "${gst}" is not valid (expected 15-char GSTIN format)`;
  return null;
}

function validateLicensePlate(plate: string | undefined): string | null {
  if (!plate) return null;
  const normalized = plate.replace(/[\s\-]/g, '').toUpperCase();
  if (!TRUCK_PLATE_REGEX.test(normalized))
    return `License plate "${plate}" is not a valid Indian truck plate (e.g. GJ01AB1234)`;
  return null;
}

// ─── Parser ───────────────────────────────────────────────────────────────────

function parseFile(
  buffer: Buffer,
  originalName: string,
): Record<string, unknown>[] {
  // @ts-ignore: reserved for future use
  const _ext = originalName.split('.').pop()?.toLowerCase();
  const workbook = XLSX.read(buffer, { type: 'buffer', cellDates: true });
  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  return XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
    defval: '',
  });
}

// ─── Service ─────────────────────────────────────────────────────────────────

@Injectable()
export class BulkImportService {
  constructor(private readonly prisma: PrismaService) {}

  getTemplate(type: ImportType): Buffer {
    const columns = TEMPLATES[type];
    const wb = XLSX.utils.book_new();
    // Header row + one example row
    const exampleRows: Record<string, string>[] = [];
    const example: Record<string, string> = {};
    columns.forEach((col) => {
      example[col] = `<${col}>`;
    });
    exampleRows.push(example);
    const ws = XLSX.utils.json_to_sheet(exampleRows, { header: columns });
    XLSX.utils.book_append_sheet(wb, ws, type);
    return XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
  }

  async import(
    companyId: string,
    _userId: string,
    type: ImportType,
    buffer: Buffer,
    originalName: string,
  ): Promise<ImportReport> {
    const rows = parseFile(buffer, originalName);

    const report: ImportReport = {
      importType: type,
      totalRows: rows.length,
      imported: 0,
      skipped: 0,
      results: [],
    };

    if (rows.length === 0) {
      throw new BadRequestException('File is empty or has no data rows.');
    }

    await this.prisma.runAsSystem(`Bulk import ${type}`, async (tx: any) => {
      for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const rowNum = i + 2; // 1-indexed, +1 for header

        try {
          const errors: string[] = [];

          switch (type) {
            case 'vehicles':
              await this.importVehicleRow(tx, companyId, row, errors);
              break;
            case 'drivers':
              await this.importDriverRow(tx, companyId, row, errors);
              break;
            case 'customers':
              await this.importCustomerRow(tx, companyId, row, errors);
              break;
            case 'vendors':
              await this.importVendorRow(tx, companyId, row, errors);
              break;
            case 'opening-balances':
              await this.importOpeningBalanceRow(tx, companyId, row, errors);
              break;
          }

          if (errors.length > 0) {
            report.results.push({
              row: rowNum,
              status: 'skipped',
              reason: errors.join('; '),
              data: row,
            });
            report.skipped++;
          } else {
            report.results.push({ row: rowNum, status: 'imported', data: row });
            report.imported++;
          }
        } catch (err: any) {
          report.results.push({
            row: rowNum,
            status: 'skipped',
            reason: err?.message || 'Unknown error',
            data: row,
          });
          report.skipped++;
        }
      }
    });

    return report;
  }

  // ─── Row Importers ────────────────────────────────────────────────────────

  private async importVehicleRow(
    tx: any,
    companyId: string,
    row: Record<string, unknown>,
    errors: string[],
  ): Promise<void> {
    const plate = (row['licensePlate'] as string)?.trim();
    const make = (row['make'] as string)?.trim();
    const type = (row['type'] as string)?.trim() || 'TRUCK';
    // @ts-ignore: reserved for future use
    const _ownershipType = (row['ownershipType'] as string)?.trim() || 'OWNED';

    // Required field validation
    if (!plate) {
      errors.push('licensePlate is required');
    }
    if (!make) {
      errors.push('make is required');
    }
    if (errors.length) return;

    // Format validation
    const plateErr = validateLicensePlate(plate);
    if (plateErr) errors.push(plateErr);
    if (errors.length) return;

    // Duplicate check
    const existing = await tx.vehicle.findFirst({
      where: {
        companyId,
        licensePlate: plate.toUpperCase().replace(/[\s\-]/g, ''),
      },
    });
    if (existing) {
      errors.push(`Vehicle with plate ${plate} already exists`);
      return;
    }

    const yearRaw = row['year'];
    const year = yearRaw ? parseInt(String(yearRaw), 10) : null;
    const capacityWeight = row['capacityWeight']
      ? parseFloat(String(row['capacityWeight']))
      : null;

    await tx.vehicle.create({
      data: {
        companyId,
        licensePlate: plate.toUpperCase().replace(/[\s\-]/g, ''),
        make,
        model: (row['model'] as string)?.trim() || null,
        year: isNaN(year!) ? null : year,
        type,
        capacityWeight: isNaN(capacityWeight!) ? null : capacityWeight,
        vin: (row['vin'] as string)?.trim() || null,
        status: 'ACTIVE',
      },
    });
  }

  private async importDriverRow(
    tx: any,
    companyId: string,
    row: Record<string, unknown>,
    errors: string[],
  ): Promise<void> {
    const firstName = (row['firstName'] as string)?.trim();
    const lastName = (row['lastName'] as string)?.trim();
    const phone = (row['phone'] as string)?.trim();
    const licenseNumber = (row['licenseNumber'] as string)?.trim();

    if (!firstName) errors.push('firstName is required');
    if (!lastName) errors.push('lastName is required');
    if (errors.length) return;

    const phoneErr = validatePhone(phone);
    if (phoneErr) errors.push(phoneErr);
    if (errors.length) return;

    // Duplicate check by phone
    if (phone) {
      const existing = await tx.driver.findFirst({
        where: { companyId, phone },
      });
      if (existing) {
        errors.push(`Driver with phone ${phone} already exists`);
        return;
      }
    }
    // Duplicate check by license
    if (licenseNumber) {
      const existing = await tx.driver.findFirst({
        where: { companyId, licenseNumber },
      });
      if (existing) {
        errors.push(`Driver with license ${licenseNumber} already exists`);
        return;
      }
    }

    let licenseExpiry: Date | null = null;
    const expiryRaw = row['licenseExpiry'];
    if (expiryRaw) {
      const parsed = new Date(String(expiryRaw));
      licenseExpiry = isNaN(parsed.getTime()) ? null : parsed;
    }

    await tx.driver.create({
      data: {
        companyId,
        firstName,
        lastName,
        phone: phone || null,
        email: (row['email'] as string)?.trim() || null,
        licenseNumber: licenseNumber || null,
        licenseState: (row['licenseState'] as string)?.trim() || null,
        licenseExpiry,
        status: 'AVAILABLE',
      },
    });
  }

  private async importCustomerRow(
    tx: any,
    companyId: string,
    row: Record<string, unknown>,
    errors: string[],
  ): Promise<void> {
    const name = (row['name'] as string)?.trim();
    const email = (row['email'] as string)?.trim();
    const phone = (row['phone'] as string)?.trim();
    const taxId = (row['taxId'] as string)?.trim();

    if (!name) {
      errors.push('name is required');
      return;
    }

    const phoneErr = validatePhone(phone);
    if (phoneErr) errors.push(phoneErr);
    const gstErr = validateGst(taxId);
    if (gstErr) errors.push(gstErr);
    if (errors.length) return;

    if (email) {
      const existing = await tx.customer.findFirst({
        where: { companyId, email },
      });
      if (existing) {
        errors.push(`Customer with email ${email} already exists`);
        return;
      }
    }

    const creditLimit = row['creditLimit']
      ? parseFloat(String(row['creditLimit']))
      : 0;

    await tx.customer.create({
      data: {
        companyId,
        name,
        email: email || null,
        phone: phone || null,
        taxId: taxId || null,
        billingAddress: (row['billingAddress'] as string)?.trim() || null,
        creditLimit: isNaN(creditLimit) ? 0 : creditLimit,
        paymentTerms: (row['paymentTerms'] as string)?.trim() || 'NET_30',
        status: 'ACTIVE',
      },
    });
  }

  private async importVendorRow(
    tx: any,
    companyId: string,
    row: Record<string, unknown>,
    errors: string[],
  ): Promise<void> {
    const name = (row['name'] as string)?.trim();
    const email = (row['email'] as string)?.trim();
    const phone = (row['phone'] as string)?.trim();
    const taxId = (row['taxId'] as string)?.trim();

    if (!name) {
      errors.push('name is required');
      return;
    }

    const phoneErr = validatePhone(phone);
    if (phoneErr) errors.push(phoneErr);
    const gstErr = validateGst(taxId);
    if (gstErr) errors.push(gstErr);
    if (errors.length) return;

    if (email) {
      const existing = await tx.vendor.findFirst({
        where: { companyId, email },
      });
      if (existing) {
        errors.push(`Vendor with email ${email} already exists`);
        return;
      }
    }

    await tx.vendor.create({
      data: {
        companyId,
        name,
        email: email || null,
        phone: phone || null,
        taxId: taxId || null,
        billingAddress: (row['billingAddress'] as string)?.trim() || null,
        type: (row['type'] as string)?.trim() || 'CARRIER',
        paymentTerms: (row['paymentTerms'] as string)?.trim() || 'NET_30',
        status: 'ACTIVE',
      },
    });
  }

  private async importOpeningBalanceRow(
    tx: any,
    companyId: string,
    row: Record<string, unknown>,
    errors: string[],
  ): Promise<void> {
    const entityType = (row['entityType'] as string)?.trim();
    const entityRef = (row['entityRef'] as string)?.trim();
    const amountRaw = row['amount'];
    const description =
      (row['description'] as string)?.trim() || 'Opening Balance';

    if (!entityType)
      errors.push('entityType is required (e.g. CUSTOMER, VENDOR)');
    if (!entityRef) errors.push('entityRef is required (name or ID)');
    if (!amountRaw) errors.push('amount is required');
    if (errors.length) return;

    const amount = parseFloat(String(amountRaw));
    if (isNaN(amount)) {
      errors.push(`amount "${amountRaw}" is not a valid number`);
      return;
    }

    let dateVal = new Date();
    const dateRaw = row['date'];
    if (dateRaw) {
      const parsed = new Date(String(dateRaw));
      if (!isNaN(parsed.getTime())) dateVal = parsed;
    }

    // Opening balances stored as Expense records with category=OPENING_BALANCE
    await tx.expense.create({
      data: {
        companyId,
        category: 'OPENING_BALANCE',
        description: `[${entityType}] ${entityRef}: ${description}`,
        amount,
        currency: (row['currency'] as string)?.trim() || 'INR',
        date: dateVal,
        status: 'APPROVED',
      },
    });
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ChatService } from './chat.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { GetUser } from '../auth/decorators/get-user.decorator';
import type { AuthenticatedUser } from '../auth/decorators/get-user.decorator';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';

@ApiTags('Chat')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('chat')
export class ChatController {
  constructor(private readonly chatService: ChatService) {}

  @Get('channels')
  @ApiOperation({ summary: 'Get all channels for the current user' })
  getChannels(@GetUser() user: AuthenticatedUser) {
    return this.chatService.getChannels(user.companyId, user.userId);
  }

  @Post('channels')
  @ApiOperation({ summary: 'Create a new channel' })
  createChannel(
    @GetUser() user: AuthenticatedUser,
    @Body()
    body: {
      name: string;
      description?: string;
      type?: string;
      isPrivate?: boolean;
      memberIds?: string[];
    },
  ) {
    return this.chatService.createChannel(user.companyId, user.userId, body);
  }

  @Get('channels/:channelId/messages')
  @ApiOperation({ summary: 'Get messages in a channel' })
  getMessages(
    @GetUser() user: AuthenticatedUser,
    @Param('channelId') channelId: string,
    @Query('cursor') cursor?: string,
    @Query('limit') limit?: string,
  ) {
    return this.chatService.getMessages(
      user.companyId,
      user.userId,
      channelId,
      cursor,
      limit ? parseInt(limit) : 50,
    );
  }

  @Post('channels/:channelId/messages')
  @ApiOperation({ summary: 'Send a message to a channel' })
  sendMessage(
    @GetUser() user: AuthenticatedUser,
    @Param('channelId') channelId: string,
    @Body() body: { content: string; attachments?: any[]; mentions?: string[] },
  ) {
    return this.chatService.sendMessage(
      user.companyId,
      user.userId,
      channelId,
      body.content,
      body.attachments,
      body.mentions,
    );
  }

  @Put('messages/:messageId')
  @ApiOperation({ summary: 'Edit a message' })
  editMessage(
    @GetUser() user: AuthenticatedUser,
    @Param('messageId') messageId: string,
    @Body() body: { content: string },
  ) {
    return this.chatService.editMessage(
      user.companyId,
      user.userId,
      messageId,
      body.content,
    );
  }

  @Delete('messages/:messageId')
  @ApiOperation({ summary: 'Delete a message' })
  @HttpCode(HttpStatus.NO_CONTENT)
  deleteMessage(
    @GetUser() user: AuthenticatedUser,
    @Param('messageId') messageId: string,
  ) {
    return this.chatService.deleteMessage(
      user.companyId,
      user.userId,
      messageId,
    );
  }

  @Post('messages/:messageId/reactions')
  @ApiOperation({ summary: 'Add a reaction to a message' })
  addReaction(
    @GetUser() user: AuthenticatedUser,
    @Param('messageId') messageId: string,
    @Body() body: { emoji: string },
  ) {
    return this.chatService.addReaction(user.userId, messageId, body.emoji);
  }

  @Delete('messages/:messageId/reactions/:emoji')
  @ApiOperation({ summary: 'Remove a reaction from a message' })
  @HttpCode(HttpStatus.NO_CONTENT)
  removeReaction(
    @GetUser() user: AuthenticatedUser,
    @Param('messageId') messageId: string,
    @Param('emoji') emoji: string,
  ) {
    return this.chatService.removeReaction(user.userId, messageId, emoji);
  }

  @Post('channels/:channelId/join')
  @ApiOperation({ summary: 'Join a public channel' })
  joinChannel(
    @GetUser() user: AuthenticatedUser,
    @Param('channelId') channelId: string,
  ) {
    return this.chatService.joinChannel(user.userId, channelId);
  }

  @Post('dm/:otherUserId')
  @ApiOperation({ summary: 'Open or create a DM with a user' })
  getOrCreateDm(
    @GetUser() user: AuthenticatedUser,
    @Param('otherUserId') otherUserId: string,
  ) {
    return this.chatService.getOrCreateDm(
      user.companyId,
      user.userId,
      otherUserId,
    );
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class ChatService {
  constructor(private prisma: PrismaService) {}

  async getChannels(companyId: string, userId: string) {
    // Get all non-archived channels the user is a member of, or all public channels
    const channels = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannel.findMany({
        where: {
          companyId,
          archivedAt: null,
          OR: [{ isPrivate: false }, { members: { some: { userId } } }],
        },
        include: {
          members: { select: { userId: true, lastReadAt: true } },
          _count: { select: { messages: true } },
        },
        orderBy: { createdAt: 'asc' },
      }),
    );

    // Add unread count per channel for this user
    return channels.map((ch) => {
      const myMembership = ch.members.find((m) => m.userId === userId);
      return {
        ...ch,
        isMember: !!myMembership,
        lastReadAt: myMembership?.lastReadAt,
      };
    });
  }

  async createChannel(
    companyId: string,
    userId: string,
    data: {
      name: string;
      description?: string;
      type?: string;
      isPrivate?: boolean;
      memberIds?: string[];
    },
  ) {
    const channel = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannel.create({
        data: {
          companyId,
          name: data.name,
          description: data.description,
          type: data.type || 'CHANNEL',
          isPrivate: data.isPrivate || false,
          createdById: userId,
          members: {
            create: [
              { userId, role: 'ADMIN' },
              ...(data.memberIds || [])
                .filter((id) => id !== userId)
                .map((id) => ({ userId: id, role: 'MEMBER' })),
            ],
          },
        },
        include: { members: true },
      }),
    );
    return channel;
  }

  async getMessages(
    companyId: string,
    userId: string,
    channelId: string,
    cursor?: string,
    limit = 50,
  ) {
    // Verify membership or public channel
    const channel = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannel.findFirst({
        where: { id: channelId, companyId },
      }),
    );
    if (!channel) throw new NotFoundException('Channel not found');

    if (channel.isPrivate) {
      const isMember = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.chatChannelMember.findUnique({
          where: { channelId_userId: { channelId, userId } },
        }),
      );
      if (!isMember)
        throw new ForbiddenException('Not a member of this channel');
    }

    const messages = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.findMany({
        where: {
          channelId,
          ...(cursor ? { createdAt: { lt: new Date(cursor) } } : {}),
        },
        include: {
          sender: {
            select: { id: true, firstName: true, lastName: true, avatar: true },
          },
          reactions: {
            include: {
              user: { select: { id: true, firstName: true, lastName: true } },
            },
          },
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
      }),
    );

    // Update last read
    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannelMember.upsert({
        where: { channelId_userId: { channelId, userId } },
        update: { lastReadAt: new Date() },
        create: { channelId, userId, lastReadAt: new Date() },
      }),
    );

    return messages.reverse();
  }

  async sendMessage(
    companyId: string,
    userId: string,
    channelId: string,
    content: string,
    attachments: any[] = [],
    mentions: string[] = [],
  ) {
    const channel = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannel.findFirst({
        where: { id: channelId, companyId },
      }),
    );
    if (!channel) throw new NotFoundException('Channel not found');

    const message = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.create({
        data: { channelId, senderId: userId, content, attachments, mentions },
        include: {
          sender: {
            select: { id: true, firstName: true, lastName: true, avatar: true },
          },
          reactions: true,
        },
      }),
    );

    // Create notifications for mentioned users
    if (mentions.length > 0) {
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.notification.createMany({
          data: mentions.map((mentionedUserId) => ({
            companyId,
            userId: mentionedUserId,
            type: 'CHAT',
            title: `You were mentioned`,
            body: `${content.substring(0, 100)}...`,
            entityType: 'ChatMessage',
            entityId: message.id,
            actionUrl: `/chat?channel=${channelId}`,
          })),
          skipDuplicates: true,
        }),
      );
    }

    return message;
  }

  async editMessage(
    companyId: string,
    userId: string,
    messageId: string,
    content: string,
  ) {
    const message = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.findUnique({
        where: { id: messageId },
      }),
    );
    if (!message) throw new NotFoundException('Message not found');
    if (message.senderId !== userId)
      throw new ForbiddenException("Cannot edit another user's message");

    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.update({
        where: { id: messageId },
        data: { content, editedAt: new Date() },
        include: {
          sender: { select: { id: true, firstName: true, lastName: true } },
          reactions: true,
        },
      }),
    );
  }

  async deleteMessage(companyId: string, userId: string, messageId: string) {
    const message = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.findUnique({
        where: { id: messageId },
      }),
    );
    if (!message) throw new NotFoundException('Message not found');
    if (message.senderId !== userId)
      throw new ForbiddenException("Cannot delete another user's message");

    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatMessage.update({
        where: { id: messageId },
        data: { deletedAt: new Date(), content: 'This message was deleted.' },
      }),
    );
  }

  async addReaction(userId: string, messageId: string, emoji: string) {
    return this.prisma.runAsSystem(
      '[ChatService.addReaction] Internal service operation bypass',
      async (tx) =>
        tx.messageReaction.upsert({
          where: { messageId_userId_emoji: { messageId, userId, emoji } },
          update: {},
          create: { messageId, userId, emoji },
        }),
    );
  }

  async removeReaction(userId: string, messageId: string, emoji: string) {
    return this.prisma.runAsSystem(
      '[ChatService.removeReaction] Internal service operation bypass',
      async (tx) =>
        tx.messageReaction.deleteMany({
          where: { messageId, userId, emoji },
        }),
    );
  }

  async joinChannel(userId: string, channelId: string) {
    return this.prisma.runAsSystem(
      '[ChatService.joinChannel] Internal service operation bypass',
      async (tx) =>
        tx.chatChannelMember.upsert({
          where: { channelId_userId: { channelId, userId } },
          update: {},
          create: { channelId, userId },
        }),
    );
  }

  async getOrCreateDm(companyId: string, userId: string, otherUserId: string) {
    // Check if DM channel already exists between these two users
    const existing = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.chatChannel.findFirst({
        where: {
          companyId,
          type: 'DIRECT',
          members: { every: { userId: { in: [userId, otherUserId] } } },
        },
      }),
    );
    if (existing) return existing;

    return this.createChannel(companyId, userId, {
      name: `DM`,
      type: 'DIRECT',
      isPrivate: true,
      memberIds: [otherUserId],
    });
  }
}

