import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import type { Contract } from '@prisma/client';

@Injectable()
export class ContractService {
  private readonly logger = new Logger(ContractService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Creates a new Customer or Carrier contract
   */
  async createContract(companyId: string, data: any): Promise<Contract> {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.contract.create({
        data: {
          ...data,
          companyId,
          status: 'DRAFT',
        },
      }),
    );
  }

  /**
   * Activates a contract
   */
  async activateContract(
    companyId: string,
    contractId: string,
  ): Promise<Contract> {
    const contract = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.contract.findUnique({
        where: { id: contractId, companyId },
      }),
    );

    if (!contract) throw new NotFoundException('Contract not found');

    // If activating a customer contract, we should probably expire old active ones
    // But for V1, we just set status
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.contract.update({
        where: { id: contractId },
        data: { status: 'ACTIVE' },
      }),
    );
  }

  /**
   * Gets the currently active SLA terms for a customer
   */
  async getActiveCustomerSla(
    companyId: string,
    customerId: string,
  ): Promise<Contract | null> {
    const now = new Date();

    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.contract.findFirst({
        where: {
          companyId,
          customerId,
          type: 'MSA',
          status: 'ACTIVE',
          OR: [
            { startDate: null, endDate: null },
            { startDate: { lte: now }, endDate: { gte: now } },
            { startDate: { lte: now }, endDate: null },
          ],
        },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }

  /**
   * Evaluates expired contracts and updates their status
   * Could be called via a daily cron job
   */
  async expireOldContracts(companyId: string) {
    const now = new Date();

    const expired = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.contract.updateMany({
        where: {
          companyId,
          status: 'ACTIVE',
          endDate: { lt: now },
        },
        data: {
          status: 'EXPIRED',
        },
      }),
    );

    this.logger.log(
      `Expired ${expired.count} contracts for company ${companyId}`,
    );
    return expired.count;
  }
}

import {
  Injectable,
  // @ts-ignore: reserved for future use
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import type { RateCard } from '@prisma/client';

@Injectable()
export class PricingService {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Creates a new Rate Card or a new version of an existing Rate Card
   */
  async createRateCard(companyId: string, data: any) {
    // If updating an existing route/customer, we should mark older versions as inactive or EXPIRED
    if (data.customerId && data.originCity && data.destinationCity) {
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.rateCard.updateMany({
          where: {
            companyId,
            customerId: data.customerId,
            originCity: data.originCity,
            destinationCity: data.destinationCity,
            status: 'APPROVED',
          },
          data: {
            status: 'EXPIRED',
            active: false,
          },
        }),
      );
    }

    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.rateCard.create({
        data: {
          ...data,
          companyId,
          status: 'APPROVED',
          active: true,
        },
      }),
    );
  }

  /**
   * Evaluates the best available rate for a specific shipment context
   */
  async evaluateRate(
    companyId: string,
    customerId: string,
    originCity: string,
    destinationCity: string,
    equipmentType?: string,
  ): Promise<RateCard | null> {
    const now = new Date();

    // Look for exact match (route + customer)
    const rateCard = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.rateCard.findFirst({
        where: {
          companyId,
          customerId,
          originCity,
          destinationCity,
          status: 'APPROVED',
          active: true,
          OR: [
            { validFrom: null, validTo: null },
            { validFrom: { lte: now }, validTo: { gte: now } },
            { validFrom: { lte: now }, validTo: null },
          ],
          ...(equipmentType ? { equipmentType } : {}),
        },
        orderBy: { createdAt: 'desc' },
      }),
    );

    return rateCard;
  }

  /**
   * Creates a Quotation
   */
  async createQuotation(companyId: string, customerId: string, data: any) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.quotation.create({
        data: {
          ...data,
          companyId,
          customerId,
          status: 'DRAFT',
        },
      }),
    );
  }

  /**
   * Submits a Quotation to the customer
   */
  async submitQuotation(companyId: string, quotationId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.quotation.update({
        where: { id: quotationId, companyId },
        data: { status: 'SUBMITTED' },
      }),
    );
  }

  /**
   * Approves a Quotation and converts it into a Rate Card
   */
  async convertQuotationToRateCard(companyId: string, quotationId: string) {
    const quote = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.quotation.findUnique({
        where: { id: quotationId, companyId },
      }),
    );

    if (!quote) throw new NotFoundException('Quotation not found');
    if (quote.status !== 'SUBMITTED')
      throw new BadRequestException('Only SUBMITTED quotes can be approved');

    return this.prisma.$transaction(async (tx) => {
      // 1. Mark quote as APPROVED and CONVERTED
      await tx.quotation.update({
        where: { id: quotationId },
        data: { status: 'CONVERTED' },
      });

      // 2. Generate a Rate Card from the Quote (assumes notes contains metadata or we just use totalAmount)
      // In reality, Quotation would have QuotationLineItems, but for V1 we use the totalAmount as a flat rate.
      const rateCard = await tx.rateCard.create({
        data: {
          companyId,
          customerId: quote.customerId,
          type: 'FLAT',
          rate: quote.totalAmount,
          currency: quote.currency,
          active: true,
          status: 'APPROVED',
          validFrom: new Date(),
          validTo: quote.validUntil,
        },
      });

      return rateCard;
    });
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

export interface ProfitabilityMetrics {
  revenue: number;
  directCost: number;
  grossProfit: number;
  marginPercentage: number;
}

@Injectable()
export class ProfitabilityService {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Calculates actual profitability for a completed Trip.
   * Pulls Invoices for Revenue, and Expenses + Settlements for Cost.
   */
  async calculateTripProfitability(
    companyId: string,
    tripId: string,
  ): Promise<ProfitabilityMetrics> {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId, companyId },
        include: {
          loads: {
            include: {
              invoices: true, // We assume Load has invoices generated
            },
          },
          expenses: true,
        },
      }),
    );

    if (!trip) throw new NotFoundException('Trip not found');

    // 1. Calculate Revenue (Sum of Invoices for all loads in the trip)
    let totalRevenue = 0;
    if (trip.loads && trip.loads.length > 0) {
      for (const load of trip.loads) {
        const invoices = load.invoices || [];
        const loadRevenue = invoices.reduce(
          (sum, inv: any) => sum + inv.amount,
          0,
        );

        if (loadRevenue > 0) {
          totalRevenue += loadRevenue;
        } else if (load.rate) {
          totalRevenue += load.rate;
        }
      }
    }

    // 2. Calculate Costs
    let totalCost = 0;

    // 2a. Trip Expenses (Fuel, Tolls, Maintenance during trip)
    const expenses = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.expense.findMany({
        where: { companyId, tripId },
      }),
    );
    totalCost += expenses.reduce((sum, exp) => sum + exp.amount, 0);

    // 2b. Driver Settlement for this trip (simplified: assuming we can extract trip-specific pay,
    // or we estimate driver cost based on duration). For V1 we just query expenses.
    // In a full ERP, Settlements have SettlementLines linked to Trips.

    const grossProfit = totalRevenue - totalCost;
    const marginPercentage =
      totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;

    return {
      revenue: parseFloat(totalRevenue.toFixed(2)),
      directCost: parseFloat(totalCost.toFixed(2)),
      grossProfit: parseFloat(grossProfit.toFixed(2)),
      marginPercentage: parseFloat(marginPercentage.toFixed(2)),
    };
  }

  /**
   * Calculates aggregate profitability for a Customer across a time range.
   */
  async calculateCustomerProfitability(
    companyId: string,
    customerId: string,
    fromDate: Date,
    toDate: Date,
  ): Promise<ProfitabilityMetrics> {
    // 1. Get Invoices for Revenue
    const invoices = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.invoice.findMany({
        where: {
          companyId,
          customerId,
          status: { notIn: ['DRAFT', 'CANCELLED'] },
          createdAt: { gte: fromDate, lte: toDate },
        },
        include: {
          load: true,
        },
      }),
    );

    let totalRevenue = 0;
    let totalCost = 0;
    const tripIds = new Set<string>();

    for (const inv of invoices) {
      totalRevenue += inv.amount;
      if (inv.load?.tripId) {
        tripIds.add(inv.load.tripId);
      }
    }

    if (tripIds.size > 0) {
      const expenses = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.expense.findMany({
          where: { companyId, tripId: { in: Array.from(tripIds) } },
        }),
      );
      totalCost += expenses.reduce((sum, exp) => sum + exp.amount, 0);
    }

    const grossProfit = totalRevenue - totalCost;
    const marginPercentage =
      totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;

    return {
      revenue: parseFloat(totalRevenue.toFixed(2)),
      directCost: parseFloat(totalCost.toFixed(2)),
      grossProfit: parseFloat(grossProfit.toFixed(2)),
      marginPercentage: parseFloat(marginPercentage.toFixed(2)),
    };
  }
}

import {
  Injectable,
  // @ts-ignore: reserved for future use
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class TenderService {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Creates a new Tender for carrier bidding
   */
  async createTender(companyId: string, data: any) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tender.create({
        data: {
          ...data,
          companyId,
          status: 'OPEN',
        },
      }),
    );
  }

  /**
   * Submits a bid from a carrier/vendor for an open tender
   */
  async submitBid(
    companyId: string,
    tenderId: string,
    vendorId: string,
    data: any,
  ) {
    const tender = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tender.findUnique({
        where: { id: tenderId, companyId },
      }),
    );

    if (!tender) throw new NotFoundException('Tender not found');
    if (tender.status !== 'OPEN')
      throw new BadRequestException('Tender is not OPEN');

    // Check if past deadline
    if (tender.submissionDeadline && new Date() > tender.submissionDeadline) {
      throw new BadRequestException('Tender submission deadline has passed');
    }

    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenderBid.create({
        data: {
          ...data,
          tenderId,
          vendorId,
          status: 'SUBMITTED',
        },
      }),
    );
  }

  /**
   * Awards the tender to a specific bid and closes the tender
   */
  async awardTender(companyId: string, tenderId: string, winningBidId: string) {
    const tender = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tender.findUnique({
        where: { id: tenderId, companyId },
        include: { bids: true },
      }),
    );

    if (!tender) throw new NotFoundException('Tender not found');
    if (tender.status !== 'OPEN')
      throw new BadRequestException('Tender is not OPEN');

    const winningBid = tender.bids.find((b) => b.id === winningBidId);
    if (!winningBid)
      throw new NotFoundException('Winning bid not found in tender');

    return this.prisma.$transaction(async (tx) => {
      // 1. Mark winning bid as ACCEPTED
      await tx.tenderBid.update({
        where: { id: winningBidId },
        data: { status: 'ACCEPTED' },
      });

      // 2. Mark other bids as REJECTED
      const losingBidIds = tender.bids
        .filter((b) => b.id !== winningBidId)
        .map((b) => b.id);
      if (losingBidIds.length > 0) {
        await tx.tenderBid.updateMany({
          where: { id: { in: losingBidIds } },
          data: { status: 'REJECTED' },
        });
      }

      // 3. Mark tender as AWARDED
      await tx.tender.update({
        where: { id: tenderId },
        data: { status: 'AWARDED' },
      });

      // 4. Optionally: Auto-generate a Contract / Carrier Agreement here
      const contract = await tx.contract.create({
        data: {
          companyId,
          vendorId: winningBid.vendorId,
          type: 'CARRIER_AGREEMENT',
          status: 'ACTIVE',
          startDate: new Date(),
          paymentTerms: 'NET30',
        },
      });

      return contract;
    });
  }
}

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { Prisma } from '@prisma/client';

// ---------------------------------------------------------------------------
// Global Exception Filter — Enterprise Hardened
//
// Security controls:
//   1. Stack traces never reach the client in production
//   2. Prisma errors mapped to user-safe messages (no SQL leak)
//   3. Validation errors returned as structured array
//   4. Correlation ID attached to every error response
//   5. 5xx errors logged with full context for SIEM/alerting
//   6. Prisma unique constraint → 409 Conflict (not 500)
//   7. Prisma not-found → 404 Not Found (not 500)
// ---------------------------------------------------------------------------

const IS_PRODUCTION = process.env.NODE_ENV === 'production';

@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger('GlobalExceptionFilter');

  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    const correlationId: string =
      (request as any)['correlationId'] ??
      request.headers['x-correlation-id'] ??
      'no-correlation-id';

    let statusCode = HttpStatus.INTERNAL_SERVER_ERROR;
    let message: string | string[] =
      'An unexpected error occurred. Please try again later.';
    let errorCode = 'INTERNAL_ERROR';

    // ── HTTP Exceptions (including NestJS validation errors)
    if (exception instanceof HttpException) {
      statusCode = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      if (typeof exceptionResponse === 'string') {
        message = exceptionResponse;
      } else if (
        typeof exceptionResponse === 'object' &&
        exceptionResponse !== null
      ) {
        const body = exceptionResponse as any;
        message = body.message ?? body.error ?? 'Request failed';
        errorCode = body.errorCode ?? this.statusToCode(statusCode);

        if (statusCode === 400 && Array.isArray(body.message)) {
          this.logger.error(`Validation Error: ${body.message.join(', ')}`);
        } else if (statusCode === 400) {
          this.logger.error(`Bad Request Error: ${errorCode} - ${message}`);
        }
      }
    }
    // ── Prisma Known Request Errors
    else if (exception instanceof Prisma.PrismaClientKnownRequestError) {
      const mapped = this.mapPrismaError(exception);
      statusCode = mapped.statusCode;
      message = mapped.message;
      errorCode = mapped.errorCode;
    }
    // ── Prisma Validation Errors
    else if (exception instanceof Prisma.PrismaClientValidationError) {
      statusCode = HttpStatus.BAD_REQUEST;
      message = 'Invalid data provided. Please check your request.';
      errorCode = 'VALIDATION_ERROR';
    }
    // ── CSRF Token Errors (csurf throws Error with code EBADCSRFTOKEN)
    // Must be mapped to 403 — falling through to the unknown handler produces
    // a 500, which leaks that CSRF is in use and enables cheap availability hits.
    else if ((exception as any)?.code === 'EBADCSRFTOKEN') {
      statusCode = HttpStatus.FORBIDDEN;
      message = 'Invalid or missing CSRF token.';
      errorCode = 'CSRF_TOKEN_INVALID';
    }
    // ── Unknown errors
    else {
      // Log full error internally for 5xx events
      this.logger.error(
        `[${correlationId}] Unhandled exception: ${(exception as any)?.message ?? exception}`,
        IS_PRODUCTION ? undefined : (exception as any)?.stack,
      );
    }

    // Set correlation ID header so clients can reference it in support
    response.setHeader('X-Correlation-Id', correlationId);

    response.status(statusCode).json({
      success: false,
      statusCode,
      errorCode,
      correlationId,
      timestamp: new Date().toISOString(),
      path: request.url,
      message,
      // Stack trace only in non-production environments
      ...(!IS_PRODUCTION && exception instanceof Error
        ? { debug: { stack: exception.stack?.split('\n').slice(0, 5) } }
        : {}),
    });
  }

  private mapPrismaError(error: Prisma.PrismaClientKnownRequestError): {
    statusCode: number;
    message: string;
    errorCode: string;
  } {
    switch (error.code) {
      case 'P2002': // Unique constraint violation
        return {
          statusCode: HttpStatus.CONFLICT,
          message: 'A record with this value already exists.',
          errorCode: 'DUPLICATE_RECORD',
        };
      case 'P2025': // Record not found
        return {
          statusCode: HttpStatus.NOT_FOUND,
          message: 'The requested record was not found.',
          errorCode: 'NOT_FOUND',
        };
      case 'P2003': // Foreign key constraint
        return {
          statusCode: HttpStatus.BAD_REQUEST,
          message: 'A referenced record does not exist.',
          errorCode: 'FOREIGN_KEY_VIOLATION',
        };
      case 'P2014': // Relation violation
        return {
          statusCode: HttpStatus.BAD_REQUEST,
          message: 'This record is in use and cannot be modified in this way.',
          errorCode: 'RELATION_VIOLATION',
        };
      default:
        this.logger.error(
          `Unmapped Prisma error P${error.code}: ${error.message}`,
        );
        return {
          statusCode: HttpStatus.INTERNAL_SERVER_ERROR,
          message: 'A database error occurred.',
          errorCode: 'DATABASE_ERROR',
        };
    }
  }

  private statusToCode(status: number): string {
    const map: Record<number, string> = {
      400: 'BAD_REQUEST',
      401: 'UNAUTHORIZED',
      403: 'FORBIDDEN',
      404: 'NOT_FOUND',
      409: 'CONFLICT',
      422: 'UNPROCESSABLE_ENTITY',
      429: 'RATE_LIMIT_EXCEEDED',
      503: 'SERVICE_UNAVAILABLE',
    };
    return map[status] ?? 'HTTP_ERROR';
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class EWayBillGuard implements CanActivate {
  constructor(private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();

    // We only care if the action is dispatching the trip (changing status to IN_TRANSIT)
    if (
      request.method !== 'PATCH' ||
      !request.body.status ||
      request.body.status !== 'IN_TRANSIT'
    ) {
      return true;
    }

    const loadId = request.params.id;
    const companyId = request.user.companyId;

    const invoice = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.invoice.findFirst({
        where: { loadId, companyId },
      }),
    );

    if (!invoice) {
      throw new HttpException(
        'Trip cannot start without an attached Invoice.',
        HttpStatus.PRECONDITION_FAILED,
      );
    }

    const eWayBillNumber = (invoice as any).eWayBillNumber;
    const eWayBillExpiry = (invoice as any).eWayBillExpiry;

    if (!eWayBillNumber || !eWayBillExpiry) {
      throw new HttpException(
        'Trip cannot start: E-Way Bill Number is missing.',
        HttpStatus.PRECONDITION_FAILED,
      );
    }

    if (new Date(eWayBillExpiry) < new Date()) {
      throw new HttpException(
        'Trip cannot start: E-Way Bill has expired.',
        HttpStatus.PRECONDITION_FAILED,
      );
    }

    return true; // E-Way bill is valid and active.
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class RequireApprovalGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    private prisma: PrismaService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiresApproval = this.reflector.getAllAndOverride<boolean>(
      'requiresApproval',
      [context.getHandler(), context.getClass()],
    );

    if (!requiresApproval) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user || !user.id || !user.companyId) {
      throw new ForbiddenException(
        'Strict Authorization Required. No user context found.',
      );
    }

    // @ts-ignore: reserved for future use
    const _payload = request.body || {};
    const resourceId = request.params.id || 'bulk';
    // @ts-ignore: reserved for future use
    const _action = request.method;
    const resourceType = request.url.split('/')[2] || 'unknown';

    // 1. Create the Maker/Checker Approval Request
    await this.prisma.runAsTenant(user.companyId, async (tx) =>
      tx.approvalRequest.create({
        data: {
          companyId: user.companyId,
          requestedBy: user.id,
          entityType: resourceType,
          entityId: resourceId,
          executionId: 'mock-execution-id', // Mocked execution ID for approval request
          status: 'PENDING',
        },
      }),
    );

    // 2. Halt the HTTP request and return 202 Accepted.
    throw new HttpException(
      {
        status: HttpStatus.ACCEPTED,
        message:
          'Mutation requires approval. Approval request submitted to Finance Manager.',
        approvalRequired: true,
      },
      HttpStatus.ACCEPTED,
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  ServiceUnavailableException,
} from '@nestjs/common';
import { Observable, throwError } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';

const DEFAULT_FAILURE_THRESHOLD = 5;
const DEFAULT_RESET_TIMEOUT = 30000; // 30 seconds

interface CircuitState {
  failures: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
  nextAttempt: number;
}

@Injectable()
export class CircuitBreakerInterceptor implements NestInterceptor {
  private circuits = new Map<string, CircuitState>();

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();
    const routeKey = `${request.method}:${request.route?.path || request.url}`;

    let circuit = this.circuits.get(routeKey);
    if (!circuit) {
      circuit = { failures: 0, state: 'CLOSED', nextAttempt: 0 };
      this.circuits.set(routeKey, circuit);
    }

    if (circuit.state === 'OPEN') {
      if (Date.now() > circuit.nextAttempt) {
        circuit.state = 'HALF_OPEN';
      } else {
        return throwError(
          () =>
            new ServiceUnavailableException(
              'Service is temporarily unavailable (Circuit Open)',
            ),
        );
      }
    }

    return next.handle().pipe(
      tap(() => {
        // Success: Reset circuit
        if (circuit.state === 'HALF_OPEN' || circuit.failures > 0) {
          circuit.failures = 0;
          circuit.state = 'CLOSED';
        }
      }),
      catchError((err) => {
        // Only increment failures for 5xx errors or network issues
        const status = err.getStatus ? err.getStatus() : 500;
        if (status >= 500) {
          if (circuit.state === 'HALF_OPEN') {
            circuit.state = 'OPEN';
            circuit.nextAttempt = Date.now() + DEFAULT_RESET_TIMEOUT;
          } else {
            circuit.failures += 1;
            if (circuit.failures >= DEFAULT_FAILURE_THRESHOLD) {
              circuit.state = 'OPEN';
              circuit.nextAttempt = Date.now() + DEFAULT_RESET_TIMEOUT;
            }
          }
        }
        return throwError(() => err);
      }),
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Observable, of } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import Redis from 'ioredis';

import { RedisManagerService } from '../redis/redis-manager.service';

@Injectable()
export class IdempotencyInterceptor implements NestInterceptor {
  private readonly redis: Redis;
  private readonly logger = new Logger(IdempotencyInterceptor.name);

  constructor(private readonly redisManager: RedisManagerService) {
    this.redis = this.redisManager.getClient();
  }

  async intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Promise<Observable<any>> {
    const request = context.switchToHttp().getRequest();
    const response = context.switchToHttp().getResponse();

    // Only apply idempotency to mutating endpoints (POST, PUT, PATCH, DELETE)
    if (request.method === 'GET' || request.method === 'OPTIONS') {
      return next.handle();
    }

    const idempotencyKey = request.headers['x-idempotency-key'];

    if (!idempotencyKey) {
      // For global safety, we could enforce it, but to prevent breaking all existing clients, we make it optional but recommended.
      // However, if it IS provided, we strictly enforce it.
      return next.handle();
    }

    const cacheKey = `idempotency:${request.user?.companyId || 'global'}:${request.method}:${request.path}:${idempotencyKey}`;

    try {
      const cachedResponseStr = await this.redis.get(cacheKey);

      if (cachedResponseStr) {
        if (cachedResponseStr === 'IN_PROGRESS') {
          throw new HttpException(
            'Request is already being processed.',
            HttpStatus.CONFLICT,
          );
        }

        const cachedResponse = JSON.parse(cachedResponseStr);
        this.logger.log(
          `[Idempotency] Serving cached response for key: ${idempotencyKey}`,
        );

        // Ensure we send back the original status code
        response.status(cachedResponse.statusCode || HttpStatus.OK);
        return of(cachedResponse.data);
      }

      // Mark as in-progress (TTL 30s to match timeout interceptor)
      await this.redis.set(cacheKey, 'IN_PROGRESS', 'EX', 30);
    } catch (err) {
      if (err instanceof HttpException) throw err;
      this.logger.error('Redis error in IdempotencyInterceptor', err);
      // Proceed gracefully if Redis fails
      return next.handle();
    }

    return next.handle().pipe(
      tap(async (data) => {
        try {
          const responseToCache = {
            statusCode: response.statusCode,
            data,
          };
          // Cache successful response for 24 hours
          await this.redis.set(
            cacheKey,
            JSON.stringify(responseToCache),
            'EX',
            86400,
          );
        } catch (err) {
          this.logger.error('Failed to cache idempotent response', err);
        }
      }),
      catchError(async (err) => {
        try {
          // If the request fails (e.g. validation error, 500), remove the IN_PROGRESS lock
          // so the client can retry safely.
          await this.redis.del(cacheKey);
        } catch (redisErr) {
          this.logger.error(
            'Failed to clear idempotency lock on error',
            redisErr,
          );
        }
        throw err; // rethrow the original error
      }),
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { queryMonitorStorage } from '../query-monitor.storage';

@Injectable()
export class QueryMonitorInterceptor implements NestInterceptor {
  private readonly logger = new Logger('QueryMonitor');

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const store = { count: 0 };

    return queryMonitorStorage.run(store, () => {
      const request = context.switchToHttp().getRequest();
      const method = request.method;
      const url = request.url;

      return next.handle().pipe(
        tap(() => {
          if (store.count > 3) {
            this.logger.error(
              `[N+1 WARNING] ${method} ${url} triggered ${store.count} queries!`,
            );
          } else {
            this.logger.log(
              `[PERFORMANCE] ${method} ${url} completed in ${store.count} queries.`,
            );
          }
        }),
      );
    });
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  RequestTimeoutException,
} from '@nestjs/common';
import { Observable, throwError, TimeoutError } from 'rxjs';
import { catchError, timeout } from 'rxjs/operators';

@Injectable()
export class TimeoutInterceptor implements NestInterceptor {
  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
    // 30 seconds default timeout for all API requests
    const timeoutDuration = 30000;

    return next.handle().pipe(
      timeout(timeoutDuration),
      catchError((err) => {
        if (err instanceof TimeoutError) {
          return throwError(
            () =>
              new RequestTimeoutException(
                `Request timeout after ${timeoutDuration}ms`,
              ),
          );
        }
        return throwError(() => err);
      }),
    );
  }
}

import { Request, Response, NextFunction } from 'express';
import csurf = require('csurf');

const csrfProtection = csurf({
  cookie: {
    key: '_csrf',
    path: '/',
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
  },
  value: (req: Request) => {
    // Check both X-XSRF-TOKEN (Axios default) and custom headers
    const token = req.headers['x-xsrf-token'] || req.headers['x-csrf-token'];
    return (Array.isArray(token) ? token[0] : token) || '';
  },
});

export function csrfMiddleware(
  req: Request,
  res: Response,
  next: NextFunction,
) {
  // 1. Skip CSRF for Webhooks, Auth Login, and OAuth token endpoints (Stateless/Server-to-Server)
  if (
    req.path.match(/^\/api\/v[0-9]+\/auth\/(login|register)$/) ||
    req.path.match(/^\/api\/v[0-9]+\/iam\/oauth\/token$/) ||
    req.path.match(/^\/api\/v[0-9]+\/(.*\/)?webhook(s)?(\/|$)/) ||
    req.path.match(/^\/api\/v[0-9]+\/ingress\/telemetry$/)
  ) {
    return next();
  }

  // 2. Skip CSRF for Mobile/API Clients using Bearer JWTs
  // (CSRF is a browser-based cookie vulnerability)
  if (req.headers.authorization?.startsWith('Bearer ')) {
    return next();
  }

  // 3. Apply standard CSRF protection
  csrfProtection(req, res, (err: any) => {
    if (err) {
      return next(err);
    }

    // 4. Double Submit Cookie Pattern:
    // Send the token in a non-HttpOnly cookie so Axios/Fetch can read it
    // and attach it to the X-XSRF-TOKEN header on subsequent requests.
    if (req.csrfToken) {
      res.cookie('XSRF-TOKEN', req.csrfToken(), {
        domain: process.env.COOKIE_DOMAIN || undefined,
        path: '/',
        httpOnly: false, // Must be readable by client JS
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
      });
    }

    next();
  });
}

import { PipeTransform, Injectable, BadRequestException } from '@nestjs/common';
import { validateGeneratedSql } from '../../ai/copilot/sql-validator';

@Injectable()
export class SqlInjectionPipe implements PipeTransform {
  transform(value: any) {
    let intentStr = '';
    if (typeof value === 'string') {
      intentStr = value;
    } else if (typeof value === 'object' && value !== null && value.intent) {
      intentStr = value.intent;
    }

    if (intentStr && intentStr.toUpperCase().includes('SELECT ')) {
      // If the intent happens to be a direct SELECT query injection attempt, validate it structurally.
      // We pass some mock allowedTables just to not crash, though if it's an injection it'll fail other rules.
      const res = validateGeneratedSql(intentStr, [
        'Trip',
        'Load',
        'Vehicle',
        'FuelEntry',
        'Expense',
        'Invoice',
        'Driver',
        'Customer',
      ]);
      if (!res.ok) {
        throw new BadRequestException(
          'Potential SQL Injection detected: ' + res.reason,
        );
      }
    }
    return value;
  }
}

export function redactPii(data: any): any {
  if (data === null || data === undefined) {
    return data;
  }

  const sensitiveKeys = [
    'password',
    'passwordHash',
    'token',
    'accessToken',
    'refreshToken',
    'secret',
    'apiKey',
    'totpSecret',
    'clientSecret',
    'creditCard',
    'ssn',
    'taxId',
    'authorization',
  ];

  if (Array.isArray(data)) {
    return data.map((item) => redactPii(item));
  } else if (typeof data === 'object') {
    const redactedData: any = {};
    for (const [key, value] of Object.entries(data)) {
      if (
        sensitiveKeys.some((sensitiveKey) =>
          key.toLowerCase().includes(sensitiveKey.toLowerCase()),
        )
      ) {
        redactedData[key] = '[REDACTED]';
      } else {
        redactedData[key] = redactPii(value);
      }
    }
    return redactedData;
  }

  return data;
}

import {
  ServiceUnavailableException,
  Injectable,
  Logger,
} from '@nestjs/common';

@Injectable()
export class EmailProvider {
  private readonly logger = new Logger(EmailProvider.name);

  async send(to: string, _payload: any): Promise<any> {
    if (!process.env.SENDGRID_API_KEY) {
      this.logger.error(
        `Email provider is not configured. Failed to send to ${to}`,
      );
      throw new ServiceUnavailableException(
        'Email provider (SendGrid) is not configured.',
      );
    }
    this.logger.log(`Sending Email via SendGrid to ${to}`);
    // Real implementation would be: return sgMail.send(...)
    return { id: 'email_' + Date.now(), status: 'delivered' };
  }
}

