      user.companyId,
      async (tx) =>
        tx.announcement.create({
          data: {
            companyId: user.companyId,
            title: (dto as any).title,
            content: (dto as any).content,
            status: 'PUBLISHED',
          },
        }),
    );

    return { data: announcement };
  }
