      tx.notificationPreference.update({
        where: { userId: user.id },
        data: {
          channels: (dto as any).channels,
          quietHoursStart: (dto as any).quietHoursStart,
          quietHoursEnd: (dto as any).quietHoursEnd,
        },
      }),
    );

    return { data: prefs };
  }
}

