import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { parse } from 'json2csv';
import * as archiver from 'archiver';
import { Response } from 'express';

@Injectable()
export class ExportService {
  private readonly logger = new Logger(ExportService.name);

  constructor(private readonly prisma: PrismaService) {}

  async exportCompanyData(
    companyId: string,
    modules: string[],
    format: string,
    res: Response,
  ) {
    this.logger.log(
      `Starting enterprise export for company ${companyId}, modules: ${modules.join(',')}`,
    );

    const exportData: Record<string, any[]> = {};

    // Enforce tenant isolation via Prisma runAsTenant where applicable, or explicit where checks
    if (modules.includes('Fleet')) {
      exportData.vehicles = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.vehicle.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Drivers')) {
      exportData.drivers = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.driver.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Customers')) {
      exportData.customers = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.customer.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('Loads')) {
      exportData.loads = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.load.findMany({
          where: { companyId },
          take: 10000,
        }),
      );
    }
    if (modules.includes('Trips')) {
      exportData.trips = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.trip.findMany({
          where: { companyId },
          take: 10000,
        }),
      );
    }
    if (modules.includes('Invoices')) {
      exportData.invoices = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.invoice.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }
    if (modules.includes('AuditLogs')) {
      exportData.auditLogs = await this.prisma.runAsTenant(
        companyId,
        async (tx) =>
          tx.auditLog.findMany({
            where: { companyId },
            take: 10000,
          }),
      );
    }

    if (format.toLowerCase() === 'json') {
      res.setHeader('Content-Type', 'application/json');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="parilink_export_${companyId}.json"`,
      );
      return res.send(exportData);
    }

    if (format.toLowerCase() === 'csv') {
      const archive = (archiver as any)('zip', { zlib: { level: 9 } });
      res.setHeader('Content-Type', 'application/zip');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="parilink_export_${companyId}.zip"`,
      );

      archive.pipe(res);

      for (const [key, data] of Object.entries(exportData)) {
        if (data.length > 0) {
          try {
            const csv = parse(data);
            archive.append(csv, { name: `${key}.csv` });
          } catch (err) {
            this.logger.error(`Error parsing CSV for ${key}`, err);
          }
        }
      }

      await archive.finalize();
      return;
    }

    throw new BadRequestException(`Unsupported export format: ${format}`);
  }
}

import { AuditService } from '../platform/audit/audit.service';
import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class ImportService {
  private readonly logger = new Logger(ImportService.name);

  constructor(
    private readonly auditService: AuditService,
    private readonly prisma: PrismaService,
  ) {}

  async importData(
    companyId: string,
    moduleType: string,
    data: any[],
    userId: string,
  ) {
    this.logger.log(
      `Starting enterprise import for company ${companyId}, module: ${moduleType}`,
    );

    // Enterprise safeguards: Rollback on failure, limit to 1000 rows
    if (data.length > 1000) {
      throw new BadRequestException(
        'Import payload exceeds maximum allowed size of 1000 records per batch.',
      );
    }

    try {
      return await this.prisma.$transaction(async (tx) => {
        let importedCount = 0;
        if (moduleType === 'Customers') {
          const customersToCreate = data.map((record) => ({
            companyId,
            name: record.name,
            email: record.email,
            phone: record.phone,
            status: 'ACTIVE',
          }));

          const result = await tx.customer.createMany({
            data: customersToCreate,
            skipDuplicates: true,
          });
          importedCount = result.count;
        }

        // Log Audit Event
        await this.auditService.logEvent(
          {
            companyId,
            userId,
            action: 'BULK_IMPORT',
            entity: moduleType,
            entityId: 'BATCH',
            details: { recordCount: importedCount },
          },
          null,
          tx,
        );

        return { success: true, importedCount };
      });
    } catch (error) {
      this.logger.error('Import transaction failed, rolling back.', error);
      throw new BadRequestException(
        'Import failed due to validation or integrity errors.',
      );
    }
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { AuditService } from '../platform/audit/audit.service';
import {
  CreateDeveloperAppDto,
  UpdateDeveloperAppDto,
} from './dto/developer.dto';
import * as crypto from 'crypto';

@Injectable()
export class DeveloperService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly audit: AuditService,
  ) {}

  private generateClientSecret(): string {
    return 'sk_dev_' + crypto.randomBytes(32).toString('hex');
  }

  async createApp(
    companyId: string,
    userId: string,
    dto: CreateDeveloperAppDto,
  ) {
    const clientId = 'ca_' + crypto.randomBytes(16).toString('hex');
    const clientSecret = this.generateClientSecret();

    const app = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.create({
        data: {
          companyId,
          name: dto.name,
          description: dto.description,
          websiteUrl: dto.websiteUrl,
          clientId,
          clientSecret,
          environment: dto.environment || 'DEVELOPMENT',
          scopes: dto.scopes || [],
          redirectUris: dto.redirectUris || [],
          webhookUrl: dto.webhookUrl,
        },
      }),
    );

    await this.audit.logEvent({
      companyId,
      userId,
      entity: 'DeveloperApp',
      entityId: app.id,
      action: 'CREATE',
      details: { name: app.name, environment: app.environment },
    });

    return app;
  }

  async getApps(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.findMany({
        where: { companyId },
        orderBy: { createdAt: 'desc' },
      }),
    );
  }

  async getApp(companyId: string, id: string) {
    const app = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.findUnique({
        where: { id, companyId },
      }),
    );

    if (!app || app.companyId !== companyId) {
      throw new NotFoundException('Developer Application not found');
    }

    return app;
  }

  async updateApp(
    companyId: string,
    id: string,
    userId: string,
    dto: UpdateDeveloperAppDto,
  ) {
    // @ts-ignore: reserved for future use
    const _app = await this.getApp(companyId, id);

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.update({
        where: { id, companyId },
        data: {
          name: dto.name,
          description: dto.description,
          websiteUrl: dto.websiteUrl,
          scopes: dto.scopes,
          redirectUris: dto.redirectUris,
          webhookUrl: dto.webhookUrl,
        },
      }),
    );

    await this.audit.logEvent({
      companyId,
      userId,
      entity: 'DeveloperApp',
      entityId: id,
      action: 'UPDATE',
      details: { updates: Object.keys(dto) },
    });

    return updated;
  }

  async rotateSecret(companyId: string, id: string, userId: string) {
    // @ts-ignore: reserved for future use
    const _app = await this.getApp(companyId, id);
    const newSecret = this.generateClientSecret();

    const updated = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.update({
        where: { id, companyId },
        data: { clientSecret: newSecret },
      }),
    );

    await this.audit.logEvent({
      companyId,
      userId,
      entity: 'DeveloperApp',
      entityId: id,
      action: 'UPDATE',
      details: { action: 'ROTATE_SECRET' },
    });

    return { clientSecret: updated.clientSecret };
  }

  async deleteApp(companyId: string, id: string, userId: string) {
    const app = await this.getApp(companyId, id);

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.developerApp.delete({ where: { id, companyId } }),
    );

    await this.audit.logEvent({
      companyId,
      userId,
      entity: 'DeveloperApp',
      entityId: id,
      action: 'DELETE',
      details: { name: app.name },
    });

    return { success: true };
  }
}

