      expect(result.pendingLoads).toHaveLength(1);
      expect(result.availableDrivers).toHaveLength(1);
      expect(result.metrics.pendingLoadsCount).toBe(1);
      expect(result.metrics.availableDriversCount).toBe(1);
      expect(result.metrics.activeTripsCount).toBe(1);

      // ── Strict tenant-isolation assertions ──────────────────────────────
      expect(mockTx.load.findMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ companyId: 'company-1' }),
        }),
      );
      expect(mockTx.driver.findMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ companyId: 'company-1' }),
        }),
      );
      expect(mockTx.trip.findMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ companyId: 'company-1' }),
        }),
      );
    });
  });

  describe('moveBoardCard', () => {
    it('should throw BadRequestException if load not found', async () => {
      mockTx.load.findFirst.mockResolvedValue(null);
      await expect(
        service.moveBoardCard('company-1', 'load-1', 'IN_PROGRESS', 2),
      ).rejects.toThrow(BadRequestException);
    });

    it('should update load status and position', async () => {
      const mockLoad = { id: 'load-1', status: 'PENDING' };
      mockTx.load.findFirst.mockResolvedValue(mockLoad);
      mockTx.load.update.mockResolvedValue({
        ...mockLoad,
        status: 'IN_PROGRESS',
        boardPosition: 2,
      });

      const result = await service.moveBoardCard(
        'company-1',
        'load-1',
        'IN_PROGRESS',
        2,
      );
      expect(result.status).toBe('IN_PROGRESS');
    });
  });

  describe('Tenant Isolation', () => {
    it('should always call runAsTenant with the provided companyId', async () => {
      mockTx.load.findMany.mockResolvedValue([]);
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.vehicle.findMany.mockResolvedValue([]);
      mockTx.trip.findMany.mockResolvedValue([]);

      await service.getBoardData('company-specific-id');

      expect(mockPrisma.runAsTenant).toHaveBeenCalledWith(
        'company-specific-id',
        expect.any(Function),
      );
    });

    it('should not allow data from a different company', async () => {
      // Each runAsTenant call is scoped — verify it is not called with the wrong ID
      mockTx.load.findMany.mockResolvedValue([]);
      mockTx.driver.findMany.mockResolvedValue([]);
      mockTx.vehicle.findMany.mockResolvedValue([]);
      mockTx.trip.findMany.mockResolvedValue([]);

      await service.getBoardData('company-A');

      const calls = mockPrisma.runAsTenant.mock.calls;
      expect(calls.every((c) => c[0] === 'company-A')).toBe(true);
    });
  });
});

import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { TwilioService } from '../integrations/twilio.service';
import { AuditService } from '../platform/audit/audit.service';
import { EventStoreService } from '../platform/digital-twin/event-store.service';

@Injectable()
export class DispatchService {
  constructor(
    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
    // @ts-ignore: DI dependency reserved for future use
    private _twilioService: TwilioService,
    private readonly auditService: AuditService,
    private readonly eventStore: EventStoreService,
  ) {}

  async getBoardData(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const [
        pendingLoads,
        availableDrivers,
        availableVehicles,
        availableTrailers,
        activeTrips,
      ] = await Promise.all([
        // 1. Pending Loads
        tx.load.findMany({
          where: { companyId, status: 'PENDING' },
          include: { customer: true },
          orderBy: { createdAt: 'desc' },
          take: 50,
        }),

        // 2. Available Drivers
        tx.driver.findMany({
          where: { companyId, status: 'AVAILABLE' },
          orderBy: { firstName: 'asc' },
          take: 100,
        }),

        // 3. Available Vehicles
        tx.vehicle.findMany({
          where: {
            companyId,
            status: 'IN_SERVICE',
            type: { not: 'TRAILER' },
          },
          orderBy: { licensePlate: 'asc' },
          take: 100,
        }),

        // 4. Available Trailers
        tx.vehicle.findMany({
          where: {
            companyId,
            status: 'IN_SERVICE',
            type: 'TRAILER',
          },
          orderBy: { licensePlate: 'asc' },
          take: 100,
        }),

        // 5. Active Trips
        tx.trip.findMany({
          where: {
            companyId,
            status: { in: ['PLANNED', 'DISPATCHED', 'IN_PROGRESS'] },
          },
          include: { driver: true, vehicle: true, trailer: true, loads: true },
          orderBy: { startDate: 'asc' },
          take: 100,
        }),
      ]);

      return {
        pendingLoads,
        availableDrivers,
        availableVehicles,
        availableTrailers,
        activeTrips,
        metrics: {
          pendingLoadsCount: pendingLoads.length,
          availableDriversCount: availableDrivers.length,
          availableVehiclesCount: availableVehicles.length,
          availableTrailersCount: availableTrailers.length,
          activeTripsCount: activeTrips.length,
        },
      };
    });
  }

  async moveBoardCard(
    companyId: string,
    loadId: string,
    newStatus: string,
    boardPosition: number,
  ) {
    const updatedLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id: loadId, companyId },
      });

      if (!existingLoad) {
        throw new BadRequestException('Load not found');
      }

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'DISPATCH',
        trigger: 'BOARD_CARD_MOVED',
        entityData: { load: existingLoad, newStatus, boardPosition },
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Dispatch move rejected by business rules.',
        );
      }

      const load = await this.prisma.updateWithOcc<any>(
        tx,
        'load',
        loadId,
        existingLoad.updatedAt,
        { status: newStatus, boardPosition },
      );

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Dispatch',
          entityType: 'Load',
          entityId: load.id,
          action: 'BOARD_CARD_MOVED',
          beforeValue: {
            status: existingLoad.status,
            boardPosition: existingLoad.boardPosition,
          },
          afterValue: { status: newStatus, boardPosition },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'DISPATCH',
        streamId: load.id,
        eventType: 'BoardCardMoved',
        payload: { status: newStatus, boardPosition },
      });

      return load;
    });

    this.eventEmitter.emit('dispatch.updated', {
      loadId,
      newStatus,
      boardPosition,
    });

    return updatedLoad;
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { PredictionEngineService } from '../../ai/prediction/prediction.service';

@Injectable()
export class AiOperationsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly aiPrediction: PredictionEngineService,
  ) {}

  /**
   * Predicts ETAs for active trips dynamically based on current GPS, weather, and historical telemetry.
   * Target execution: Background or fast query (<100ms)
   */
  async predictTripEta(companyId: string, tripId: string) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: { id: tripId, companyId },
        include: { loads: true },
      }),
    );

    if (!trip) return null;

    // Call underlying AI Prediction Service
    const prediction = await this.aiPrediction.generatePrediction(
      companyId,
      'Trip',
      trip.id,
      {
        origin: trip.loads[0]?.originCity,
        destination: trip.loads[0]?.destinationCity,
        departureTime: trip.startDate,
        currentTime: new Date(),
      },
    );

    const predictedData = prediction?.predictedValue as any;
    if (predictedData && predictedData.eta) {
      const newEta = new Date(predictedData.eta);
      // Update trip ETA
      await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.trip.update({
          where: { id: trip.id },
          data: { eta: newEta },
        }),
      );

      // Issue event for potential delay
      if (trip.eta && newEta > trip.eta) {
        await this.eventStore.append({
          tenantId: companyId,
          streamId: trip.id,
          streamType: 'TRIP',
          eventType: 'TripDelayPredicted',
          payload: { originalEta: trip.eta, newEta },
          userId: 'SYSTEM',
        });
      }
    }

    return prediction;
  }

  /**
   * Evaluates Risk Scoring for a trip based on driver behavior, vehicle maintenance, and route weather.
   */
  async evaluateRiskScore(
    companyId: string,
    tripId: string,
  ): Promise<{ score: number; factors: string[] }> {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: { id: tripId, companyId },
        include: { driver: true, vehicle: true },
      }),
    );

    if (!trip) return { score: 0, factors: [] };

    let score = 0;
    const factors: string[] = [];

    // Simple heuristic-based risk for speed, actual AI would use tensor scoring
    if (trip.driver) {
      // check violations (mock)
      const violations = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            entity: 'Driver',
            entityId: trip.driver?.id || '',
            action: 'OVERSPEED_DETECTED',
          },
        }),
      );
      if (violations > 0) {
        score += violations * 10;
        factors.push(`${violations} recent speed violations`);
      }
    }

    if (trip.vehicle) {
      // Mock logic: checking recent incidents or breakdowns
      const incidents = await this.prisma.runAsTenant(companyId, async (tx) =>
        tx.auditLog.count({
          where: {
            entity: 'Vehicle',
            entityId: trip.vehicle?.id || '',
            action: 'BREAKDOWN_REPORTED',
          },
        }),
      );
      if (incidents > 0) {
        score += 30;
        factors.push(`Recent breakdowns reported on vehicle`);
      }
    }

    return { score: Math.min(score, 100), factors };
  }

  async recommendDriverForLoad(companyId: string, loadId: string) {
    const load = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.load.findFirst({
        where: { id: loadId, companyId },
      }),
    );
    if (!load) return [];

    // Find available drivers and score them based on proximity and duty hours
    const availableDrivers = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.driver.findMany({
          where: { companyId, status: 'AVAILABLE' },
        }),
    );

    return availableDrivers
      .map((d, index) => ({
        driverId: d.id,
        name: `${d.firstName} ${d.lastName}`,
        score: 85 - index * 5, // Deterministic placeholder score
        reason: 'Optimal duty hours and proximity',
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, 5);
  }
}

import { Injectable } from '@nestjs/common';

export interface ConstraintContext {
  load: {
    weight?: number | null;
    volume?: number | null;
    equipmentType?: string | null;
    pickupDate: Date;
    deliveryDate: Date;
  };
  vehicle: {
    id: string;
    capacityWeight?: number | null;
    capacityVolume?: number | null;
    type: string;
    status: string;
  };
  driver: {
    id: string;
    licenseExpiry?: Date | null;
    status: string;
  };
}

export interface ConstraintResult {
  passed: boolean;
  violations: Array<{
    constraint: string;
    message: string;
    isFatal: boolean;
    vehicleId?: string;
    driverId?: string;
  }>;
}

@Injectable()
export class ConstraintEngine {
  evaluate(ctx: ConstraintContext, config?: any): ConstraintResult {
    const violations: ConstraintResult['violations'] = [];

    // Default strictness to true if not provided in config
    const strictWeight = config?.strictWeight !== false;
    const strictVolume = config?.strictVolume !== false;

    // ── Vehicle Constraints ─────────────────────────────────

    // 1. Vehicle must be IN_SERVICE
    if (ctx.vehicle.status !== 'IN_SERVICE') {
      violations.push({
        constraint: 'VEHICLE_NOT_AVAILABLE',
        message: `Vehicle ${ctx.vehicle.id} status is ${ctx.vehicle.status}, not IN_SERVICE.`,
        isFatal: true,
        vehicleId: ctx.vehicle.id,
      });
    }

    // 2. Weight Capacity
    if (ctx.load.weight && ctx.vehicle.capacityWeight) {
      if (ctx.load.weight > ctx.vehicle.capacityWeight) {
        violations.push({
          constraint: 'WEIGHT_EXCEEDED',
          message: `Load weight ${ctx.load.weight}kg exceeds vehicle capacity ${ctx.vehicle.capacityWeight}kg.`,
          isFatal: strictWeight,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // 3. Volume Capacity
    if (ctx.load.volume && ctx.vehicle.capacityVolume) {
      if (ctx.load.volume > ctx.vehicle.capacityVolume) {
        violations.push({
          constraint: 'VOLUME_EXCEEDED',
          message: `Load volume ${ctx.load.volume}m³ exceeds vehicle capacity ${ctx.vehicle.capacityVolume}m³.`,
          isFatal: strictVolume,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // 4. Equipment Type Compatibility
    if (ctx.load.equipmentType && ctx.vehicle.type) {
      if (
        ctx.load.equipmentType === 'REFRIGERATED' &&
        ctx.vehicle.type !== 'REEFER'
      ) {
        violations.push({
          constraint: 'EQUIPMENT_MISMATCH',
          message: `Load requires REFRIGERATED equipment but vehicle type is ${ctx.vehicle.type}.`,
          isFatal: true,
          vehicleId: ctx.vehicle.id,
        });
      }
    }

    // ── Driver Constraints ──────────────────────────────────

    // 5. Driver must be AVAILABLE
    if (ctx.driver.status !== 'AVAILABLE') {
      violations.push({
        constraint: 'DRIVER_NOT_AVAILABLE',
        message: `Driver ${ctx.driver.id} status is ${ctx.driver.status}, not AVAILABLE.`,
        isFatal: true,
        driverId: ctx.driver.id,
      });
    }

    // 6. Driver Licence Expiry
    if (ctx.driver.licenseExpiry) {
      const now = new Date();
      if (ctx.driver.licenseExpiry < now) {
        violations.push({
          constraint: 'LICENSE_EXPIRED',
          message: `Driver ${ctx.driver.id} licence expired on ${ctx.driver.licenseExpiry.toISOString()}.`,
          isFatal: true,
          driverId: ctx.driver.id,
        });
      }
      // Warn if licence expires within 30 days
      const thirtyDays = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
      if (ctx.driver.licenseExpiry < thirtyDays) {
        violations.push({
          constraint: 'LICENSE_EXPIRING_SOON',
          message: `Driver ${ctx.driver.id} licence expires on ${ctx.driver.licenseExpiry.toISOString()}.`,
          isFatal: false,
          driverId: ctx.driver.id,
        });
      }
    }

    return {
      passed: violations.filter((v) => v.isFatal).length === 0,
      violations,
    };
  }
}

