import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

export interface PricingContext {
  companyId: string;
  customerId: string;
  distanceKm?: number;
  weightKg?: number;
  volumeM3?: number;
  stops?: number;
  isHazmat?: boolean;
  baseFuelPrice?: number;
  currentFuelPrice?: number;
  detentionHours?: number;
}

export interface PricingResult {
  baseFreight: number;
  fuelSurcharge: number;
  accessorialCharges: Array<{
    type: string;
    amount: number;
    description: string;
  }>;
  totalAmount: number;
}

@Injectable()
export class PricingEngine {
  private readonly logger = new Logger(PricingEngine.name);

  // @ts-ignore: DI dependency reserved for future use
  constructor(private readonly _prisma: PrismaService) {}

  /**
   * Calculates dynamic multi-modal pricing.
   * Supports Contract Pricing, Spot Pricing, Distance/Weight based, and Accessorials.
   */
  async calculatePrice(ctx: PricingContext): Promise<PricingResult> {
    this.logger.log(`Evaluating Pricing for Customer ${ctx.customerId}`);

    // In a full implementation, query Contract rules. We will implement robust heuristic logic.
    let baseFreight = 0;
    const accessorialCharges = [];

    // Base Freight: Distance * Rate or Weight * Rate
    if (ctx.distanceKm) {
      baseFreight = ctx.distanceKm * 2.5; // $2.50 per km base rate
    } else if (ctx.weightKg) {
      baseFreight = (ctx.weightKg / 1000) * 50; // $50 per ton
    } else {
      baseFreight = 500; // Minimum Spot Freight
    }

    // Fuel Surcharge (FSC)
    let fuelSurcharge = 0;
    if (
      ctx.currentFuelPrice &&
      ctx.baseFuelPrice &&
      ctx.currentFuelPrice > ctx.baseFuelPrice
    ) {
      const fscMultiplier = 0.05; // 5% for every $1 over base
      const overage = ctx.currentFuelPrice - ctx.baseFuelPrice;
      fuelSurcharge = baseFreight * (overage * fscMultiplier);
    }

    // Detention Charges
    if (ctx.detentionHours && ctx.detentionHours > 2) {
      // Free time is 2 hours
      const billableHours = ctx.detentionHours - 2;
      const detentionAmount = billableHours * 50; // $50/hr
      accessorialCharges.push({
        type: 'DETENTION',
        amount: detentionAmount,
        description: `${billableHours} hours detention`,
      });
    }

    // Multi-stop Charges
    if (ctx.stops && ctx.stops > 1) {
      const stopAmount = (ctx.stops - 1) * 75; // $75 per extra stop
      accessorialCharges.push({
        type: 'EXTRA_STOP',
        amount: stopAmount,
        description: `${ctx.stops - 1} extra stops`,
      });
    }

    // Hazmat
    if (ctx.isHazmat) {
      accessorialCharges.push({
        type: 'HAZMAT',
        amount: 200,
        description: 'Hazardous materials surcharge',
      });
    }

    const totalAccessorials = accessorialCharges.reduce(
      (acc, c) => acc + c.amount,
      0,
    );
    const totalAmount = baseFreight + fuelSurcharge + totalAccessorials;

    return {
      baseFreight,
      fuelSurcharge,
      accessorialCharges,
      totalAmount,
    };
  }
}

import {
  Controller,
  Post,
  Body,
  Headers,
  UnauthorizedException,
  Req,
} from '@nestjs/common';
import type { RawBodyRequest } from '@nestjs/common';
import type { Request } from 'express';
import * as crypto from 'crypto';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { IoTService } from './iot.service';
import { ApiKeyService } from '../../iam/services/api-keys.service';
import { SecretsService } from '../../platform/security/secrets/secrets.service';

@ApiTags('fleet/iot')
@Controller('fleet/iot')
export class IoTController {
  constructor(
    private readonly iotService: IoTService,
    private readonly apiKeyService: ApiKeyService,
    private readonly secretsService: SecretsService,
  ) {}

  @Post('webhook/:providerId')
  @ApiOperation({ summary: 'Receive webhook payloads from IoT providers' })
  async handleWebhook(
    @Req() req: RawBodyRequest<Request>,
    @Body() payload: any,
    @Headers('x-api-key') apiKey: string,
    @Headers('x-provider-signature') signature: string,
  ) {
    if (!apiKey) {
      throw new UnauthorizedException('Missing IoT API Key');
    }

    const validKey = await this.apiKeyService.validateApiKey(apiKey);
    if (!validKey) {
      throw new UnauthorizedException('Invalid IoT API Key');
    }

    if (!signature) {
      throw new UnauthorizedException('Missing x-provider-signature header');
    }

    const secret = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'IOT_PROVIDER',
      'WEBHOOK_SECRET',
    );
    if (!secret) {
      throw new UnauthorizedException('Webhook secret not configured');
    }

    const rawBody = req.rawBody;
    if (!rawBody) {
      throw new UnauthorizedException('Missing raw body');
    }

    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(rawBody)
      .digest('hex');

    const expectedBuffer = Buffer.from(expectedSignature, 'hex');
    // Ensure the incoming signature is valid hex to prevent Buffer.from throwing
    const signatureBuffer = Buffer.from(
      /^[0-9a-fA-F]+$/.test(signature) ? signature : '',
      'hex',
    );

    if (
      expectedBuffer.length !== signatureBuffer.length ||
      !crypto.timingSafeEqual(expectedBuffer, signatureBuffer)
    ) {
      throw new UnauthorizedException('Invalid signature');
    }

    return this.iotService.ingestTelemetry('generic', payload);
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class IoTService {
  constructor(private prisma: PrismaService) {}

  async ingestTelemetry(providerId: string, payload: any) {
    // In production, this would parse provider-specific formats (e.g. LocoNav, Samsara)
    // and potentially push to a BullMQ queue for async processing.

    // For now, assume a generic payload format:
    // { vehicleId, latitude, longitude, speed, fuelLevel, timestamp }

    // Example: Log to VehicleLocation for real-time map plotting
    if (payload.vehicleId && payload.latitude && payload.longitude) {
      await this.prisma.runAsTenant(payload.companyId, async (tx) =>
        tx.vehicleLocation.create({
          data: {
            companyId: 'UNKNOWN_COMPANY', // In prod, this would map from the provider settings
            provider: providerId,
            providerVehicleId: payload.vehicleId,
            vehicleId: payload.vehicleId,
            latitude: payload.latitude,
            longitude: payload.longitude,
            speed: payload.speed || 0,
            heading: payload.heading || 0,
            gpsTimestamp: payload.timestamp
              ? new Date(payload.timestamp)
              : new Date(),
          },
        }),
      );
    }

    return { status: 'ingested' };
  }
}

