import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';
import { InvoicesService } from '../../invoices/invoices.service';

/**
 * Enterprise Logistics Operating Model (ELOM) Orchestrator.
 * Subscribes to cross-domain events and orchestrates automated business processes.
 */
@Injectable()
export class ElomOrchestratorService {
  private readonly logger = new Logger(ElomOrchestratorService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
    private readonly invoicesService: InvoicesService,
  ) {}

  /**
   * Listen for Trip Completion -> Automatically generate Invoice
   */
  @OnEvent('EventStore.*')
  async handleGlobalEvents(payload: any) {
    if (!payload || !payload.eventType) return;

    try {
      switch (payload.eventType) {
        case 'LifecycleStateChangedToCOMPLETED':
          if (payload.streamType === 'TRIP') {
            await this.handleTripCompleted(
              payload.tenantId,
              payload.streamId,
              payload.userId,
            );
          }
          break;

        case 'InvoiceGenerated':
          // Auto-approve or schedule for payment depending on rules
          await this.handleInvoiceGenerated(
            payload.tenantId,
            payload.streamId,
            payload.userId,
          );
          break;

        case 'PaymentReceived':
          await this.handlePaymentReceived(
            payload.tenantId,
            payload.streamId,
            payload.userId,
          );
          break;

        case 'SettlementCompleted':
          this.logger.log(
            `ELOM: Settlement ${payload.streamId} completed. Pushing to external Accounting ledger.`,
          );
          // Stub: Call accounting integration (ERP)
          break;

        case 'VehicleYardEntry':
          // Trigger Dock Scheduling or Maintenance check
          await this.handleYardEntry(
            payload.tenantId,
            payload.streamId,
            payload.payload,
            payload.userId,
          );
          break;
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      this.logger.error(
        `ELOM Orchestration failed for event ${payload.eventType} on ${payload.streamType} ${payload.streamId}: ${errorMessage}`,
      );
    }
  }

  private async handleTripCompleted(
    companyId: string,
    tripId: string,
    userId: string,
  ) {
    this.logger.log(
      `ELOM Orchestrating Post-Trip workflows for Trip ${tripId}`,
    );

    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId },
        include: { loads: true },
      }),
    );

    if (!trip || !trip.loads.length) return;

    // 1. Transition all associated Loads to DELIVERED / COMPLETED
    for (const load of trip.loads) {
      await this.lifecycle.transitionState({
        companyId,
        entityType: 'Load',
        entityId: load.id,
        fromState: load.status,
        toState: 'COMPLETED',
        userId,
        reason: `Auto-completed due to Trip ${trip.tripNumber} completion`,
      });

      // 2. Automatically generate an invoice for each load (Billing Integration)
      // Assuming InvoicesService has a createInvoice method for loads
      try {
        const invoice = await this.invoicesService.createInvoice(companyId, {
          customerId: load.customerId,
          loadId: load.id,
          amount: trip.fuelExpenses ? trip.fuelExpenses * 1.2 : 500, // Dummy pricing engine hook
          dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // Net 30
          invoiceNumber: `INV-${Date.now()}`,
        });

        if (invoice) {
          await this.eventStore.append({
            tenantId: companyId,
            streamId: invoice.id,
            streamType: 'INVOICE',
            eventType: 'InvoiceGenerated',
            payload: { loadId: load.id, amount: invoice.amount },
            userId,
          });
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        this.logger.warn(
          `Failed to auto-generate invoice for load ${load.id}: ${errorMessage}`,
        );
      }
    }
  }

  private async handleInvoiceGenerated(
    companyId: string,
    invoiceId: string,
    userId: string,
  ) {
    this.logger.log(`ELOM Auto-processing new Invoice ${invoiceId}`);
    // Transition invoice from DRAFT -> PENDING_APPROVAL automatically based on rules
    await this.lifecycle.transitionState({
      companyId,
      entityType: 'Invoice',
      entityId: invoiceId,
      fromState: 'DRAFT',
      toState: 'PENDING_APPROVAL',
      userId,
      reason: 'ELOM Auto-routing for financial approval',
    });
  }

  private async handlePaymentReceived(
    companyId: string,
    invoiceId: string,
    userId: string,
  ) {
    this.logger.log(
      `ELOM: Payment received for invoice ${invoiceId}, initiating settlement.`,
    );
    // Automatically transition to Settlement if payment is complete
    await this.eventStore.append({
      tenantId: companyId,
      streamId: invoiceId,
      streamType: 'SETTLEMENT',
      eventType: 'SettlementCompleted',
      payload: { invoiceId, status: 'PAID' },
      userId,
    });
  }

  private async handleYardEntry(
    _companyId: string,
    vehicleId: string,
    _data: any,
    _userId: string,
  ) {
    this.logger.log(
      `ELOM: Vehicle ${vehicleId} entered Yard. Checking pending maintenance.`,
    );
    // In a full implementation, check if the vehicle is scheduled for maintenance and route to the shop.
    // E.g., transition vehicle state to 'MAINTENANCE' if due.
  }
}

import type { AuthenticatedUser } from '../../auth/decorators/get-user.decorator';
import { GetUser } from '../../auth/decorators/get-user.decorator';
import {
  Controller,
  Get,
  Post,
  Body,
  Query,
  UseGuards,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import { EnterpriseEventBusService } from './enterprise-event-bus.service';

@ApiTags('Enterprise Event Bus')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('integration/events')
export class EnterpriseEventBusController {
  constructor(private readonly eventBus: EnterpriseEventBusService) {}

  @Post('publish')
  @RequirePermissions('integrations:write')
  @ApiOperation({
    summary: 'Publish a structured domain event to the enterprise event bus',
  })
  async publishEvent(
    @GetUser() user: AuthenticatedUser,
    @Body()
    dto: {
      streamId: string;
      streamType: string;
      eventType: string;
      payload: any;
      metadata?: any;
      correlationId?: string;
    },
  ) {
    return this.eventBus.publishEvent(user.companyId, user.userId, dto);
  }

  @Get('history')
  @RequirePermissions('integrations:read')
  @ApiOperation({ summary: 'List chronological domain event stream history' })
  async getEventHistory(
    @GetUser() user: AuthenticatedUser,
    @Query('streamType') streamType?: string,
    @Query('streamId') streamId?: string,
    @Query('eventType') eventType?: string,
    @Query('limit') limit?: number,
    @Query('offset') offset?: number,
  ) {
    return this.eventBus.getEventHistory(user.companyId, {
      streamType,
      streamId,
      eventType,
      limit: limit ? Number(limit) : 50,
      offset: offset ? Number(offset) : 0,
    });
  }

  @Post('replay')
  @RequirePermissions('integrations:write')
  @ApiOperation({
    summary:
      'Replay a sequence of domain events for state reconstruction or synchronization',
  })
  async replayEvents(
    @GetUser() user: AuthenticatedUser,
    @Body() dto: { streamId: string; fromVersion: number; toVersion: number },
  ) {
    if (
      !dto ||
      typeof dto.streamId !== 'string' ||
      dto.streamId.trim() === ''
    ) {
      throw new BadRequestException(
        'streamId is required and must be a non-empty string',
      );
    }
    return this.eventBus.replayEvents(
      user.companyId,
      dto.streamId,
      dto.fromVersion,
      dto.toVersion,
      user.userId,
    );
  }
}

import {
  Injectable,
  Logger,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AuditService } from '../../platform/audit/audit.service';
import * as crypto from 'crypto';

@Injectable()
export class EnterpriseEventBusService {
  private readonly logger = new Logger(EnterpriseEventBusService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventEmitter: EventEmitter2,
    private readonly audit: AuditService,
  ) {}

  async publishEvent(
    companyId: string,
    userId: string,
    dto: {
      streamId: string;
      streamType: string;
      eventType: string;
      payload: any;
      metadata?: any;
      correlationId?: string;
    },
  ) {
    if (!dto.streamId || !dto.streamType || !dto.eventType || !dto.payload) {
      throw new BadRequestException(
        'streamId, streamType, eventType, and payload are required',
      );
    }

    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Optimistic concurrency: find latest version for stream
      const lastEvent = await tx.domainEvent.findFirst({
        where: { streamId: dto.streamId },
        orderBy: { version: 'desc' },
      });
      const nextVersion = lastEvent ? lastEvent.version + 1 : 1;

      const eventRecord = await tx.domainEvent.create({
        data: {
          companyId,
          streamId: dto.streamId,
          streamType: dto.streamType.toUpperCase(),
          eventType: dto.eventType,
          version: nextVersion,
          payload: dto.payload,
          metadata: dto.metadata || {},
          correlationId: dto.correlationId || crypto.randomUUID(),
          userId,
        },
      });

      // Emit to internal bus for integration routing and digital twin updates
      const topic = `DomainEvent.${eventRecord.streamType}.${eventRecord.eventType}`;
      this.eventEmitter.emit(topic, {
        tenantId: companyId,
        eventId: eventRecord.id,
        streamId: eventRecord.streamId,
        version: eventRecord.version,
        payload: {
          data: {
            eventType: eventRecord.eventType,
            ...dto.payload,
          },
        },
      });

      this.logger.log(
        `Published event ${topic} (v${nextVersion}) for stream ${dto.streamId}`,
      );

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'DomainEvent',
        entityId: eventRecord.id,
        action: 'PUBLISH_EVENT',
        details: {
          streamId: dto.streamId,
          eventType: dto.eventType,
          version: nextVersion,
        },
      });

      return eventRecord;
    });
  }

  async getEventHistory(
    companyId: string,
    query: {
      streamType?: string;
      streamId?: string;
      eventType?: string;
      limit?: number;
      offset?: number;
    },
  ) {
    const where: any = { companyId };
    if (query.streamType) where.streamType = query.streamType.toUpperCase();
    if (query.streamId) where.streamId = query.streamId;
    if (query.eventType) where.eventType = query.eventType;

    const [events, total] = await Promise.all([
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.domainEvent.findMany({
          where,
          take: query.limit || 50,
          skip: query.offset || 0,
          orderBy: { timestamp: 'desc' },
        }),
      ),
      this.prisma.runAsTenant(companyId, async (tx) =>
        tx.domainEvent.count({ where }),
      ),
    ]);

    return {
      events,
      total,
      limit: query.limit || 50,
      offset: query.offset || 0,
    };
  }

  async replayEvents(
    companyId: string,
    streamId: string,
    fromVersion: number,
    toVersion: number,
    userId: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const events = await tx.domainEvent.findMany({
        where: {
          companyId,
          streamId,
          version: {
            gte: fromVersion,
            lte: toVersion,
          },
        },
        orderBy: { version: 'asc' },
      });

      if (events.length === 0) {
        throw new NotFoundException(
          `No domain events found for stream ${streamId} in the specified version range.`,
        );
      }

      let replayedCount = 0;
      for (const ev of events) {
        const topic = `DomainEvent.${ev.streamType}.${ev.eventType}`;
        this.eventEmitter.emit(topic, {
          tenantId: companyId,
          eventId: ev.id,
          streamId: ev.streamId,
          version: ev.version,
          isReplay: true,
          payload: {
            data: {
              eventType: ev.eventType,
              ...(ev.payload as any),
            },
          },
        });
        replayedCount++;
      }

      this.logger.log(
        `Replayed ${replayedCount} events for stream ${streamId}`,
      );

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'DomainEvent',
        entityId: streamId,
        action: 'REPLAY_STREAM_EVENTS',
        details: { fromVersion, toVersion, replayedCount },
      });

      return { streamId, replayedCount, status: 'REPLAYED' };
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { SyncEngineService } from '../sync/sync.service';

@Injectable()
export class EventIntegrationService {
  private readonly logger = new Logger(EventIntegrationService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly syncService: SyncEngineService,
  ) {}

  /**
   * Listen to all internal DomainEvents and route them to interested external connectors.
   */
  @OnEvent('DomainEvent.**')
  async handleDomainEvent(eventPayload: any) {
    if (!eventPayload || !eventPayload.tenantId || !eventPayload.payload)
      return;

    // Check if any connector supports this event topic (e.g. 'InvoiceGenerated')
    const topic = eventPayload.payload.data?.eventType;
    if (!topic) return;

    // In a production system, this mapping would be heavily cached in Redis.
    const connections = await this.prisma.runAsSystem(
      '[EventIntegrationService.handleDomainEvent] Internal service operation bypass',
      async (tx) =>
        tx.integrationConnection.findMany({
          where: {
            companyId: eventPayload.tenantId,
            status: 'ENABLED',
          },
          include: { connector: true },
        }),
    );

    for (const conn of connections) {
      const supportedEvents = conn.connector.supportedEvents as string[];
      if (supportedEvents && supportedEvents.includes(topic)) {
        this.logger.log(
          `Routing Event ${topic} to External Connector: ${conn.connector.provider}`,
        );

        // Trigger a push sync to the external system
        await this.syncService.triggerSync(
          eventPayload.tenantId,
          conn.id,
          topic,
          eventPayload.payload.data,
        );
      }
    }
  }
}

import { Logger } from '@nestjs/common';

export interface ConnectorConfig {
  id: string;
  name: string;
  type: 'REST' | 'GRAPHQL' | 'SOAP' | 'WEBHOOK' | 'FTP' | 'QUEUE';
  authType: 'API_KEY' | 'OAUTH2' | 'BASIC' | 'NONE';
  credentials: Record<string, string>;
  direction: 'INBOUND' | 'OUTBOUND' | 'BIDIRECTIONAL';
  status: 'ACTIVE' | 'INACTIVE' | 'ERROR';
  rateLimitPerMin?: number;
}

export interface SyncPayload {
  aggregateId: string;
  aggregateType: string;
  data: any;
}

export interface SyncResult {
  success: boolean;
  externalId?: string;
  error?: string;
  latencyMs: number;
}

export abstract class BaseConnector {
  protected readonly logger = new Logger(this.constructor.name);

  constructor(protected readonly config: ConnectorConfig) {}

  abstract authenticate(): Promise<boolean>;
  abstract validate(payload: SyncPayload): boolean;
  abstract sync(payload: SyncPayload): Promise<SyncResult>;

  async execute(payload: SyncPayload): Promise<SyncResult> {
    const start = Date.now();
    try {
      if (this.config.status !== 'ACTIVE') {
        throw new Error(`Connector ${this.config.name} is not active`);
      }

      await this.authenticate();

      if (!this.validate(payload)) {
        throw new Error(`Invalid payload for connector ${this.config.name}`);
      }

      const result = await this.sync(payload);
      return {
        ...result,
        latencyMs: Date.now() - start,
      };
    } catch (err: any) {
      this.logger.error(`Sync failed for ${this.config.name}: ${err.message}`);
      return {
        success: false,
        error: err.message,
        latencyMs: Date.now() - start,
      };
    }
  }

  getConfig(): ConnectorConfig {
    return this.config;
  }
}

