import {
  Injectable,
  // @ts-ignore: reserved for future use
  Logger,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { ConnectorRegistryService } from '../framework/registry.service';
import { IntegrationAuthService } from '../auth/auth.service';
import { AuditService } from '../../platform/audit/audit.service';

@Injectable()
export class EnterpriseIntegrationHubService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly registry: ConnectorRegistryService,
    private readonly auth: IntegrationAuthService,
    private readonly audit: AuditService,
  ) {}

  async getCatalog() {
    const dbConnectors = await this.prisma.runAsSystem(
      '[EnterpriseIntegrationHubService.getCatalog] Internal service operation bypass',
      async (tx) =>
        tx.integrationConnector.findMany({
          where: { status: 'ACTIVE' },
          include: { category: true },
        }),
    );
    return dbConnectors;
  }

  async getInstalledIntegrations(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.integrationConnection.findMany({
        where: { companyId },
        select: {
          id: true,
          companyId: true,
          connectorId: true,
          status: true,
          settings: true,
          lastSync: true,
          lastError: true,
          retryCount: true,
          createdAt: true,
          updatedAt: true,
          connector: true,
          syncJobs: { take: 5, orderBy: { createdAt: 'desc' } },
        },
      });
    });
  }

  async configureIntegration(
    companyId: string,
    userId: string,
    dto: {
      provider: string;
      credentials: any;
      settings?: any;
      isActive?: boolean;
    },
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const connector = this.registry.getConnector(dto.provider);
      if (!connector) {
        throw new BadRequestException(
          `Connector for provider ${dto.provider} is not available in registry.`,
        );
      }

      if (!connector.validateConfiguration(dto.credentials)) {
        throw new BadRequestException(
          `Invalid configuration credentials for ${dto.provider}. Required schema check failed.`,
        );
      }

      const isHealthy = await connector.testConnection(dto.credentials);
      if (!isHealthy) {
        throw new BadRequestException(
          `Connection test failed for provider ${dto.provider}. Please check your credentials.`,
        );
      }

      const encryptedCredentials = this.auth.encryptCredentials(
        dto.credentials,
      );

      let connectorRecord = await tx.integrationConnector.findUnique({
        where: { provider: dto.provider },
      });
      if (!connectorRecord) {
        connectorRecord = await tx.integrationConnector.create({
          data: {
            provider: dto.provider,
            version: connector.version,
            authType: connector.authType,
            status: 'ACTIVE',
          },
        });
      }

      const existing = await tx.integrationConnection.findFirst({
        where: { companyId, connectorId: connectorRecord.id },
      });

      let connection;
      if (existing) {
        connection = await tx.integrationConnection.update({
          where: { id: existing.id },
          data: {
            credentials: encryptedCredentials as any,
            settings: dto.settings || existing.settings,
            status: dto.isActive !== false ? 'ENABLED' : 'CONFIGURED',
          },
          include: { connector: true },
        });
      } else {
        connection = await tx.integrationConnection.create({
          data: {
            companyId,
            connectorId: connectorRecord.id,
            credentials: encryptedCredentials as any,
            settings: dto.settings || {},
            status: dto.isActive !== false ? 'ENABLED' : 'CONFIGURED',
          },
          include: { connector: true },
        });
      }

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'IntegrationConnection',
        entityId: connection.id,
        action: existing ? 'UPDATE_CONNECTION' : 'CREATE_CONNECTION',
        details: { provider: dto.provider, status: connection.status },
      });

      return connection;
    });
  }

  async enableIntegration(
    companyId: string,
    connectionId: string,
    userId: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existing = await tx.integrationConnection.findFirst({
        where: { id: connectionId, companyId },
      });
      if (!existing) throw new NotFoundException('Connection not found');

      const conn = await tx.integrationConnection.update({
        where: { id: connectionId },
        data: { status: 'ENABLED' },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'IntegrationConnection',
        entityId: connectionId,
        action: 'ENABLE_INTEGRATION',
        details: { status: 'ENABLED' },
      });

      return conn;
    });
  }

  async disableIntegration(
    companyId: string,
    connectionId: string,
    userId: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existing = await tx.integrationConnection.findFirst({
        where: { id: connectionId, companyId },
      });
      if (!existing) throw new NotFoundException('Connection not found');

      const conn = await tx.integrationConnection.update({
        where: { id: connectionId },
        data: { status: 'DISABLED' },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'IntegrationConnection',
        entityId: connectionId,
        action: 'DISABLE_INTEGRATION',
        details: { status: 'DISABLED' },
      });

      return conn;
    });
  }

  async updateVersion(
    companyId: string,
    connectionId: string,
    version: string,
    userId: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const conn = await tx.integrationConnection.findUnique({
        where: { id: connectionId },
        include: { connector: true },
      });
      if (!conn) throw new NotFoundException('Connection not found');

      await tx.integrationConnector.update({
        where: { id: conn.connectorId },
        data: { version },
      });

      await this.audit.logEvent({
        companyId,
        userId,
        entity: 'IntegrationConnection',
        entityId: connectionId,
        action: 'UPGRADE_VERSION',
        details: { oldVersion: conn.connector.version, newVersion: version },
      });

      return { ...conn, version };
    });
  }

  async checkHealth(companyId: string, connectionId: string) {
    const conn = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.integrationConnection.findUnique({
        where: { id: connectionId, companyId },
        include: { connector: true },
      }),
    );
    if (!conn) throw new NotFoundException('Connection not found');

    const connector = this.registry.getConnector(conn.connector.provider);
    if (!connector) {
      return {
        status: 'UNHEALTHY',
        error: 'Connector class not loaded',
        latencyMs: 0,
        lastChecked: new Date(),
      };
    }

    const start = Date.now();
    try {
      const credentials = this.auth.decryptCredentials(
        conn.credentials as string,
      );
      const isHealthy = await connector.healthCheck(credentials);
      const latencyMs = Date.now() - start;

      if (!isHealthy) {
        return { status: 'UNHEALTHY', latencyMs, lastChecked: new Date() };
      }
      return { status: 'HEALTHY', latencyMs, lastChecked: new Date() };
    } catch (e: any) {
      return {
        status: 'UNHEALTHY',
        error: e.message,
        latencyMs: Date.now() - start,
        lastChecked: new Date(),
      };
    }
  }
}

import type { AuthenticatedUser } from '../../auth/decorators/get-user.decorator';
import { GetUser } from '../../auth/decorators/get-user.decorator';
import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  Query,
  UseGuards,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import { ImportExportService } from './import-export.service';

@ApiTags('Import & Export Console')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('integration')
export class ImportExportController {
  constructor(private readonly importExportService: ImportExportService) {}

  @Post('import/preview')
  @RequirePermissions('integrations:read')
  @ApiOperation({
    summary: 'Preview bulk data import with validation and duplicate detection',
  })
  async previewImport(
    @GetUser() user: AuthenticatedUser,
    @Body() dto: { entityType: string; format: string; rows: any[] },
  ) {
    return this.importExportService.previewImport(
      user.companyId,
      dto.entityType,
      dto.format,
      dto.rows,
    );
  }

  @Post('import/execute')
  @RequirePermissions('integrations:write')
  @ApiOperation({
    summary: 'Execute bulk data import in transaction with rollback on error',
  })
  async executeImport(
    @GetUser() user: AuthenticatedUser,
    @Body()
    dto: {
      entityType: string;
      format: string;
      rows: any[];
      rollbackOnError?: boolean;
    },
  ) {
    return this.importExportService.executeImport(
      user.companyId,
      user.userId,
      dto.entityType,
      dto.format,
      dto.rows,
      dto.rollbackOnError !== false,
    );
  }

  @Post('export/execute')
  @RequirePermissions('integrations:read')
  @ApiOperation({
    summary: 'Execute bulk data export into CSV, XML, JSON, or Excel format',
  })
  async executeExport(
    @GetUser() user: AuthenticatedUser,
    @Body() dto: { entityType: string; format: string; filter?: any },
  ) {
    if (
      !dto ||
      typeof dto.entityType !== 'string' ||
      dto.entityType.trim() === ''
    ) {
      throw new BadRequestException(
        'entityType is required and must be a string',
      );
    }
    if (!dto.format || !['csv', 'json'].includes(dto.format.toLowerCase())) {
      throw new BadRequestException(
        'format is required and must be either csv or json',
      );
    }
    return this.importExportService.executeExport(
      user.companyId,
      user.userId,
      dto.entityType,
      dto.format,
      dto.filter,
    );
  }

  @Get('jobs')
  @RequirePermissions('integrations:read')
  @ApiOperation({ summary: 'List background sync, import, and export jobs' })
  async listJobs(
    @GetUser() user: AuthenticatedUser,
    @Query('type') type?: string,
  ) {
    return this.importExportService.listJobs(user.companyId, type);
  }

  @Get('jobs/:id')
  @RequirePermissions('integrations:read')
  @ApiOperation({
    summary: 'Get status and results of a background import/export job',
  })
  async getJobStatus(
    @GetUser() user: AuthenticatedUser,
    @Param('id') jobId: string,
  ) {
    return this.importExportService.getJobStatus(user.companyId, jobId);
  }
}

