import { Injectable, Logger } from '@nestjs/common';
import Razorpay from 'razorpay';
import crypto from 'crypto';
import { SecretsService } from '../platform/security/secrets/secrets.service';

@Injectable()
export class RazorpayService {
  private readonly logger = new Logger(RazorpayService.name);

  constructor(private readonly secretsService: SecretsService) {}

  private async getClient(): Promise<any> {
    const key_id = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'RAZORPAY',
      'KEY_ID',
    );
    const key_secret = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'RAZORPAY',
      'KEY_SECRET',
    );

    if (!key_id || !key_secret) {
      this.logger.warn(
        'Razorpay API keys missing from SecretsService. Billing disabled.',
      );
      return null;
    }

    return new Razorpay({
      key_id,
      key_secret,
    });
  }

  async createSubscription(
    planId: string,
    _customerId: string,
    totalCount = 12,
  ) {
    const razorpay = await this.getClient();
    if (!razorpay) throw new Error('Razorpay not configured');
    try {
      const subscription = await razorpay.subscriptions.create({
        plan_id: planId,
        customer_notify: 1,
        total_count: totalCount,
      });
      return subscription;
    } catch (error) {
      this.logger.error('Failed to create Razorpay subscription', error);
      throw error;
    }
  }

  async cancelSubscription(subscriptionId: string) {
    const razorpay = await this.getClient();
    if (!razorpay) throw new Error('Razorpay not configured');
    return await razorpay.subscriptions.cancel(subscriptionId);
  }

  verifyWebhookSignature(
    payload: string,
    signature: string,
    secret: string,
  ): boolean {
    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');
    return expectedSignature === signature;
  }
}

import { Processor, WorkerHost, OnWorkerEvent } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { ConnectorFactoryService } from '../connectors/connector-factory.service';
import { CryptoService } from '../security/crypto.service';

export interface SyncJobPayload {
  connectionId: string;
  entityType: string;
  userId: string;
  isFullSync?: boolean;
}

@Processor('integration-sync', { concurrency: 20 })
export class SyncEngineProcessor extends WorkerHost {
  private readonly logger = new Logger(SyncEngineProcessor.name);

  constructor(
    private prisma: PrismaService,
    private factory: ConnectorFactoryService,
    // @ts-ignore: DI dependency reserved for future use
    private _crypto: CryptoService,
  ) {
    super();
  }

  async process(job: Job<SyncJobPayload, any, string>): Promise<any> {
    this.logger.log(
      `Starting Sync Job ${job.id} for connection ${job.data.connectionId}`,
    );

    const connection = await this.prisma.runAsSystem(
      '[SyncEngineProcessor.process] Background job bypass',
      async (tx) =>
        tx.integrationConnection.findUnique({
          where: { id: job.data.connectionId },
          include: { connector: true },
        }),
    );

    if (!connection) {
      throw new Error(`Connection ${job.data.connectionId} not found`);
    }

    if (connection.status !== 'ACTIVE' && connection.status !== 'CONFIGURED') {
      throw new Error(`Connection is in invalid state: ${connection.status}`);
    }

    try {
      const connector = this.factory.getConnector(
        connection.connector.provider,
      );

      // Decrypt credentials
      // Note: In production, credentials should be decrypted properly.
      // Here we assume it's just parsed JSON for the MVP wrapper.
      const credentials =
        typeof connection.credentials === 'string'
          ? JSON.parse(connection.credentials)
          : connection.credentials;

      const lastSyncDate = job.data.isFullSync
        ? undefined
        : connection.lastSync || undefined;

      const result = await connector.syncEntity(
        job.data.entityType,
        credentials,
        lastSyncDate,
      );

      // Log success
      await this.prisma.runAsSystem(
        '[SyncEngineProcessor.process] Background job bypass',
        async (tx) =>
          tx.syncJob.create({
            data: {
              connectionId: connection.id,
              companyId: connection.companyId,
              entityType: job.data.entityType,
              direction: 'IMPORT',
              status: 'COMPLETED',
              recordsProcessed: result.recordsSynced,
              startedAt: new Date(job.timestamp),
              completedAt: new Date(),
            },
          }),
      );

      // Update connection
      await this.prisma.runAsSystem(
        '[SyncEngineProcessor.process] Background job bypass',
        async (tx) =>
          tx.integrationConnection.update({
            where: { id: connection.id },
            data: { lastSync: new Date(), lastError: null },
          }),
      );

      return result;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      const errorStack = error instanceof Error ? error.stack : undefined;
      this.logger.error(`Sync Job ${job.id} failed: ${errorMessage}`);

      // Log Error
      await this.prisma.runAsSystem(
        '[SyncEngineProcessor.process] Background job bypass',
        async (tx) =>
          tx.syncError.create({
            data: {
              connectionId: connection.id,
              errorMessage: errorMessage,
              errorStack: errorStack,
            },
          }),
      );

      // Update connection
      await this.prisma.runAsSystem(
        '[SyncEngineProcessor.process] Background job bypass',
        async (tx) =>
          tx.integrationConnection.update({
            where: { id: connection.id },
            data: { status: 'FAILED', lastError: errorMessage },
          }),
      );

      throw error;
    }
  }

  @OnWorkerEvent('completed')
  onCompleted(job: Job) {
    this.logger.log(`Job ${job.id} completed successfully`);
  }

  @OnWorkerEvent('failed')
  onFailed(job: Job, error: Error) {
    this.logger.error(`Job ${job.id} failed: ${error.message}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import twilio from 'twilio';
import { SecretsService } from '../platform/security/secrets/secrets.service';
import { CircuitBreakerService } from '../platform/resilience/circuit-breaker.service';

@Injectable()
export class TwilioService {
  private readonly logger = new Logger(TwilioService.name);

  constructor(
    private readonly secretsService: SecretsService,
    private readonly circuitBreaker: CircuitBreakerService,
  ) {}

  private async getClientInfo(): Promise<{
    client: any;
    fromPhone: string;
  } | null> {
    const sid = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'TWILIO',
      'ACCOUNT_SID',
    );
    const token = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'TWILIO',
      'AUTH_TOKEN',
    );
    const phone = await this.secretsService.retrieveIntegrationSecret(
      'SYSTEM',
      'TWILIO',
      'PHONE_NUMBER',
    );

    if (!sid || !token || !phone) {
      this.logger.warn(
        'Twilio credentials missing from SecretsService. WhatsApp dispatch disabled.',
      );
      return null;
    }

    return {
      client: twilio(sid, token),
      fromPhone: phone,
    };
  }

  async sendWhatsAppMessage(to: string, message: string) {
    const twilioInfo = await this.getClientInfo();
    if (!twilioInfo) {
      this.logger.warn(`Simulating WhatsApp to ${to}: ${message}`);
      return { sid: 'mock_sid' };
    }

    try {
      const response = await this.circuitBreaker.execute(
        'TWILIO',
        async () => {
          // Implement hard timeout via Promise.race
          const timeoutMs = 5000;
          const timeoutPromise = new Promise((_, reject) =>
            setTimeout(
              () => reject(new Error('Twilio request timed out')),
              timeoutMs,
            ),
          );

          return Promise.race([
            twilioInfo.client.messages.create({
              body: message,
              from: `whatsapp:${twilioInfo.fromPhone}`,
              to: `whatsapp:${to}`,
            }),
            timeoutPromise,
          ]);
        },
        { retryCount: 3, resetTimeoutMs: 15000, retryBaseDelayMs: 200 },
      );
      this.logger.log(`WhatsApp message sent to ${to}, SID: ${response.sid}`);
      return response;
    } catch (error) {
      this.logger.error('Failed to send WhatsApp message via Twilio', error);
      throw error;
    }
  }
}

import { CreateWebhookDto } from '../dto/webhook.dto';
import {
  Controller,
  Post,
  Body,
  Param,
  Headers,
  HttpException,
  HttpStatus,
  Logger,
  Req,
} from '@nestjs/common';
import { ApiTags, ApiOperation } from '@nestjs/swagger';
import { PrismaService } from '../../prisma/prisma.service';
import { IntegrationAuthService } from '../../integration/auth/auth.service';
import * as crypto from 'crypto';
import type { RawBodyRequest } from '@nestjs/common';
import type { Request } from 'express';

@ApiTags('webhooks')
@Controller('webhooks/v1')
export class WebhookController {
  private readonly logger = new Logger(WebhookController.name);

  constructor(
    private prisma: PrismaService,
    private authService: IntegrationAuthService,
  ) {}

  @Post('incoming/:provider/:connectionId')
  @ApiOperation({
    summary: 'Receive incoming webhooks from external providers',
  })
  async receiveWebhook(
    @Req() req: RawBodyRequest<Request>,
    @Param('provider') provider: string,
    @Param('connectionId') connectionId: string,
    @Headers('x-webhook-signature') signature: string,
    @Body() payload: CreateWebhookDto,
  ) {
    this.logger.log(
      `Received webhook from ${provider} for connection ${connectionId}`,
    );

    // Verify connection exists
    const connection = await this.prisma.runAsSystem(
      '[WebhookController.receiveWebhook] Webhook handler bypass',
      async (tx) =>
        tx.integrationConnection.findUnique({
          where: { id: connectionId },
          include: { connector: true },
        }),
    );

    if (!connection || !connection.credentials) {
      throw new HttpException('Connection not found', HttpStatus.NOT_FOUND);
    }

    let secret = '';
    try {
      const credsString =
        typeof connection.credentials === 'string'
          ? connection.credentials
          : JSON.stringify(connection.credentials);
      const credentials = this.authService.decryptCredentials(credsString);
      secret = credentials?.webhookSecret;
    } catch (e: any) {
      throw new HttpException(
        'Invalid credentials state',
        HttpStatus.UNAUTHORIZED,
      );
    }

    if (!secret) {
      throw new HttpException(
        'Webhook secret not configured',
        HttpStatus.UNAUTHORIZED,
      );
    }

    if (!signature) {
      throw new HttpException('Missing signature', HttpStatus.UNAUTHORIZED);
    }

    const payloadBuffer = req.rawBody || Buffer.from(JSON.stringify(payload));
    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(payloadBuffer)
      .digest('hex');

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (
      expectedBuffer.length !== actualBuffer.length ||
      !crypto.timingSafeEqual(expectedBuffer, actualBuffer)
    ) {
      throw new HttpException('Invalid signature', HttpStatus.UNAUTHORIZED);
    }

    // Log Delivery
    await this.prisma.runAsSystem(
      '[WebhookController.receiveWebhook] Webhook handler bypass',
      async (tx) =>
        tx.webhookDelivery.create({
          data: {
            companyId: connection.companyId,
            direction: 'INCOMING',
            endpointUrl: req.url,
            eventTopic: (payload as any).event_type || 'unknown_event',
            payload: payload as any,
          },
        }),
    );

    // We would then push this to the EventBus/BullMQ for asynchronous processing.
    // e.g. this.eventBus.publish('integration.webhook.received', { connectionId, payload })

    return { status: 'Received', timestamp: new Date() };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../../platform/events/event.service';

@Injectable()
export class AlertEngineService {
  private readonly logger = new Logger(AlertEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  @OnEvent('GpsPing.Received')
  async evaluateGpsPing(event: any) {
    const { tenantId, payload, timestamp } = event;
    const { vehicleId, speed, fuelLevel } = payload;

    const rules = await this.prisma.runAsTenant(tenantId, async (tx) =>
      tx.alertRule.findMany({
        where: { companyId: tenantId, isActive: true },
      }),
    );

    for (const rule of rules) {
      if (rule.type === 'SPEEDING' && speed !== undefined) {
        if (rule.condition === 'EXCEEDS' && speed > rule.threshold) {
          await this.triggerAlert(tenantId, rule, vehicleId, timestamp, {
            speed,
          });
        }
      } else if (rule.type === 'LOW_FUEL' && fuelLevel !== undefined) {
        if (rule.condition === 'LESS_THAN' && fuelLevel < rule.threshold) {
          await this.triggerAlert(tenantId, rule, vehicleId, timestamp, {
            fuelLevel,
          });
        }
      }
    }
  }

  private async triggerAlert(
    companyId: string,
    rule: any,
    vehicleId: string,
    timestamp: string,
    metadata: any,
  ) {
    // Deduplication: Don't trigger if there's already an active (NEW/ACKNOWLEDGED) alert for this rule & vehicle
    const activeAlert = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.findFirst({
        where: {
          companyId,
          ruleId: rule.id,
          vehicleId,
          status: { in: ['NEW', 'ACKNOWLEDGED'] },
        },
      }),
    );

    if (activeAlert) return; // Prevent alert spam

    const alert = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.alert.create({
        data: {
          companyId,
          ruleId: rule.id,
          vehicleId,
          severity: rule.severity,
          message: `Alert: ${rule.name} triggered.`,
          timestamp: new Date(timestamp),
          metadata,
        },
      }),
    );

    this.logger.warn(
      `Alert Generated [${rule.severity}]: ${rule.name} for Vehicle ${vehicleId}`,
    );

    this.eventService.publish('Alert.Triggered', {
      tenantId: companyId,
      userId: 'SYSTEM',
      correlationId: `alert-${alert.id}`,
      payload: { alertId: alert.id, ruleType: rule.type },
      timestamp: new Date(timestamp),
    });
  }
}

