    );

    // Assume driver has a 'safetyScore' field added later, or an Analytics projection calculates this on the fly.
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { CommandCenterGateway } from './command-center.gateway';
import { JwtService } from '@nestjs/jwt';

describe('CommandCenterGateway', () => {
  let gateway: CommandCenterGateway;
  let jwtService: JwtService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        CommandCenterGateway,
        {
          provide: JwtService,
          useValue: {
            verify: jest.fn(),
          },
        },
      ],
    }).compile();

    gateway = module.get<CommandCenterGateway>(CommandCenterGateway);
    jwtService = module.get<JwtService>(JwtService);
  });

  it('should be defined', () => {
    expect(gateway).toBeDefined();
  });

  describe('handleConnection', () => {
    let mockClient: any;

    beforeEach(() => {
      mockClient = {
        id: 'socket-id-123',
        handshake: {
          headers: {},
          auth: {},
        },
        join: jest.fn(),
        disconnect: jest.fn(),
      };
    });

    it('should drop connection if no token provided', async () => {
      await gateway.handleConnection(mockClient);
      expect(mockClient.disconnect).toHaveBeenCalledWith(true);
      expect(mockClient.join).not.toHaveBeenCalled();
    });

    it('should drop connection if token is invalid', async () => {
      mockClient.handshake.auth.token = 'invalid.jwt.token';
      jest.spyOn(jwtService, 'verify').mockImplementation(() => {
        throw new Error('jwt malformed');
      });

      await gateway.handleConnection(mockClient);

      expect(jwtService.verify).toHaveBeenCalledWith('invalid.jwt.token');
      expect(mockClient.disconnect).toHaveBeenCalledWith(true);
      expect(mockClient.join).not.toHaveBeenCalled();
    });

    it('should drop connection if token has no companyId', async () => {
      mockClient.handshake.auth.token = 'valid.jwt.no-company';
      jest.spyOn(jwtService, 'verify').mockReturnValue({ userId: 'user-1' });

      await gateway.handleConnection(mockClient);

      expect(jwtService.verify).toHaveBeenCalledWith('valid.jwt.no-company');
      expect(mockClient.disconnect).toHaveBeenCalledWith(true);
      expect(mockClient.join).not.toHaveBeenCalled();
    });

    it('should join strictly isolated tenant room if token is valid', async () => {
      const companyId = 'test-tenant-xyz';
      mockClient.handshake.auth.token = 'valid.jwt.token';
      jest
        .spyOn(jwtService, 'verify')
        .mockReturnValue({ companyId, userId: 'user-1' });

      await gateway.handleConnection(mockClient);

      expect(jwtService.verify).toHaveBeenCalledWith('valid.jwt.token');
      expect(mockClient.disconnect).not.toHaveBeenCalled();
      expect(mockClient.join).toHaveBeenCalledWith(`tenant_${companyId}`);
      expect(mockClient.companyId).toBe(companyId);
    });
  });
});

import {
  WebSocketGateway,
  OnGatewayConnection,
  OnGatewayDisconnect,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { JwtService } from '@nestjs/jwt';
import { Logger } from '@nestjs/common';

@WebSocketGateway({ cors: true })
export class CommandCenterGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(CommandCenterGateway.name);

  constructor(private readonly jwtService: JwtService) {}

  async handleConnection(client: Socket) {
    this.logger.log(`Client attempting connection: ${client.id}`);

    try {
      const authHeader = client.handshake.headers.authorization;
      const token = authHeader?.split(' ')[1] || client.handshake.auth?.token;

      if (!token) {
        throw new Error('No token provided');
      }

      const decoded = this.jwtService.verify(token);
      const companyId = decoded.companyId;

      if (!companyId) {
        throw new Error('No companyId in token payload');
      }

      const roomName = `tenant_${companyId}`;
      client.join(roomName);

      // Store on client for convenience
      (client as any).companyId = companyId;

      this.logger.log(`Client ${client.id} joined room: ${roomName}`);
    } catch (error) {
      this.logger.warn(
        `Invalid connection attempt from ${client.id}: ${error.message}`,
      );
      client.disconnect(true);
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client disconnected: ${client.id}`);
  }

  broadcastToTenant(companyId: string, event: string, payload: any) {
    const roomName = `tenant_${companyId}`;
    this.server.to(roomName).emit(event, payload);
    this.logger.debug(`Broadcasted ${event} to ${roomName}`);
  }
}

