import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

// ---------------------------------------------------------------------------
// Cause definitions
// ---------------------------------------------------------------------------
export type RootCause =
  | 'DRIVER'
  | 'MECHANICAL'
  | 'ROUTE'
  | 'INVESTIGATE'
  | 'INSUFFICIENT_DATA'
  | 'NORMAL';

export interface RootCauseEntry {
  fuelEntryId: string;
  tripId: string;
  driverId: string;
  driverName: string;
  vehicleId: string;
  licensePlate: string;
  routeKey: string | null;
  litres: number;
  expectedLitres: number | null;
  variancePct: number | null;
  rootCause: RootCause;
  confidence: 'HIGH' | 'LOW';
  comparisonGroupSize: number;
  explanation: string;
}

@Injectable()
export class FuelIntelligenceService {
  constructor(private readonly prisma: PrismaService) {}

  // ---------------------------------------------------------------------------
  // Existing anomaly feed (unchanged)
  // ---------------------------------------------------------------------------
  async getAnomalies(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      const recentDate = new Date();
      recentDate.setDate(recentDate.getDate() - 30);

      const entries = await tx.fuelEntry.findMany({
        where: { companyId, filledAt: { gte: recentDate } },
        include: {
          vehicle: { select: { id: true, licensePlate: true, type: true } },
          driver: { select: { id: true, firstName: true, lastName: true } },
          trip: { select: { id: true, tripNumber: true } },
        },
      });

      const anomalies: any[] = [];

      entries.forEach((entry: any) => {
        if (entry.variancePct > 25) {
          anomalies.push({
            entityType: 'TRIP',
            entityId: entry.tripId,
            entityName: `Trip ${entry.trip?.tripNumber || 'Unknown'}`,
            variancePct: Number(entry.variancePct.toFixed(1)),
            cause: 'INVESTIGATE',
            description: `Trip ${entry.trip?.tripNumber} used ${entry.variancePct.toFixed(1)}% over expected fuel.`,
            severity: 'HIGH',
          });
        }
      });

      const truckMap = new Map<
        string,
        { name: string; variances: number[]; drivers: Set<string> }
      >();
      const driverMap = new Map<
        string,
        { name: string; variances: number[]; trucks: Set<string> }
      >();

      entries.forEach((entry: any) => {
        if (!entry.vehicleId || !entry.driverId) return;

        if (!truckMap.has(entry.vehicleId)) {
          truckMap.set(entry.vehicleId, {
            name: entry.vehicle?.licensePlate || entry.vehicleId,
            variances: [],
            drivers: new Set(),
          });
        }
        truckMap.get(entry.vehicleId)!.variances.push(entry.variancePct);
        truckMap.get(entry.vehicleId)!.drivers.add(entry.driverId);

        if (!driverMap.has(entry.driverId)) {
          driverMap.set(entry.driverId, {
            name:
              `${entry.driver?.firstName || ''} ${entry.driver?.lastName || ''}`.trim() ||
              entry.driverId,
            variances: [],
            trucks: new Set(),
          });
        }
        driverMap.get(entry.driverId)!.variances.push(entry.variancePct);
        driverMap.get(entry.driverId)!.trucks.add(entry.vehicleId);
      });

      truckMap.forEach((data, vehicleId) => {
        const avgVariance =
          data.variances.reduce((a: number, b: number) => a + b, 0) /
          data.variances.length;
        if (avgVariance > 15 && data.drivers.size > 0) {
          anomalies.push({
            entityType: 'TRUCK',
            entityId: vehicleId,
            entityName: data.name,
            variancePct: Number(avgVariance.toFixed(1)),
            cause: 'MECHANICAL',
            description: `Truck ${data.name} used ${avgVariance.toFixed(1)}% over expected across ${data.variances.length} trips (different drivers). Likely mechanical.`,
            severity: avgVariance > 25 ? 'HIGH' : 'MEDIUM',
          });
        }
      });

      driverMap.forEach((data, driverId) => {
        const avgVariance =
          data.variances.reduce((a: number, b: number) => a + b, 0) /
          data.variances.length;
        if (avgVariance > 15 && data.trucks.size > 0) {
          anomalies.push({
            entityType: 'DRIVER',
            entityId: driverId,
            entityName: data.name,
            variancePct: Number(avgVariance.toFixed(1)),
            cause: 'DRIVER PILFERAGE',
            description: `Driver ${data.name} used ${avgVariance.toFixed(1)}% over expected across ${data.variances.length} trips. Potential pilferage.`,
            severity: avgVariance > 25 ? 'HIGH' : 'MEDIUM',
          });
        }
      });

      anomalies.sort((a: any, b: any) => b.variancePct - a.variancePct);
      return anomalies;
    });
  }

  async getSummary(companyId: string) {
    const anomalies = await this.getAnomalies(companyId);
    return {
      worstTrucks: anomalies
        .filter((a: any) => a.entityType === 'TRUCK')
        .slice(0, 5),
      worstDrivers: anomalies
        .filter((a: any) => a.entityType === 'DRIVER')
        .slice(0, 5),
      criticalTrips: anomalies
        .filter((a: any) => a.entityType === 'TRIP')
        .slice(0, 5),
      totalAnomalies: anomalies.length,
    };
  }

  // ---------------------------------------------------------------------------
  // NEW: Root-cause attribution engine
  //
  // Isolation logic:
  //   DRIVER    → same (vehicleId + routeKey), different driverIds, ≥2 entries
  //               Entry with highest variance in that group = DRIVER behaviour
  //   MECHANICAL→ same (driverId + routeKey), different vehicleIds, ≥2 entries
  //               Vehicle with consistently higher variance = MECHANICAL issue
  //   ROUTE     → same (driverId + vehicleId), different routeKeys, ≥2 entries
  //               Route with higher variance = ROUTE difficulty
  //   INVESTIGATE→ variance >15% but only 1 entry in every comparison group
  //   INSUFFICIENT_DATA → <15% variance AND no comparison group to confirm
  // ---------------------------------------------------------------------------
  async getRootCause(companyId: string): Promise<RootCauseEntry[]> {
    return this.prisma.runAsTenant(companyId, async (tx: any) => {
      const entries = await tx.fuelEntry.findMany({
        where: { companyId },
        include: {
          vehicle: { select: { id: true, licensePlate: true } },
          driver: { select: { id: true, firstName: true, lastName: true } },
        },
        orderBy: { filledAt: 'desc' },
      });

      if (entries.length === 0) return [];

      // Build lookup indexes for fast group access
      // key = vehicleId:routeKey  -> [entries]
      const byVehicleRoute = new Map<string, any[]>();
      // key = driverId:routeKey   -> [entries]
      const byDriverRoute = new Map<string, any[]>();
      // key = driverId:vehicleId  -> [entries]
      const byDriverVehicle = new Map<string, any[]>();

      for (const e of entries) {
        const routeKey =
          e.originCity && e.destinationCity
            ? `${e.originCity}:${e.destinationCity}`
            : null;

        const vk = `${e.vehicleId}:${routeKey ?? 'UNKNOWN_ROUTE'}`;
        const dk = `${e.driverId}:${routeKey ?? 'UNKNOWN_ROUTE'}`;
        const dvk = `${e.driverId}:${e.vehicleId}`;

        if (!byVehicleRoute.has(vk)) byVehicleRoute.set(vk, []);
        byVehicleRoute.get(vk)!.push(e);

        if (!byDriverRoute.has(dk)) byDriverRoute.set(dk, []);
        byDriverRoute.get(dk)!.push(e);

        if (!byDriverVehicle.has(dvk)) byDriverVehicle.set(dvk, []);
        byDriverVehicle.get(dvk)!.push(e);
      }

      const results: RootCauseEntry[] = entries.map((e: any) => {
        const routeKey =
          e.originCity && e.destinationCity
            ? `${e.originCity}:${e.destinationCity}`
            : null;

        const driverName =
          `${e.driver?.firstName ?? ''} ${e.driver?.lastName ?? ''}`.trim() ||
          e.driverId;
        const licensePlate = e.vehicle?.licensePlate || e.vehicleId;
        const variancePct = e.variancePct ?? null;

        // Check isolation groups
        const vk = `${e.vehicleId}:${routeKey ?? 'UNKNOWN_ROUTE'}`;
        const dk = `${e.driverId}:${routeKey ?? 'UNKNOWN_ROUTE'}`;
        const dvk = `${e.driverId}:${e.vehicleId}`;

        const vehicleRouteGroup = byVehicleRoute.get(vk)!;
        const driverRouteGroup = byDriverRoute.get(dk)!;
        const driverVehicleGroup = byDriverVehicle.get(dvk)!;

        const uniqueDriversOnVehicleRoute = new Set(
          vehicleRouteGroup.map((x: any) => x.driverId),
        );
        const uniqueVehiclesOnDriverRoute = new Set(
          driverRouteGroup.map((x: any) => x.vehicleId),
        );
        const uniqueRoutesForDriverVehicle = new Set(
          driverVehicleGroup
            .filter((x: any) => x.originCity && x.destinationCity)
            .map((x: any) => `${x.originCity}:${x.destinationCity}`),
        );

        // ── DRIVER isolation: same vehicle+route, multiple drivers
        if (uniqueDriversOnVehicleRoute.size >= 2 && routeKey) {
          const groupVariances = vehicleRouteGroup.map(
            (x: any) => x.variancePct ?? 0,
          );
          const avgGroupVariance =
            groupVariances.reduce((a: number, b: number) => a + b, 0) /
            groupVariances.length;
          const eVariance = variancePct ?? 0;
          const isHighDriver = eVariance > avgGroupVariance + 5;

          return {
            fuelEntryId: e.id,
            tripId: e.tripId,
            driverId: e.driverId,
            driverName,
            vehicleId: e.vehicleId,
            licensePlate,
            routeKey,
            litres: e.litres,
            expectedLitres: e.expectedLitres,
            variancePct,
            rootCause: isHighDriver ? 'DRIVER' : 'NORMAL',
            confidence: 'HIGH',
            comparisonGroupSize: vehicleRouteGroup.length,
            explanation: isHighDriver
              ? `Driver ${driverName} used ${eVariance.toFixed(1)}% variance vs group avg ${avgGroupVariance.toFixed(1)}% on route ${routeKey} with vehicle ${licensePlate}. Same vehicle, same route, different driver — behaviour isolated.`
              : `On route ${routeKey} with ${licensePlate}, ${uniqueDriversOnVehicleRoute.size} drivers. ${driverName}'s variance (${eVariance.toFixed(1)}%) is within normal group range (avg ${avgGroupVariance.toFixed(1)}%).`,
          } as RootCauseEntry;
        }

        // ── MECHANICAL isolation: same driver+route, multiple vehicles
        if (uniqueVehiclesOnDriverRoute.size >= 2 && routeKey) {
          const groupVariances = driverRouteGroup.map(
            (x: any) => x.variancePct ?? 0,
          );
          const avgGroupVariance =
            groupVariances.reduce((a: number, b: number) => a + b, 0) /
            groupVariances.length;
          const eVariance = variancePct ?? 0;
          const isHighMechanical = eVariance > avgGroupVariance + 5;

          return {
            fuelEntryId: e.id,
            tripId: e.tripId,
            driverId: e.driverId,
            driverName,
            vehicleId: e.vehicleId,
            licensePlate,
            routeKey,
            litres: e.litres,
            expectedLitres: e.expectedLitres,
            variancePct,
            rootCause: isHighMechanical ? 'MECHANICAL' : 'NORMAL',
            confidence: 'HIGH',
            comparisonGroupSize: driverRouteGroup.length,
            explanation: isHighMechanical
              ? `Vehicle ${licensePlate} used ${eVariance.toFixed(1)}% variance vs group avg ${avgGroupVariance.toFixed(1)}%. Same driver, same route, different vehicle — mechanical issue isolated.`
              : `Driver ${driverName} on route ${routeKey} drove ${uniqueVehiclesOnDriverRoute.size} vehicles. ${licensePlate}'s variance (${eVariance.toFixed(1)}%) within normal range.`,
          } as RootCauseEntry;
        }

        // ── ROUTE isolation: same driver+vehicle, multiple routes
        if (uniqueRoutesForDriverVehicle.size >= 2 && routeKey) {
          const groupVariances = driverVehicleGroup.map(
            (x: any) => x.variancePct ?? 0,
          );
          const avgGroupVariance =
            groupVariances.reduce((a: number, b: number) => a + b, 0) /
            groupVariances.length;
          const eVariance = variancePct ?? 0;
          const isHighRoute = eVariance > avgGroupVariance + 5;

          return {
            fuelEntryId: e.id,
            tripId: e.tripId,
            driverId: e.driverId,
            driverName,
            vehicleId: e.vehicleId,
            licensePlate,
            routeKey,
            litres: e.litres,
            expectedLitres: e.expectedLitres,
            variancePct,
            rootCause: isHighRoute ? 'ROUTE' : 'NORMAL',
            confidence: 'HIGH',
            comparisonGroupSize: driverVehicleGroup.length,
            explanation: isHighRoute
              ? `Route ${routeKey} shows ${eVariance.toFixed(1)}% variance vs this driver+vehicle avg of ${avgGroupVariance.toFixed(1)}%. Same driver, same vehicle, different route — route difficulty isolated.`
              : `Driver ${driverName} + ${licensePlate} across ${uniqueRoutesForDriverVehicle.size} routes. Route ${routeKey} variance (${eVariance.toFixed(1)}%) within normal range.`,
          } as RootCauseEntry;
        }

        // ── INSUFFICIENT_DATA: only 1 entry in every comparison group
        const hasHighVariance = (variancePct ?? 0) > 15;
        return {
          fuelEntryId: e.id,
          tripId: e.tripId,
          driverId: e.driverId,
          driverName,
          vehicleId: e.vehicleId,
          licensePlate,
          routeKey,
          litres: e.litres,
          expectedLitres: e.expectedLitres,
          variancePct,
          rootCause: hasHighVariance ? 'INVESTIGATE' : 'INSUFFICIENT_DATA',
          confidence: 'LOW',
          comparisonGroupSize: 1,
          explanation: hasHighVariance
            ? `Variance of ${(variancePct ?? 0).toFixed(1)}% is above 15% threshold but no comparison group exists to isolate cause. More trips on this vehicle/driver/route combination needed.`
            : `Only 1 data point for this vehicle+route+driver combination. Cannot isolate cause without a comparison group.`,
        } as RootCauseEntry;
      });

      // Sort: highest variance first, then by cause specificity
      const causePriority: Record<RootCause, number> = {
        DRIVER: 0,
        MECHANICAL: 1,
        ROUTE: 2,
        INVESTIGATE: 3,
        INSUFFICIENT_DATA: 4,
        NORMAL: 5,
      };
      results.sort((a, b) => {
        if (a.rootCause !== b.rootCause) {
          return causePriority[a.rootCause] - causePriority[b.rootCause];
        }
        return (b.variancePct ?? 0) - (a.variancePct ?? 0);
      });

      return results;
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../../platform/events/event.service';

@Injectable()
export class GeofenceService {
  private readonly logger = new Logger(GeofenceService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
  ) {}

  // Haversine distance formula
  private getDistance(
    lat1: number,
    lon1: number,
    lat2: number,
    lon2: number,
  ): number {
    const R = 6371e3; // metres
    const φ1 = (lat1 * Math.PI) / 180; // φ, λ in radians
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c; // in metres
  }

  @OnEvent('GpsPing.Received')
  async handleGpsPing(event: any) {
    const { tenantId, payload, timestamp } = event;
    const { vehicleId, latitude, longitude } = payload;

    // 1. Fetch active geofences for this company
    // Optimisation: In a real system, you'd use PostGIS or Redis geospatial indexing (GEORADIUS)
    // rather than loading all geofences, but for the MVP we will filter in memory.
    const geofences = await this.prisma.runAsTenant(tenantId, async (tx) =>
      tx.geofence.findMany({
        where: { companyId: tenantId, isActive: true },
      }),
    );

    for (const geofence of geofences) {
      // 2. Calculate distance
      const distance = this.getDistance(
        latitude,
        longitude,
        geofence.latitude,
        geofence.longitude,
      );
      const isInsideNow = distance <= geofence.radiusMeters;

      // 3. Check previous state (did we already enter/exit?)
      const lastEvent = await this.prisma.runAsTenant(tenantId, async (tx) =>
        tx.geofenceEvent.findFirst({
          where: { vehicleId, geofenceId: geofence.id },
          orderBy: { timestamp: 'desc' },
        }),
      );

      const wasInsideBefore = lastEvent?.eventType === 'ENTER';

      if (isInsideNow && !wasInsideBefore) {
        // Trigger ENTER event
        await this.prisma.runAsTenant(tenantId, async (tx) =>
          tx.geofenceEvent.create({
            data: {
              companyId: tenantId,
              geofenceId: geofence.id,
              vehicleId,
              eventType: 'ENTER',
              timestamp: new Date(timestamp),
            },
          }),
        );

        this.eventService.publish('Geofence.Entered', {
          tenantId,
          userId: 'SYSTEM',
          correlationId: event.correlationId,
          payload: {
            vehicleId,
            geofenceId: geofence.id,
            geofenceName: geofence.name,
          },
          timestamp: new Date(timestamp),
        });

        this.logger.debug(
          `Vehicle ${vehicleId} ENTERED geofence ${geofence.name}`,
        );
      } else if (!isInsideNow && wasInsideBefore) {
        // Trigger EXIT event
        const dwellTimeMs =
          new Date(timestamp).getTime() -
          new Date(lastEvent.timestamp).getTime();

        await this.prisma.runAsTenant(tenantId, async (tx) =>
          tx.geofenceEvent.create({
            data: {
              companyId: tenantId,
              geofenceId: geofence.id,
              vehicleId,
              eventType: 'EXIT',
              timestamp: new Date(timestamp),
              metadata: { dwellTimeMs },
            },
          }),
        );

        this.eventService.publish('Geofence.Exited', {
          tenantId,
          userId: 'SYSTEM',
          correlationId: event.correlationId,
          payload: {
            vehicleId,
            geofenceId: geofence.id,
            geofenceName: geofence.name,
            dwellTimeMs,
          },
          timestamp: new Date(timestamp),
        });

        this.logger.debug(
          `Vehicle ${vehicleId} EXITED geofence ${geofence.name} (Dwell: ${Math.round(dwellTimeMs / 60000)}m)`,
        );
      }
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class TimelineService {
  private readonly logger = new Logger(TimelineService.name);

  constructor(private readonly prisma: PrismaService) {}

  async addEvent(
    tripId: string,
    companyId: string,
    eventName: string,
    metadata: any = {},
  ) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId },
      }),
    );

    if (!trip || trip.companyId !== companyId) return;

    let timeline: any[] = [];
    if (trip.timeline && Array.isArray(trip.timeline)) {
      timeline = trip.timeline as any[];
    }

    timeline.push({
      event: eventName,
      timestamp: new Date().toISOString(),
      metadata,
    });

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.update({
        where: { id: tripId },
        data: { timeline },
      }),
    );

    this.logger.debug(`Timeline event ${eventName} added to trip ${tripId}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../../platform/events/event.service';
import { MetricsEngineService } from '../../analytics/engine/metrics-engine.service';

@Injectable()
export class BusinessHealthService {
  private readonly logger = new Logger(BusinessHealthService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventService: EventService,
    private readonly metrics: MetricsEngineService,
  ) {}

  /**
   * Orchestrates the calculation of the Business Health Vitals
   */
  async calculateHealthVitals(companyId: string) {
    this.logger.log(
      `Calculating Business Health Vitals for company ${companyId}`,
    );

    // 1. Calculate Operational Health
    const operationalData = await this.calculateOperationalHealth(companyId);

    // 2. Calculate Financial Health
    const financialData = await this.calculateFinancialHealth(companyId);

    const snapshot = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.businessHealthSnapshot.create({
        data: {
          companyId,
          operationalScore: operationalData.score,
          financialScore: financialData.score,
          contributingFactors: {
            operational: operationalData.factors,
            financial: financialData.factors,
          },
        },
      }),
    );

    // 3. Fetch LIN Industry Benchmarks
    const benchmarks = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.linBenchmark.findMany(),
    );
    const benchmarkMap = benchmarks.reduce(
      (acc, b) => ({ ...acc, [b.metricName]: b.value }),
      {},
    );

    // 4. Emit Event for Realtime SSE Update
    this.eventService.publish('BusinessHealth.Updated', {
      tenantId: companyId,
      payload: {
        operationalScore: snapshot.operationalScore,
        financialScore: snapshot.financialScore,
        timestamp: snapshot.timestamp,
        factors: snapshot.contributingFactors,
        industryBenchmarks: benchmarkMap,
      },
    });

    return snapshot;
  }

  /**
   * Calculates Operational Health Score (0-100)
   */
  private async calculateOperationalHealth(companyId: string) {
    const now = new Date();
    const startOfDay = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
    );

    // Factor 1: Fleet Utilization
    const fleetUtil = await this.metrics.getFleetUtilization(companyId);
    const utilizationScore = fleetUtil.percentage; // 0-100

    // Factor 2: Active AI Anomalies Penalty
    const activeAnomalies = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.operationalAnomaly.count({
          where: { companyId, status: 'OPEN' },
        }),
    );
    // Deduct 5 points per active anomaly, max deduction 30
    const anomalyPenalty = Math.min(activeAnomalies * 5, 30);

    // Factor 3: Morning Plan Exception Penalty
    const planExceptions = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.operationalPlanItem.count({
          where: {
            plan: { companyId, date: startOfDay },
            status: { in: ['NEEDS_APPROVAL', 'REQUIRES_HUMAN'] },
          },
        }),
    );
    // Deduct 2 points per unresolved exception, max deduction 20
    const exceptionPenalty = Math.min(planExceptions * 2, 20);

    // Factor 4: On-time Delivery Rate (Trips completed today vs delayed)
    const tripsToday = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findMany({
        where: { companyId, createdAt: { gte: startOfDay } },
      }),
    );
    const completedOrTransit = tripsToday.filter(
      (t) => t.status === 'COMPLETED' || t.status === 'IN_TRANSIT',
    ).length;
    // @ts-ignore: reserved for future use
    const _delayed = tripsToday.filter((t) => t.status === 'DELAYED').length;

    let onTimeScore = 100;
    if (tripsToday.length > 0) {
      onTimeScore = (completedOrTransit / tripsToday.length) * 100;
    }

    // Weighting Algorithm
    // Base is driven by On-time and Utilization, dragged down by unresolved exceptions
    const baseScore = utilizationScore * 0.4 + onTimeScore * 0.6;
    let finalScore = baseScore - anomalyPenalty - exceptionPenalty;

    // Clamp to 0-100
    finalScore = Math.max(0, Math.min(100, finalScore));

    return {
      score: finalScore,
      factors: {
        utilizationScore,
        onTimeScore,
        activeAnomalies,
        planExceptions,
      },
    };
  }

  /**
   * Calculates Financial Health Score (0-100)
   */
  private async calculateFinancialHealth(companyId: string) {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    // Factor 1: Revenue Momentum (MTD)
    const revenueKpi = await this.metrics.getRevenueKPI(
      companyId,
      thirtyDaysAgo,
      now,
    );
    // Arbitrary target for health demo: $100k trailing 30 days is "100 score"
    const revenueTarget = 100000;
    const revenueScore = Math.min(
      (revenueKpi.value / revenueTarget) * 100,
      100,
    );

    // Factor 2: AR Aging (Unpaid Invoices)
    const unpaidInvoices = await this.prisma.runAsTenant(
      companyId,
      async (tx) =>
        tx.invoice.findMany({
          where: { companyId, status: 'ISSUED', dueDate: { lt: now } },
        }),
    );
    const totalArAging = unpaidInvoices.reduce(
      (sum, inv) => sum + (inv.amount || 0),
      0,
    );
    // Deduct points based on severity of overdue AR
    let arPenalty = 0;
    if (totalArAging > 50000) arPenalty = 30;
    else if (totalArAging > 10000) arPenalty = 15;

    // Weighting Algorithm
    let finalScore = revenueScore - arPenalty;
    // Default to a realistic baseline if brand new company
    if (revenueKpi.value === 0 && totalArAging === 0) {
      finalScore = 85;
    }

    // Clamp to 0-100
    finalScore = Math.max(0, Math.min(100, finalScore));

    return {
      score: finalScore,
      factors: {
        revenueValue: revenueKpi.value,
        revenueScore,
        totalArAging,
        arPenalty,
      },
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import type { PlatformEvent } from '../../platform/events/event.service';

@Injectable()
export class LinAnonymizationService {
  private readonly logger = new Logger(LinAnonymizationService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Listen to critical operational events and siphon them into the anonymized
   * Intelligence Network archive. In a true distributed system, this would listen
   * to a Kafka topic. Here we listen to the local event bus.
   */
  @OnEvent('trip.completed')
  async handleTripCompleted(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing trip.completed event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    // Strict Anonymization Map
    // Drops: tripNumber, driverId, vehicleId, precise locations
    // Keeps: duration, status, delays, fuel metrics (if any)
    const anonymizedPayload = {
      durationSeconds: payload.actualDurationSeconds || null,
      distanceMeters: payload.actualDistanceMeters || null,
      delayed: payload.status === 'DELAYED',
      region: this.generalizeLocation(payload.startLocation), // e.g. "US-West" instead of GPS
    };

    await this.archiveEvent('trip.completed', anonymizedPayload);
  }

  @OnEvent('BusinessHealth.Updated')
  async handleBusinessHealth(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing BusinessHealth.Updated event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    const anonymizedPayload = {
      operationalScore: payload.operationalScore,
      financialScore: payload.financialScore,
      timestamp: payload.timestamp,
    };

    await this.archiveEvent('business_health.updated', anonymizedPayload);
  }

  @OnEvent('anomaly.resolved')
  async handleAnomalyResolved(event: PlatformEvent) {
    this.logger.debug(`[LIN] Anonymizing anomaly.resolved event...`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.payload as Record<string, any>;

    const anonymizedPayload = {
      anomalyType: payload.type,
      resolutionTimeSeconds: payload.resolutionTimeSeconds,
      aiRecommendationUsed: payload.aiRecommendationUsed || false,
    };

    await this.archiveEvent('anomaly.resolved', anonymizedPayload);
  }

  private async archiveEvent(eventType: string, anonymizedPayload: any) {
    try {
      await this.prisma.runAsSystem(
        '[LinAnonymizationService.archiveEvent] Internal service operation bypass',
        async (tx) =>
          tx.linEventArchive.create({
            data: {
              eventType,
              anonymizedPayload,
            },
          }),
      );
      this.logger.debug(
        `[LIN] Successfully archived anonymized event: ${eventType}`,
      );
    } catch (error) {
      this.logger.error(
        `[LIN] Failed to archive event: ${(error as Error).message}`,
      );
    }
  }

  private generalizeLocation(_location: any): string {
    // Stub implementation to generalize GPS into large geographic buckets
    return 'US-West';
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class LinBenchmarkEngine {
  private readonly logger = new Logger(LinBenchmarkEngine.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Periodically computes network-wide benchmarks from the anonymized event archive.
   * In a real system, this would be an offline batch job (e.g. Apache Spark) syncing
   * results back to the transactional database.
   */
  @Cron(CronExpression.EVERY_HOUR)
  async computeNetworkBenchmarks() {
    this.logger.log(`[LIN] Starting Network Benchmark computation...`);

    // 1. Compute AI Approval Rate Benchmark
    await this.computeAiApprovalRate();

    // 2. Compute Average Operational Health
    await this.computeAverageHealthScore();

    this.logger.log(`[LIN] Network Benchmark computation completed.`);
  }

  private async computeAiApprovalRate() {
    const events = await this.prisma.runAsSystem(
      '[LinBenchmarkEngine.computeAiApprovalRate] Internal service operation bypass',
      async (tx) =>
        tx.linEventArchive.findMany({
          where: { eventType: 'anomaly.resolved' },
        }),
    );

    if (events.length === 0) return;

    const approvedCount = events.filter(
      (e: any) => e.anonymizedPayload.aiRecommendationUsed,
    ).length;
    const approvalRate = (approvedCount / events.length) * 100;

    await this.upsertBenchmark(
      'ai_approval_rate_avg',
      approvalRate,
      0.9,
      events.length,
    );
  }

  private async computeAverageHealthScore() {
    const events = await this.prisma.runAsSystem(
      '[LinBenchmarkEngine.computeAverageHealthScore] Internal service operation bypass',
      async (tx) =>
        tx.linEventArchive.findMany({
          where: { eventType: 'business_health.updated' },
          orderBy: { timestamp: 'desc' },
          take: 1000, // Sample size of recent pulses across the network
        }),
    );

    if (events.length === 0) return;

    const sum = events.reduce(
      (acc, e: any) => acc + (e.anonymizedPayload.operationalScore || 0),
      0,
    );
    const avgScore = sum / events.length;

    await this.upsertBenchmark(
      'operational_health_avg',
      avgScore,
      0.85,
      events.length,
    );
  }

  private async upsertBenchmark(
    metricName: string,
    value: number,
    confidenceScore: number,
    sampleSize: number,
  ) {
    await this.prisma.runAsSystem(
      '[LinBenchmarkEngine.upsertBenchmark] Internal service operation bypass',
      async (tx) =>
        tx.linBenchmark.upsert({
          where: { metricName },
          update: {
            value,
            confidenceScore,
            sampleSize,
          },
          create: {
            metricName,
            value,
            confidenceScore,
            sampleSize,
          },
        }),
    );
    this.logger.debug(
      `[LIN] Updated benchmark ${metricName} = ${value.toFixed(2)}`,
    );
  }
}

import { Injectable, Logger } from '@nestjs/common';
