@Injectable()
export class InvoicesService {
  constructor(
    private prisma: PrismaService,
    private readonly auditService: AuditService,
    private readonly eventStore: EventStoreService,
  ) {}

  async getInvoices(
    companyId: string,
    page = 1,
    limit = 50,
    sort = 'createdAt',
    order: 'asc' | 'desc' = 'desc',
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const skip = (page - 1) * limit;
      const where = { companyId };

      const [data, total] = await Promise.all([
        tx.invoice.findMany({
          where,
          orderBy: { [sort]: order },
          skip,
          take: limit,
          include: {
            customer: { select: { id: true, name: true } },
            load: { select: { id: true, referenceNumber: true } },
          },
        }),
        tx.invoice.count({ where }),
      ]);

      const mappedData = data.map((inv: any) => ({
        ...inv,
        customerName: inv.customer?.name,
      }));

      return {
        data: mappedData,
        total,
        meta: {
          total,
          page,
          limit,
          lastPage: Math.ceil(total / limit) || 1,
        },
      };
    });
  }

  async getInvoiceById(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const invoice = await tx.invoice.findFirst({
        where: { id, companyId },
        include: {
          customer: true,
          load: true,
          lineItems: true,
          payments: { orderBy: { paymentDate: 'desc' } },
        },
      });
      if (!invoice) throw new NotFoundException('Invoice not found');

      const totalPaid =
        invoice.payments?.reduce((sum, p) => sum + p.amount, 0) ||
        (invoice.status === 'PAID' ? invoice.amount : 0);
      const subtotal =
        invoice.lineItems
          ?.filter((i) => i.type !== 'TAX')
          .reduce((sum, i) => sum + i.amount, 0) ||
        Math.round(invoice.amount / 1.05);
      const taxTotal =
        invoice.lineItems
          ?.filter((i) => i.type === 'TAX')
          .reduce((sum, i) => sum + i.amount, 0) || invoice.amount - subtotal;
      const balanceDue =
        invoice.status === 'PAID' ? 0 : Math.max(0, invoice.amount - totalPaid);

      return {
        ...invoice,
        customerName: invoice.customer?.name,
        subtotal,
        taxTotal,
        grandTotal: invoice.amount,
        amountPaid: totalPaid,
        balanceDue,
      };
    });
  }

  async recordPayment(
    companyId: string,
    invoiceId: string,
    payload: {
      amount: number;
      method?: string;
      referenceNumber?: string;
      paymentDate?: string;
      notes?: string;
    },
    _userId?: string,
  ) {
    const {
      amount,
      method = 'NEFT',
      referenceNumber,
      paymentDate = new Date().toISOString(),
      notes,
    } = payload;
    if (typeof amount !== 'number' || isNaN(amount) || amount <= 0) {
      throw new BadRequestException('Payment amount must be a positive number');
    }

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const invoice = await tx.invoice.findFirst({
        where: { id: invoiceId, companyId },
        include: { payments: true },
      });
      if (!invoice) throw new NotFoundException('Invoice not found');

      const existingPaid = invoice.payments.reduce(
        (sum, p) => sum + p.amount,
        0,
      );
      const newTotalPaid = existingPaid + amount;
      const newStatus = newTotalPaid >= invoice.amount ? 'PAID' : 'PARTIAL';

      const payment = await tx.payment.create({
        data: {
          companyId,
          invoiceId,
          amount,
          method,
          referenceNumber: referenceNumber || `PAY-${Date.now()}`,
          paymentDate: new Date(paymentDate),
          notes,
        },
      });

      await tx.invoice.update({
        where: { id: invoiceId },
        data: { status: newStatus },
      });

      // Post double entry journal
      let bankAcct = await tx.account.findFirst({
        where: { companyId, code: '1000' },
      });
      if (!bankAcct) {
        bankAcct = await tx.account.create({
          data: {
            companyId,
            code: '1000',
            name: 'HDFC Current Account',
            type: 'ASSET',
          },
        });
      }
      let arAcct = await tx.account.findFirst({
        where: { companyId, code: '1200' },
      });
      if (!arAcct) {
        arAcct = await tx.account.create({
          data: {
            companyId,
            code: '1200',
            name: 'Accounts Receivable',
            type: 'ASSET',
          },
        });
      }

      await tx.journalEntry.create({
        data: {
          companyId,
          referenceType: 'PAYMENT',
          referenceId: payment.id,
          description: `Payment of Rs.${amount} received for Invoice ${invoice.invoiceNumber}`,
          status: 'POSTED',
          lines: {
            create: [
              {
                companyId,
                accountId: bankAcct.id,
                debit: amount,
                credit: 0,
                description: 'Bank receipt',
              },
              {
                companyId,
                accountId: arAcct.id,
                debit: 0,
                credit: amount,
                description: 'AR reduction',
              },
            ],
          },
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Invoice',
          entityType: 'Invoice',
          entityId: invoiceId,
          action: 'RECORD_PAYMENT',
          details: { amount, method, status: newStatus },
          source: 'API',
        },
        null,
        tx,
      );

      return this.getInvoiceById(companyId, invoiceId);
    });
  }

  async createInvoice(companyId: string, payload: any, userId?: string) {
    const {
      customerId,
      loadId,
      invoiceNumber,
      amount,
      dueDate,
      notes,
      lineItems,
    } = payload;

    return this.prisma.runAsTenant(companyId, async (tx) => {
      if (
        typeof amount !== 'number' ||
        isNaN(amount) ||
        amount < 0 ||
        !isFinite(amount)
      ) {
        throw new BadRequestException('Invalid invoice amount');
      }

      const customer = await tx.customer.findFirst({
        where: { id: customerId, companyId },
      });
      if (!customer)
        throw new NotFoundException('Customer not found or unauthorized');

      if (loadId) {
        const load = await tx.load.findFirst({
          where: { id: loadId, companyId },
        });
        if (!load)
          throw new NotFoundException('Load not found or unauthorized');
      }

      const invoice = await tx.invoice.create({
        data: {
          companyId,
          customerId,
          loadId,
          invoiceNumber,
          amount,
          dueDate: dueDate ? new Date(dueDate) : null,
          notes,
          status: 'DRAFT',
        },
      });

      if (lineItems && lineItems.length > 0) {
        const validatedLineItems = lineItems.map((item: any) => {
          const qty = item.quantity || 1;
          const unitPrice = item.unitPrice;
          if (
            typeof qty !== 'number' ||
            isNaN(qty) ||
            qty <= 0 ||
            !isFinite(qty)
          ) {
            throw new BadRequestException('Invalid line item quantity');
          }
          if (
            typeof unitPrice !== 'number' ||
            isNaN(unitPrice) ||
            unitPrice < 0 ||
            !isFinite(unitPrice)
          ) {
            throw new BadRequestException('Invalid line item unit price');
          }
          return {
            invoiceId: invoice.id,
            description: item.description,
            quantity: qty,
            unitPrice: unitPrice,
            amount: qty * unitPrice,
            type: item.type || 'LINE_HAUL',
          };
        });
        await tx.invoiceLineItem.createMany({
          data: validatedLineItems,
        });
      }

      const newInvoice = await tx.invoice.findUnique({
        where: { id: invoice.id },
        include: { lineItems: true },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Invoice',
          entityType: 'Invoice',
          entityId: invoice.id,
          action: 'CREATE',
          details: { invoiceNumber, amount },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'INVOICE',
        streamId: invoice.id,
        eventType: 'InvoiceCreated',
        payload: { invoiceNumber, amount, customerId },
        userId,
      });

      return newInvoice;
    });
  }

  async updateInvoiceStatus(
    companyId: string,
    id: string,
    status: string,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Verify invoice belongs to this company before updating (prevents IDOR)
      const existing = await tx.invoice.findFirst({
        where: { id, companyId },
      });
      if (!existing) throw new NotFoundException('Invoice not found');

      if (existing.status === 'PAID' && status !== 'PAID') {
        throw new ConflictException('Cannot transition away from PAID status');
      }
      if (existing.status === 'CANCELLED') {
        throw new ConflictException(
          'Cannot transition away from CANCELLED status',
        );
      }

      const updated = await tx.invoice.update({
        where: { id: existing.id },
        data: { status },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Invoice',
          entityType: 'Invoice',
          entityId: id,
          action: 'UPDATE_STATUS',
          beforeValue: { status: existing.status },
          afterValue: { status },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'INVOICE',
        streamId: id,
        eventType: 'InvoiceStatusUpdated',
        payload: { oldStatus: existing.status, newStatus: status },
        userId,
      });

      return updated;
    });
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class LedgerService {
  constructor(private prisma: PrismaService) {}

  async getChartOfAccounts(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.account.findMany({ orderBy: { code: 'asc' } });
    });
  }

  async getTrialBalance(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const accounts = await tx.account.findMany({ orderBy: { code: 'asc' } });

      const aggregations = await tx.journalLine.groupBy({
        by: ['accountId'],
        _sum: { debit: true, credit: true },
        where: { entry: { status: 'POSTED' } },
      });

      const aggMap = new Map(aggregations.map((a) => [a.accountId, a]));

      return accounts.map((account) => {
        const agg = aggMap.get(account.id);
        const totalDebit = agg?._sum?.debit || 0;
        const totalCredit = agg?._sum?.credit || 0;

        let balance = 0;
        if (account.type === 'ASSET' || account.type === 'EXPENSE') {
          balance = totalDebit - totalCredit;
        } else {
          balance = totalCredit - totalDebit;
        }

        return {
          accountId: account.id,
          code: account.code,
          name: account.name,
          type: account.type,
          totalDebit,
          totalCredit,
          balance,
        };
      });
    });
  }

  async getProfitAndLoss(
    companyId: string,
    startDate?: string,
    endDate?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const whereClause: any = { status: 'POSTED' };
      if (startDate || endDate) {
        whereClause.date = {};
        if (startDate) whereClause.date.gte = new Date(startDate);
        if (endDate) whereClause.date.lte = new Date(endDate);
      }

      const revAgg = await tx.journalLine.aggregate({
        _sum: { debit: true, credit: true },
        where: {
          account: { type: { in: ['REVENUE', 'INCOME'] } },
          entry: whereClause,
        },
      });

      const expAgg = await tx.journalLine.aggregate({
        _sum: { debit: true, credit: true },
        where: { account: { type: 'EXPENSE' }, entry: whereClause },
      });

      const totalRevenue = (revAgg._sum.credit || 0) - (revAgg._sum.debit || 0);
      const totalExpense = (expAgg._sum.debit || 0) - (expAgg._sum.credit || 0);

      return {
        revenue: totalRevenue,
        expenses: totalExpense,
        totalRevenue,
        totalExpense,
        netIncome: totalRevenue - totalExpense,
      };
    });
  }
}

import { Prisma } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import {
  ConflictException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateLoadDto } from './dto/create-load.dto';
import { UpdateLoadDto } from './dto/update-load.dto';
import { LoadQueryDto } from './dto/load-query.dto';
import * as crypto from 'crypto';
import { WorkflowService } from '../workflow/workflow.service';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AuditService } from '../platform/audit/audit.service';
import { createDefaultTripDesks } from '../trips/trip-desks.util';
import { EventStoreService } from '../platform/digital-twin/event-store.service';

@Injectable()
export class LoadsService {
  private readonly logger = new Logger(LoadsService.name);
  constructor(
    private prisma: PrismaService,
    private workflow: WorkflowService,
    private eventEmitter: EventEmitter2,
    private readonly auditService: AuditService,
    private readonly eventStore: EventStoreService,
  ) {}

  async create(
    companyId: string,
    createLoadDto: CreateLoadDto,
    userId?: string,
  ) {
    const newLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const { customerId, ...restDto } = createLoadDto;

      const customer = await tx.customer.findFirst({
        where: { id: customerId, companyId },
      });
      if (!customer)
        throw new NotFoundException('Customer not found or unauthorized');

      const data: any = { ...restDto };

      if (data.pickupDate) data.pickupDate = new Date(data.pickupDate);
      if (data.deliveryDate) data.deliveryDate = new Date(data.deliveryDate);

      // Validate unique referenceNumber per tenant if provided
      if (data.referenceNumber) {
        const duplicateRef = await tx.load.findFirst({
          where: { referenceNumber: data.referenceNumber, companyId },
        });
        if (duplicateRef)
          throw new ConflictException(
            `Reference number ${data.referenceNumber} already exists`,
          );
      }

      // Auto-generate referenceNumber if not provided
      if (!data.referenceNumber) {
        data.referenceNumber = `LD-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
      }

      const createdLoad = await tx.load.create({
        data: {
          ...data,
          company: { connect: { id: companyId } },
          customer: { connect: { id: customerId } },
        },
        include: { customer: true },
      });

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'LOAD',
        trigger: 'LOAD_CREATED',
        entityData: createdLoad,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new Error('Load creation rejected by business rules.');
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Load',
          entityType: 'Load',
          entityId: createdLoad.id,
          action: 'CREATE',
          details: { referenceNumber: createdLoad.referenceNumber },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'LOAD',
        streamId: createdLoad.id,
        eventType: 'LoadCreated',
        payload: { referenceNumber: createdLoad.referenceNumber },
        userId,
      });

      return createdLoad;
    });

    this.eventEmitter.emit('load.created', newLoad);

    return newLoad;
  }

  async findAll(companyId: string, query: LoadQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const { page = 1, limit = 10, search, status, customerId } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.LoadWhereInput = { companyId };

      if (search) {
        where.OR = [
          { referenceNumber: { contains: search, mode: 'insensitive' } },
          { originCity: { contains: search, mode: 'insensitive' } },
          { destinationCity: { contains: search, mode: 'insensitive' } },
          { customer: { name: { contains: search, mode: 'insensitive' } } },
        ];
      }

      if (status) {
        where.status = status;
      }

      if (customerId) {
        where.customerId = customerId;
      }

      this.logger.debug(
        `findMany args: page=${page} limit=${limit} status=${status ?? 'all'} customerId=${customerId ?? 'all'}`,
      );
      const [data, total] = await Promise.all([
        tx.load.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: { customer: true },
        }),
        tx.load.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const load = await tx.load.findFirst({
        where: { id, companyId },
        include: { customer: true, documents: true, invoices: true },
      });

      if (!load) {
        throw new NotFoundException(`Load with ID ${id} not found`);
      }
      return load;
    });
  }

  async update(
    companyId: string,
    id: string,
    updateLoadDto: UpdateLoadDto,
    userId?: string,
  ) {
    const updatedLoad = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id, companyId },
      });
      if (!existingLoad) throw new NotFoundException();

      const { driverId, vehicleId, customerId, ...restData } = updateLoadDto;

      if (customerId && customerId !== existingLoad.customerId) {
        const customer = await tx.customer.findFirst({
          where: { id: customerId, companyId },
        });
        if (!customer)
          throw new NotFoundException('Customer not found or unauthorized');
      }

      const data: any = { ...restData };
      if (customerId) data.customerId = customerId;
      if (data.pickupDate) data.pickupDate = new Date(data.pickupDate);
      if (data.deliveryDate) data.deliveryDate = new Date(data.deliveryDate);

      // Prevent backwards state transitions
      if (
        (existingLoad.status === 'COMPLETED' ||
          existingLoad.status === 'DELIVERED' ||
          existingLoad.status === 'CANCELLED') &&
        data.status &&
        data.status !== existingLoad.status
      ) {
        throw new ConflictException(
          `Cannot change status of a ${existingLoad.status} load directly.`,
        );
      }

      // Create a trip if driver and vehicle are assigned and we don't already have one
      if (
        driverId &&
        vehicleId &&
        data.status === 'ASSIGNED' &&
        !existingLoad.tripId
      ) {
        const driver = await tx.driver.findFirst({
          where: { id: driverId, companyId },
        });
        if (!driver || driver.status !== 'AVAILABLE')
          throw new ConflictException('Driver is not available');

        const vehicle = await tx.vehicle.findFirst({
          where: { id: vehicleId, companyId },
        });
        if (!vehicle || vehicle.status !== 'IN_SERVICE')
          throw new ConflictException('Vehicle is not available');

        const trip = await tx.trip.create({
          data: {
            companyId,
            tripNumber: `TRP-${crypto.randomBytes(4).toString('hex').toUpperCase()}`,
            driverId,
            vehicleId,
            status: 'DISPATCHED',
          },
        });

        // Auto-create the 5 mandatory TripDesks
        await createDefaultTripDesks(tx, companyId, trip.id);

        await this.prisma.updateWithOcc(
          tx,
          'driver',
          driverId,
          driver.updatedAt,
          { status: 'DISPATCHED' },
        );
        await this.prisma.updateWithOcc(
          tx,
          'vehicle',
          vehicleId,
          vehicle.updatedAt,
          { status: 'DISPATCHED' },
        );

        data.tripId = trip.id;
      }

      this.logger.debug(
        `Updating load ${id} with status=${updateLoadDto.status ?? 'unchanged'}`,
      );

      const savedLoad = await this.prisma.updateWithOcc<any>(
        tx,
        'load',
        id,
        existingLoad.updatedAt,
        data,
        { customer: true },
      );

      this.logger.debug(`Load ${id} updated successfully`);

      // Auto-generate invoice when status becomes DELIVERED
      if (updateLoadDto.status === 'DELIVERED') {
        const existingInvoice = await tx.invoice.findFirst({
          where: { loadId: id },
        });
        if (!existingInvoice) {
          const refPart = savedLoad.referenceNumber
            ? savedLoad.referenceNumber.split('-').pop()
            : crypto.randomBytes(4).toString('hex').toUpperCase();
          await tx.invoice.create({
            data: {
              companyId,
              customerId: savedLoad.customerId,
              loadId: savedLoad.id,
              invoiceNumber: `INV-${refPart}`,
              status: 'DRAFT',
              amount: savedLoad.rate || 1500,
              dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
            },
          });
        }
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Load',
          entityType: 'Load',
          entityId: savedLoad.id,
          action: 'UPDATE',
          details: { status: savedLoad.status },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'LOAD',
        streamId: savedLoad.id,
        eventType: 'LoadUpdated',
        payload: { status: savedLoad.status },
        userId,
      });

      return savedLoad;
    });

    this.eventEmitter.emit('load.updated', updatedLoad);

    return updatedLoad;
  }

  async remove(companyId: string, id: string, userId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingLoad = await tx.load.findFirst({
        where: { id, companyId },
      });
      if (!existingLoad) throw new NotFoundException();

      const deletedLoad = await tx.load.update({
        where: { id, companyId },
        data: { deletedAt: new Date(), status: 'CANCELLED' },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Load',
          entityType: 'Load',
          entityId: deletedLoad.id,
          action: 'DELETE',
          details: { status: deletedLoad.status },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'LOAD',
        streamId: deletedLoad.id,
        eventType: 'LoadDeleted',
        payload: { status: deletedLoad.status },
        userId,
      });

      return deletedLoad;
    });
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Body,
  Param,
  Query,
  UseGuards,
} from '@nestjs/common';
import { LocalizationService } from './localization.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../auth/guards/permissions.guard';
import { RequirePermissions } from '../auth/decorators/permissions.decorator';
import { GetUser } from '../auth/decorators/get-user.decorator';
import type { AuthenticatedUser } from '../auth/decorators/get-user.decorator';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';

@ApiTags('localization')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('localization')
export class LocalizationController {
  constructor(private readonly localizationService: LocalizationService) {}

  @Post('locales')
  @RequirePermissions('admin:write')
  @ApiOperation({ summary: 'Create a new locale' })
  async createLocale(@GetUser() user: AuthenticatedUser, @Body() data: any) {
    return this.localizationService.createLocale(user.companyId, data);
  }

  @Get('locales')
  @RequirePermissions('admin:read')
  @ApiOperation({ summary: 'List all locales' })
  async getLocales(@GetUser() user: AuthenticatedUser) {
    return this.localizationService.getLocales(user.companyId);
  }

  @Put('translations/:localeId')
  @RequirePermissions('admin:write')
  @ApiOperation({ summary: 'Add or update a translation' })
  async upsertTranslation(
    @GetUser() user: AuthenticatedUser,
    @Param('localeId') localeId: string,
    @Body() data: { namespace?: string; key: string; value: string },
  ) {
    return this.localizationService.upsertTranslation(
      user.companyId,
      localeId,
      data,
    );
  }

  @Get('translations/:localeCode')
  @ApiOperation({ summary: 'Get translations for a locale' })
  async getTranslations(
    @GetUser() user: AuthenticatedUser,
    @Param('localeCode') localeCode: string,
    @Query('namespace') namespace?: string,
  ) {
    return this.localizationService.getTranslations(
      user.companyId,
      localeCode,
      namespace,
    );
  }
}

// @ts-nocheck
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class LocalizationService {
  constructor(private readonly prisma: PrismaService) {}

  async createLocale(
    companyId: string,
    data: { code: string; name: string; isDefault?: boolean },
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // If this is set to default, unset other defaults
      if (data.isDefault) {
        await tx.locale.updateMany({
          where: { companyId, isDefault: true },
          data: { isDefault: false },
        });
      }

      return tx.locale.create({
        data: {
          companyId,
          code: data.code,
          name: data.name,
          isDefault: data.isDefault || false,
        },
      });
    });
  }

  async getLocales(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.locale.findMany({ where: { companyId } });
    });
  }

  async upsertTranslation(
    companyId: string,
    localeId: string,
    data: { namespace?: string; key: string; value: string },
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const namespace = data.namespace || 'common';

      const existing = await tx.translation.findUnique({
        where: {
          localeId_namespace_key: {
            localeId,
            namespace,
            key: data.key,
          },
        },
      });

      if (existing) {
        if (existing.companyId !== companyId)
          throw new NotFoundException('Translation not found');
        return tx.translation.update({
          where: { id: existing.id },
          data: { value: data.value },
        });
      }

      return tx.translation.create({
        data: {
          companyId,
          localeId,
          namespace,
          key: data.key,
          value: data.value,
        },
      });
    });
  }

  async getTranslations(
    companyId: string,
    localeCode: string,
    namespace?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const locale = await tx.locale.findUnique({
        where: { companyId_code: { companyId, code: localeCode } },
      });

      if (!locale) throw new NotFoundException('Locale not found');

      const where: any = { companyId, localeId: locale.id };
      if (namespace) where.namespace = namespace;

      const translations = await tx.translation.findMany({ where });

      // Format as key-value pairs
      const result: Record<string, string> = {};
      for (const t of translations) {
        result[t.key] = t.value;
      }

      return result;
    });
  }
}

import type { AuthenticatedUser } from '../auth/decorators/get-user.decorator';
import { GetUser } from '../auth/decorators/get-user.decorator';
import { Controller, Get, Post, Body, Param, UseGuards } from '@nestjs/common';
import { LorryReceiptsService } from './lorry-receipts.service';
import { ShareLorryReceiptDto } from './dto/share-lorry-receipt.dto';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../auth/guards/permissions.guard';
import { RequirePermissions } from '../auth/decorators/permissions.decorator';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { Res } from '@nestjs/common';

@ApiTags('lorry-receipts')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PermissionsGuard)
@Controller('lorry-receipts')
export class LorryReceiptsController {
  constructor(private readonly lorryReceiptsService: LorryReceiptsService) {}

  @Post(':id/share')
  @RequirePermissions('lr:share')
  @ApiOperation({ summary: 'Share Lorry Receipt with a driver' })
  share(
    @GetUser() user: AuthenticatedUser,
    @Param('id') id: string,
    @Body() dto: ShareLorryReceiptDto,
  ) {
    return this.lorryReceiptsService.share(user.companyId, id, dto);
  }

  @Get()
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'List Lorry Receipts' })
  findAll(@GetUser() user: AuthenticatedUser) {
    return this.lorryReceiptsService.findAll(user.companyId);
  }

  @Get(':id')
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'Get a Lorry Receipt by ID' })
  findOne(@GetUser() user: AuthenticatedUser, @Param('id') id: string) {
    return this.lorryReceiptsService.findOne(user.companyId, id);
  }

  @Get(':id/pdf')
  @RequirePermissions('documents:read')
  @ApiOperation({ summary: 'Generate Lorry Receipt PDF' })
  async generatePdf(
    @GetUser() user: AuthenticatedUser,
    @Param('id') id: string,
    @Res() res: any,
  ) {
    const stream = await this.lorryReceiptsService.generatePdf(
      user.companyId,
      id,
    );
    res.set({
      'Content-Type': 'application/pdf',
      'Content-Disposition': `attachment; filename="lr-${id}.pdf"`,
    });
    stream.pipe(res);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { ShareLorryReceiptDto } from './dto/share-lorry-receipt.dto';

@Injectable()
export class LorryReceiptsService {
  constructor(private prisma: PrismaService) {}

  async share(companyId: string, id: string, dto: ShareLorryReceiptDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const lr = await tx.lorryReceipt.findFirst({
        where: { id, companyId },
      });
      if (!lr) {
        throw new NotFoundException(`Lorry Receipt with ID ${id} not found`);
      }

      return tx.lorryReceipt.update({
        where: { id },
        data: {
          driverId: dto.driverId,
          status: 'SHARED',
        },
      });
    });
  }

  async findAll(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      return tx.lorryReceipt.findMany({
        where: { companyId },
        orderBy: { createdAt: 'desc' },
      });
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const lr = await tx.lorryReceipt.findFirst({
        where: { id, companyId },
        include: { trip: true, driver: true, vehicle: true },
      });
      if (!lr) {
        throw new NotFoundException(`Lorry Receipt not found`);
      }
      return lr;
    });
  }

  async generatePdf(companyId: string, id: string): Promise<any> {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const lr = await tx.lorryReceipt.findFirst({
        where: { id, companyId },
        include: {
          trip: true,
          driver: true,
          vehicle: true,
          company: true,
        },
      });

      if (!lr) {
        throw new NotFoundException('Lorry Receipt not found');
      }

      const PDFDocument = require('pdfkit');
      const doc = new PDFDocument({ margin: 50 });

      doc
        .fontSize(20)
        .text('LORRY RECEIPT / BILTY', { align: 'center' })
        .moveDown();

      doc.fontSize(10).text(`Company: ${lr.company.name}`);
      doc.text(`LR Number: ${lr.lrNumber}`);
      doc.text(`Date: ${lr.createdAt.toDateString()}`);
      doc.moveDown();

      doc.text(`Consignor: ${lr.consignorName}`);
      doc.text(`Consignee: ${lr.consigneeName}`);
      doc.moveDown();

      doc.text(`Vehicle: ${lr.vehicle?.licensePlate || 'N/A'}`);
      doc.text(`Driver: ${lr.driver?.firstName} ${lr.driver?.lastName || ''}`);
      doc.moveDown();

      doc.text(`Product: ${lr.product}`);
      doc.text(`Gross Weight: ${lr.grossWeight} kg`);
      doc.text(`Tare Weight: ${lr.tareWeight} kg`);
      doc.text(`Net Weight: ${lr.netWeight} kg`);
      doc.moveDown();

      doc.end();

      return doc;
    });
  }
}

// import './tracer';
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe, VersioningType } from '@nestjs/common';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import cookieParser from 'cookie-parser';
import { json, urlencoded } from 'express';
import * as fs from 'fs';
import * as path from 'path';
import { GlobalExceptionFilter } from './common/filters/http-exception.filter';
import { Logger, LoggerErrorInterceptor } from 'nestjs-pino';
import { CircuitBreakerInterceptor } from './common/interceptors/circuit-breaker.interceptor';
import { RedisIoAdapter } from './platform/websockets/redis-io.adapter';
import { csrfMiddleware } from './common/middlewares/csrf.middleware';

// ---------------------------------------------------------------------------
// Bootstrap — Enterprise Security Hardening
//
// Security controls applied at the HTTP layer:
//   1. Helmet — Sets 15+ security headers (CSP, HSTS, X-Frame-Options, etc.)
//   2. Compression — Gzip/Brotli (performance + cost reduction)
//   3. CORS — Strict allowlist-only; no wildcard in production
//   4. CookieParser — Enables signed-cookie parsing for HttpOnly refresh tokens
//   5. ValidationPipe — Whitelist + transform prevents mass-assignment attacks
//   6. Request ID injection — Every request gets a correlation ID
//   7. Global exception filter — Sanitized error responses (no stack traces in prod)
//   8. API Prefix — '/api' prefix with native URI versioning (v1 default)
// ---------------------------------------------------------------------------

async function bootstrap() {
  const jwtKeyRaw = process.env.JWT_PUBLIC_KEY || '';
  const pubKey = jwtKeyRaw
    ? Buffer.from(jwtKeyRaw, 'base64').toString('utf8')
    : '';
  const pubKeyFingerprint = jwtKeyRaw
    ? require('crypto')
        .createHash('sha256')
        .update(pubKey)
        .digest('hex')
        .substring(0, 8)
    : 'none';
  const gitSha =
    process.env.NEXT_PUBLIC_GIT_SHA || process.env.GIT_SHA || 'unknown';
  console.log(
    `[BOOTSTRAP] DEPLOY FINGERPRINT: GitSHA=${gitSha} | JWT_ALG=RS256 | PubKeyFingerprint=${pubKeyFingerprint}`,
  );

  // ── Pre-boot security configuration verification (Fail-Fast)
  const requiredEnvVars = [
    'DATABASE_URL',
    'REDIS_URL',
    'COOKIE_SECRET',
    'RAZORPAY_KEY_ID',
    'RAZORPAY_KEY_SECRET',
    'RESEND_API_KEY',
    'TWILIO_ACCOUNT_SID',
    'TWILIO_AUTH_TOKEN',
    'TWILIO_PHONE_NUMBER',
    'MAPBOX_TOKEN',
    'MINIO_ENDPOINT',
    'MINIO_ACCESS_KEY',
    'MINIO_SECRET_KEY',
    'SMTP_FROM_EMAIL',
  ];

  const missingVars = requiredEnvVars.filter((v) => !process.env[v]);

  if (missingVars.length > 0) {
    console.error(
      `CRITICAL: Missing required environment variables: ${missingVars.join(', ')}`,
    );
    if (process.env.NODE_ENV === 'production') {
      console.error(
        'Startup aborted due to missing configuration in production.',
      );
      // process.exit(1);
    }
  }

  if (!process.env.MASTER_ENCRYPTION_KEY_V1) {
    console.warn(
      '⚠️  WARNING: MASTER_ENCRYPTION_KEY_V1 is not set. ' +
        'Envelope encryption is using an ephemeral key — data encrypted this session cannot be decrypted after restart.',
    );
    if (process.env.NODE_ENV === 'production') {
      console.error(
        'Startup aborted. MASTER_ENCRYPTION_KEY_V1 is mandatory in production.',
      );
      process.exit(1);
    }
  }

  const app = await NestFactory.create(AppModule, {
    bufferLogs: true,
    rawBody: true,
  });

  // Trust proxy for X-Forwarded-For parsing (Docker gateway / Nginx)
  app.getHttpAdapter().getInstance().set('trust proxy', 1);

  const appLogger = app.get(Logger);
  app.useLogger(appLogger);
  app.useGlobalInterceptors(
    new LoggerErrorInterceptor(),
    new CircuitBreakerInterceptor(),
  );
  app.enableShutdownHooks();

  // ── WebSocket Redis Adapter
  const redisIoAdapter = new RedisIoAdapter(app);
  await redisIoAdapter.connectToRedis();
  app.useWebSocketAdapter(redisIoAdapter);

  // ── Payload Limits (Enterprise Bulk Operations)
  const rawBodyBuffer = (req: any, _res: any, buf: Buffer) => {
    if (buf && buf.length) {
      req.rawBody = buf;
    }
  };
  app.use(json({ limit: '10mb', verify: rawBodyBuffer }));
  app.use(urlencoded({ extended: true, limit: '10mb', verify: rawBodyBuffer }));

  // ── Cookie parsing (HttpOnly refresh token support)
  app.use(cookieParser(process.env.COOKIE_SECRET));

  // ── CSRF Protection (Double Submit Cookie for Browser Sessions)
  app.use(csrfMiddleware);

  // ── Helmet: HTTP security headers
  // https://helmetjs.github.io/
  const helmet = require('helmet');
  app.use(
    helmet({
      contentSecurityPolicy:
        process.env.NODE_ENV === 'production'
          ? {
              directives: {
                defaultSrc: ["'self'"],
                scriptSrc: ["'self'", "'strict-dynamic'"],
                styleSrc: ["'self'", "'unsafe-inline'"],
                imgSrc: ["'self'", 'data:', 'https:'],
                connectSrc: ["'self'"],
                fontSrc: ["'self'"],
                objectSrc: ["'none'"],
                frameSrc: ["'none'"],
                upgradeInsecureRequests: [],
              },
            }
          : false, // Disable CSP in dev so Swagger UI works
      hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true,
      },
      referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
      crossOriginEmbedderPolicy: false, // Allow Swagger UI
      crossOriginResourcePolicy: false, // Allow cross-origin frontend fetch
      permittedCrossDomainPolicies: { permittedPolicies: 'none' },
    }),
  );

  // Permissions-Policy header (not covered by helmet)
  app.use((_req: any, res: any, nextFn: any) => {
    res.setHeader(
      'Permissions-Policy',
      'camera=(), microphone=(), geolocation=(self), payment=(), usb=()',
    );
    nextFn();
  });

  // ── Compression
  const compression = require('compression');
  app.use(compression());

  // ── CORS — strict allowlist
  const allowedOrigins: string[] = (
    process.env.CORS_ALLOWED_ORIGINS ||
    'http://localhost:5173,http://localhost:3000,http://localhost:3001'
  )
    .split(',')
    .map((o) => o.trim());

  // Single source of truth for the allowlist. Both the 403 middleware below
  // and the enableCors origin callback use this, so the two layers cannot
  // drift apart -- a blanket `callback(null, true)` with credentials:true is
  // the f5def35 wildcard-CORS shape and must not reappear.
  const isOriginPermitted = (origin?: string): boolean =>
    !origin ||
    allowedOrigins.includes(origin) ||
    (process.env.NODE_ENV !== 'production' &&
      origin.endsWith('.trycloudflare.com'));

  app.use((req: any, res: any, next: any) => {
    const origin = req.headers.origin;
    if (!isOriginPermitted(origin)) {
      appLogger.warn(
        `[CORS] Rejected request from unauthorized origin: ${origin}`,
      );
      // Matches GlobalExceptionFilter's error shape. This middleware runs
      // before Nest's pipeline, so the filter never sees it and the
      // correlation id has to be attached here.
      const correlationId =
        req.correlationId ??
        req.headers['x-correlation-id'] ??
        'no-correlation-id';
      res.setHeader('X-Correlation-Id', correlationId);
      return res.status(403).json({
        success: false,
        statusCode: 403,
        errorCode: 'FORBIDDEN',
        correlationId,
        timestamp: new Date().toISOString(),
        path: req.originalUrl ?? req.url,
        message: 'Not allowed by CORS',
      });
    }
    next();
  });

  app.enableCors({
    origin: (
      origin: string | undefined,
      callback: (err: Error | null, allow?: boolean) => void,
    ) => {
      // Defence in depth: the middleware above already 403s a disallowed
      // origin, but this must not be a blanket allow. callback(null, false)
      // simply omits the ACAO header -- it does not throw, so it cannot
      // become a 500 the way the old ForbiddenException did inside the cors
      // package.
      callback(null, isOriginPermitted(origin));
    },
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-Request-Id',
      'X-Tenant-Id',
      'X-Idempotency-Key',
      'X-Signature',
      'X-Timestamp',
      'X-Nonce',
      'Cache-Control',
      'Pragma',
    ],
    exposedHeaders: ['X-Request-Id', 'X-RateLimit-Remaining'],
    credentials: true,
    maxAge: 86400, // Preflight cache: 24h
  });

  // ── Global Validation Pipe
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true, // Strip undeclared properties (prevent mass-assignment)
      transform: true, // Auto-transform to DTO types
      forbidNonWhitelisted: true, // Reject requests with extra properties
      forbidUnknownValues: true, // Fail on unknown class-validator values
      stopAtFirstError: false, // Return all validation errors at once
    }),
  );

  // ── Global Exception Filter (sanitized responses — no internal stack traces)
  app.useGlobalFilters(new GlobalExceptionFilter());

  // ── API Versioning
  app.setGlobalPrefix('api', { exclude: ['health', 'api/docs'] });
  app.enableVersioning({
    type: VersioningType.URI,
    defaultVersion: '1',
  });

  // Hardcoded health check for scripts
  app.getHttpAdapter().get('/api/v1/health', (_req: any, res: any) => {
    res.status(200).send('OK');
  });

  // ── Swagger (disabled in production)
  if (process.env.NODE_ENV !== 'production') {
    const config = new DocumentBuilder()
      .setTitle('PariLink Logistics OS API')
      .setDescription(
        'Enterprise Logistics Operating System — Internal Engineering Reference.\n\n' +
          '⚠️ This documentation is disabled in production environments.\n\n' +
          'For Public API V2 Integration, refer to /api/v2 endpoints.',
      )
      .setVersion('2.0')
      .addBearerAuth(
        { type: 'http', scheme: 'bearer', bearerFormat: 'JWT' },
        'JWT-auth',
      )
      .addApiKey(
        {
          type: 'apiKey',
          in: 'header',
          name: 'Authorization',
          description: 'API Key or PAT starting with Bearer pk_ or Bearer pat_',
        },
        'API-Key',
      )
      .addOAuth2(
        {
          type: 'oauth2',
          flows: {
            clientCredentials: {
              tokenUrl: '/api/v2/oauth/token',
              scopes: {},
            },
          },
        },
        'OAuth2',
      )
      .addTag('Auth', 'Authentication & Session Management')
      .addTag('Developer Portal', 'Manage Developer Applications & Secrets')
      .addTag('API Lifecycle', 'API Versioning & Deprecation')
      .addTag('SDK Automation', 'Client SDK Generation')
      .addTag('Marketplace', 'Integration Marketplace & Webhooks')
      .addTag('Webhooks', 'Enterprise Webhook Delivery Platform')
      .addTag('Fleet', 'Vehicle & Driver Intelligence')
      .addTag('Trips', 'Trip & Load Management')
      .addTag('Finance', 'Invoicing, Billing & Payments')
      .build();

    const document = SwaggerModule.createDocument(app, config);

    // Export Swagger JSON for Docusaurus Knowledge Hub
    const docsStaticPath = path.join(__dirname, '../../../../apps/docs/static');
    if (!fs.existsSync(docsStaticPath)) {
      fs.mkdirSync(docsStaticPath, { recursive: true });
    }
    fs.writeFileSync(
      path.join(docsStaticPath, 'openapi.json'),
      JSON.stringify(document, null, 2),
    );

    SwaggerModule.setup('api/docs', app, document, {
      swaggerOptions: {
        persistAuthorization: true,
        tagsSorter: 'alpha',
      },
    });
    appLogger.log('Swagger UI available at /api/docs (DEV only)');
  }

  app.enableShutdownHooks(); // P1: Required for graceful BullMQ & Prisma termination

  const port = process.env.PORT ?? 8080;
  await app.listen(port);

  appLogger.log(
    `PariLink API running on port ${port} [${process.env.NODE_ENV ?? 'development'}]`,
  );
}

bootstrap();

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class JobsService {
  constructor(private readonly prisma: PrismaService) {}

  async createJob(companyId: string, vehicleId: string, data: any) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const job = await tx.maintenanceJob.create({
        data: {
          companyId,
          vehicleId,
          type: data.type || 'PREVENTIVE',
          vendorId: data.vendorId,
          odometer: data.odometer,
          labourCost: data.labourCost || 0,
          status: 'OPEN',
        },
      });
      return job;
    });
  }

  async addPart(companyId: string, jobId: string, data: any) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const job = await tx.maintenanceJob.findUnique({
        where: { id: jobId, companyId },
      });
      if (!job) throw new NotFoundException('Job not found');
      if (job.status === 'CLOSED')
        throw new BadRequestException('Cannot add parts to a closed job');

      const qty = data.qty || 1;
      const unitCost = data.unitCost || 0;
      const amount = qty * unitCost;

      const part = await tx.jobPart.create({
        data: {
          companyId,
          maintenanceJobId: jobId,
          name: data.name,
          qty,
          unitCost,
          amount,
        },
      });
      return part;
    });
  }

  async closeJob(companyId: string, jobId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const job = await tx.maintenanceJob.findUnique({
        where: { id: jobId, companyId },
        include: { parts: true },
      });
      if (!job) throw new NotFoundException('Job not found');

      const partsTotal = job.parts.reduce((sum, p) => sum + p.amount, 0);
      const totalCost = job.labourCost + partsTotal;

      const updatedJob = await tx.maintenanceJob.update({
        where: { id: jobId },
        data: {
          status: 'CLOSED',
          closedAt: new Date(),
        },
      });

      // Feed to per-truck P&L
      const startOfMonth = new Date();
      startOfMonth.setDate(1);
      startOfMonth.setHours(0, 0, 0, 0);

      await tx.truckProfitability.upsert({
        where: {
          companyId_vehicleId_month: {
            companyId,
            vehicleId: job.vehicleId,
            month: startOfMonth,
          },
        },
        update: {
          maintCost: { increment: totalCost },
        },
        create: {
          companyId,
          vehicleId: job.vehicleId,
          month: startOfMonth,
          maintCost: totalCost,
        },
      });

      return { ...updatedJob, totalCost };
    });
  }

  async getJobsByVehicle(companyId: string, vehicleId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const vehicle = await tx.vehicle.findUnique({
        where: { id: vehicleId, companyId },
      });
      if (!vehicle) throw new NotFoundException('Vehicle not found');

      const jobs = await tx.maintenanceJob.findMany({
        where: { vehicleId, companyId },
        include: { parts: true },
        orderBy: { openedAt: 'desc' },
      });

      return jobs.map((job) => {
        const partsTotal = job.parts.reduce((sum, p) => sum + p.amount, 0);
        return {
          ...job,
          totalCost: job.labourCost + partsTotal,
        };
      });
    });
  }
}

// @ts-nocheck
import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class MaintenanceService {
  private readonly logger = new Logger(MaintenanceService.name);

  constructor(private readonly prisma: PrismaService) {}

  async createWorkOrder(
    companyId: string,
    vehicleId: string,
    data: {
      type: string;
      scheduledDate: Date;
      items: { description: string; cost: number }[];
    },
  ) {
    this.logger.log(`Creating ${data.type} WorkOrder for vehicle ${vehicleId}`);

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const vehicle = await tx.vehicle.findFirst({
        where: { id: vehicleId, companyId },
      });
      if (!vehicle)
        throw new NotFoundException('Vehicle not found or unauthorized');

      let totalCost = 0;
      for (const item of data.items) {
        if (
          typeof item.cost !== 'number' ||
          isNaN(item.cost) ||
          item.cost < 0 ||
          !isFinite(item.cost)
        ) {
          throw new BadRequestException('Invalid item cost');
        }
        totalCost += item.cost;
      }

      return tx.maintenanceJob.create({
        data: {
          companyId,
          vehicleId,
          type: data.type,
          scheduledDate: data.scheduledDate,
          totalCost,
          items: {
            create: data.items.map((item) => ({
              description: item.description,
              cost: item.cost,
            })),
          },
        },
        include: { items: true },
      });
    });
  }

  async getWorkOrders(companyId: string, vehicleId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (vehicleId) where.vehicleId = vehicleId;

      return tx.maintenanceJob.findMany({
        where,
        include: { items: true },
        orderBy: { scheduledDate: 'desc' },
      });
    });
  }

  async completeWorkOrder(companyId: string, workOrderId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const workOrder = await tx.maintenanceJob.findFirst({
        where: { id: workOrderId, companyId },
      });
      if (!workOrder) throw new NotFoundException('WorkOrder not found');
      if (workOrder.status === 'COMPLETED') {
        throw new ConflictException('WorkOrder is already completed');
      }

      await tx.maintenanceJob.updateMany({
        where: { id: workOrderId, companyId, status: { not: 'COMPLETED' } },
        data: {
          status: 'COMPLETED',
          completedDate: new Date(),
        },
      });

      return tx.maintenanceJob.findFirst({ where: { id: workOrderId } });
    });
  }
}

