      details: {
        services: [
          'auth',
          'billing',
          'dispatch',
          'tracking',
          'workflow',
          'operations',
        ],
        meshUptime: '99.99%',
      },
      lastCheckedAt: new Date().toISOString(),
    };
  }

  async checkDependencyHealth(): Promise<HealthComponentStatus> {
    const start = Date.now();
    return {
      component: 'EXTERNAL_DEPENDENCIES',
      status: 'HEALTHY',
      latencyMs: Date.now() - start + 8,
      errorRatePct: 0,
      details: {
        paymentGateways: 'ONLINE',
        smsGateways: 'ONLINE',
        emailSmtp: 'ONLINE',
        gpsProviders: 'ONLINE',
