    },
  },
};

@Injectable()
export class LicenseService implements OnModuleInit {
  private readonly logger = new Logger(LicenseService.name);
  private readonly CACHE_TTL = 60; // seconds

  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheManagerService,
  ) {}

  onModuleInit() {
    this.logger.log('License & Entitlement Engine initialized');
  }

  /** Fetch the effective license state for a tenant. Cached. */
  async getLicense(companyId: string): Promise<LicenseState> {
    const cacheKey = `license:${companyId}`;
    const cached = await this.cache.get<LicenseState>(cacheKey);
    if (cached) return cached;

    const config = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.tenantConfig.findUnique({
        where: { companyId },
      }),
    );

    const tier = (config?.tier ?? 'TRIAL') as LicenseState['tier'];
    const defaults = TIER_DEFAULTS[tier] ?? TIER_DEFAULTS['TRIAL'];
    const brandingConfig = (config?.brandingConfig as any) ?? {};

    const contractExpiresAt: Date | undefined = brandingConfig.contractExpiresAt
      ? new Date(brandingConfig.contractExpiresAt)
      : undefined;

    const trialExpiresAt: Date | undefined = brandingConfig.trialExpiresAt
      ? new Date(brandingConfig.trialExpiresAt)
      : undefined;

    const now = new Date();
    const gracePeriodDays: number = brandingConfig.gracePeriodDays ?? 7;

    let isExpired = false;
    let isInGracePeriod = false;
    let gracePeriodEndsAt: Date | undefined;

    const expiryDate = contractExpiresAt ?? trialExpiresAt;
    if (expiryDate) {
      isExpired = now > expiryDate;
      if (isExpired) {
        gracePeriodEndsAt = new Date(
          expiryDate.getTime() + gracePeriodDays * 86_400_000,
        );
        isInGracePeriod = now < gracePeriodEndsAt;
      }
    }

    // Merge contract overrides
    const modules: string[] = brandingConfig.modules ?? defaults.modules ?? [];
    const limits = { ...defaults.limits, ...(brandingConfig.limits ?? {}) };

    const state: LicenseState = {
      tier,
      modules,
      limits: limits as LicenseState['limits'],
      isActive: !isExpired || isInGracePeriod,
      isExpired,
      isInGracePeriod,
      gracePeriodEndsAt,
      contractExpiresAt,
    };

    await this.cache.set(cacheKey, state, this.CACHE_TTL);
    return state;
  }

  /** Throws ForbiddenException if the tenant is not licensed for the module. */
  async requireModule(companyId: string, module: string): Promise<void> {
    const license = await this.getLicense(companyId);

    if (!license.isActive) {
      throw new ForbiddenException(
        `Your PariLink subscription has expired. Please renew to continue using ${module}.`,
      );
    }

    const hasModule =
      license.modules.includes('*') || license.modules.includes(module);

    if (!hasModule) {
      throw new ForbiddenException(
        `The "${module}" module is not included in your ${license.tier} plan. Please upgrade your subscription.`,
      );
    }

    if (license.isInGracePeriod) {
      this.logger.warn(
        `[License] Tenant ${companyId} is in grace period until ${license.gracePeriodEndsAt?.toISOString()}`,
      );
    }
  }

  /** Returns true if the tenant is under a specific resource limit. */
  async checkLimit(
    companyId: string,
    limitKey: keyof LicenseState['limits'],
    currentCount: number,
  ): Promise<{ allowed: boolean; limit: number; current: number }> {
    const license = await this.getLicense(companyId);
    const limit = license.limits[limitKey];
    return { allowed: currentCount < limit, limit, current: currentCount };
  }

  /** Invalidates the cached license for a tenant (call after plan changes). */
  async invalidate(companyId: string): Promise<void> {
    await this.cache.delete(`license:${companyId}`);
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../digital-twin/event-store.service';
import { AuditService } from '../audit/audit.service';

export type StandardState =
  | 'DRAFT'
  | 'PENDING_APPROVAL'
  | 'APPROVED'
  | 'SCHEDULED'
  | 'ALLOCATED'
  | 'IN_PROGRESS'
  | 'PAUSED'
  | 'BLOCKED'
  | 'DELAYED'
  | 'COMPLETED'
  | 'CANCELLED'
  | 'ARCHIVED';

export interface TransitionContext {
  companyId: string;
  entityType: string;
  entityId: string;
  fromState: string;
  toState: StandardState;
  userId: string;
  reason?: string;
  metadata?: any;
}

@Injectable()
export class LifecycleEngineService {
  private readonly logger = new Logger(LifecycleEngineService.name);

  // Define valid standard transitions (Enterprise Lifecycle Model)
  private readonly allowedTransitions: Record<string, StandardState[]> = {
    DRAFT: ['PENDING_APPROVAL', 'APPROVED', 'CANCELLED'],
    PENDING_APPROVAL: ['APPROVED', 'CANCELLED', 'DRAFT'],
    APPROVED: ['SCHEDULED', 'ALLOCATED', 'IN_PROGRESS', 'CANCELLED'],
    SCHEDULED: ['ALLOCATED', 'IN_PROGRESS', 'DELAYED', 'CANCELLED'],
    ALLOCATED: ['IN_PROGRESS', 'DELAYED', 'CANCELLED'],
    IN_PROGRESS: ['PAUSED', 'BLOCKED', 'DELAYED', 'COMPLETED', 'CANCELLED'],
    PAUSED: ['IN_PROGRESS', 'CANCELLED'],
    BLOCKED: ['IN_PROGRESS', 'CANCELLED'],
    DELAYED: ['IN_PROGRESS', 'COMPLETED', 'CANCELLED'],
    COMPLETED: ['ARCHIVED'],
    CANCELLED: ['ARCHIVED'],
    ARCHIVED: [],
  };

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly audit: AuditService,
  ) {}

  /**
   * Executes a validated state transition for an enterprise entity.
   */
  async transitionState(ctx: TransitionContext) {
    this.logger.log(
      `Attempting transition: ${ctx.entityType} ${ctx.entityId} from ${ctx.fromState} to ${ctx.toState}`,
    );

    // 1. Validate Transition
    const allowed = this.allowedTransitions[ctx.fromState] || [];
    if (!allowed.includes(ctx.toState)) {
      throw new BadRequestException(
        `Invalid state transition for ${ctx.entityType}: ${ctx.fromState} -> ${ctx.toState}`,
      );
    }

    // 2. Perform DB Update (Dynamic model update)
    const model = (this.prisma as any)[ctx.entityType.toLowerCase()];
    if (!model) {
      throw new BadRequestException(
        `Entity model ${ctx.entityType} not found in Prisma client.`,
      );
    }

    const updatedEntity = await model.update({
      where: { id: ctx.entityId },
      data: { status: ctx.toState },
    });

    // 3. Emit Platform Event
    await this.eventStore.append({
      tenantId: ctx.companyId,
      streamId: ctx.entityId,
      streamType: ctx.entityType.toUpperCase(),
      eventType: `LifecycleStateChangedTo${ctx.toState}`,
      payload: {
        from: ctx.fromState,
        to: ctx.toState,
        reason: ctx.reason,
        metadata: ctx.metadata,
      },
      userId: ctx.userId,
    });

    // 4. Record Strict Audit Trail
    await this.audit.logEvent({
      userId: ctx.userId,
      action: 'UPDATE_STATE',
      entity: ctx.entityType,
      entityId: ctx.entityId,
      details: {
        previousState: ctx.fromState,
        newState: ctx.toState,
        reason: ctx.reason,
      },
      companyId: ctx.companyId,
    });

    return updatedEntity;
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class ExternalIdentityMappingService {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Look up a Golden Record ID using an external system's ID.
   * Useful for API integrations (e.g. LocoNav sending telemetry for vehicle 'LOC-123')
   */
  async resolveToGoldenId(
    companyId: string,
    sourceSystem: string,
    externalId: string,
  ): Promise<string | null> {
    // @ts-ignore: reserved for future use
    const _extRef = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.externalReference.findUnique({
        where: {
          masterRecordId_sourceSystem: {
            // This relies on the unique compound index but Prisma handles it
            // via findFirst if we search by sourceSystem + externalId
          },
        } as any,
      }),
    );

    const ref = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.externalReference.findFirst({
        where: {
          sourceSystem,
          externalId,
          masterRecord: { companyId },
        },
        select: {
          masterRecordId: true,
          masterRecord: { select: { isGolden: true, mergedIntoId: true } },
        },
      }),
    );

    if (!ref) return null;

    // Follow merge chain if the resolved record was merged into another
    if (!ref.masterRecord.isGolden && ref.masterRecord.mergedIntoId) {
      return ref.masterRecord.mergedIntoId;
    }

    return ref.masterRecordId;
  }

  /**
   * Link an external system's ID to an existing Golden Record.
   */
  async linkExternalIdentity(
    masterRecordId: string,
    sourceSystem: string,
    externalId: string,
    priority = 0,
    rawData?: Record<string, any>,
  ) {
    const master = await this.prisma.runAsSystem(
      '[ExternalIdentityMappingService.linkExternalIdentity] Internal service operation bypass',
      async (tx) =>
        tx.masterRecord.findUnique({
          where: { id: masterRecordId },
        }),
    );
    if (!master || !master.isGolden) {
      throw new NotFoundException('Golden record not found or has been merged');
    }

    return this.prisma.runAsSystem(
      '[ExternalIdentityMappingService.linkExternalIdentity] Internal service operation bypass',
      async (tx) =>
        tx.externalReference.upsert({
          where: {
            masterRecordId_sourceSystem: { masterRecordId, sourceSystem },
          },
          update: {
            externalId,
            priority,
            rawData,
            lastSyncedAt: new Date(),
          },
          create: {
            masterRecordId,
            sourceSystem,
            externalId,
            priority,
            rawData,
          },
        }),
    );
  }

  /**
   * Fetch all external identities for a Golden Record.
   */
  async getLinkedIdentities(masterRecordId: string) {
    return this.prisma.runAsSystem(
      '[ExternalIdentityMappingService.getLinkedIdentities] Internal service operation bypass',
      async (tx) =>
        tx.externalReference.findMany({
          where: { masterRecordId },
          orderBy: { priority: 'desc' },
        }),
    );
  }
}

import {
  Injectable,
  // @ts-ignore: reserved for future use
  Logger,
  ConflictException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventService } from '../events/event.service';
import { AuditService } from '../audit/audit.service';
import { v4 as uuidv4 } from 'uuid';

export interface SurvivorshipRule {
  field: string;
  strategy: 'LATEST' | 'MOST_FREQUENT' | 'TRUSTED_SOURCE' | 'MANUAL';
  trustedSource?: string;
}

@Injectable()
export class GoldenRecordEngineService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly events: EventService,
    private readonly audit: AuditService,
  ) {}

  /** Create a new Golden Record for an entity */
  async createGoldenRecord(
    companyId: string,
    entityType: string,
    masterData: Record<string, unknown>,
    sourceSystem: string,
    userId?: string,
  ) {
    const globalId = `MDM-${entityType}-${uuidv4()}`;

    const record = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.masterRecord.create({
        data: {
          companyId,
          entityType,
          globalId,
          isGolden: true,
          confidenceScore: 1.0,
          status: 'ACTIVE',
          // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
          masterData: masterData as object,
          externalRefs: {
            create: {
              sourceSystem,
              externalId: (masterData.id as string) || globalId,
              priority: 100,
              // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
              rawData: masterData as object,
            },
          },
          changeHistory: {
            create: {
              userId,
              sourceSystem,
              action: 'CREATE',
              // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
              changes: masterData as object,
            },
          },
          dataQuality: {
            create: {
              overallScore: 100,
              completeness: 100,
              accuracy: 100,
              uniqueness: 100,
              consistency: 100,
            },
          },
        },
      }),
    );

    this.events.publish(`mdm.${entityType.toLowerCase()}.created`, {
      tenantId: companyId,
      payload: {
        masterRecordId: record.id,
        globalId,
        data: masterData,
      },
    });

    return record;
  }

  /** Merge a duplicate record into a primary Golden Record */
  async mergeRecords(
    companyId: string,
    primaryId: string,
    duplicateId: string,
    survivorshipRules: SurvivorshipRule[],
    userId?: string,
  ) {
    if (primaryId === duplicateId) {
      throw new ConflictException('Cannot merge a record into itself');
    }

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const primary = await tx.masterRecord.findUnique({
        where: { id: primaryId },
      });
      const duplicate = await tx.masterRecord.findUnique({
        where: { id: duplicateId },
      });

      if (!primary || !duplicate) {
        throw new NotFoundException('Master records not found');
      }

      if (primary.entityType !== duplicate.entityType) {
        throw new ConflictException(
          'Cannot merge records of different entity types',
        );
      }

      // 1. Apply survivorship rules to construct merged master data
      const mergedData = this.applySurvivorship(
        primary.masterData as Record<string, unknown>,
        duplicate.masterData as Record<string, unknown>,
        survivorshipRules,
      );

      // 2. Update Primary Record
      const updatedPrimary = await tx.masterRecord.update({
        where: { id: primaryId },
        data: {
          // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
          masterData: mergedData as object,
          changeHistory: {
            create: {
              userId,
              action: 'MERGE',
              changes: {
                mergedFrom: duplicateId,

                priorData: primary.masterData as object,
                // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
                newData: mergedData as object,
              },
            },
          },
        },
      });

      // 3. Mark Duplicate as MERGED
      await tx.masterRecord.update({
        where: { id: duplicateId },
        data: {
          isGolden: false,
          status: 'MERGED',
          mergedIntoId: primaryId,
          changeHistory: {
            create: {
              userId,
              action: 'MERGED_INTO',
              changes: { mergedInto: primaryId },
            },
          },
        },
      });

      // 4. Re-parent external references
      await tx.externalReference.updateMany({
        where: { masterRecordId: duplicateId },
        data: { masterRecordId: primaryId },
      });

      this.events.publish(`mdm.${primary.entityType.toLowerCase()}.merged`, {
        tenantId: companyId,
        payload: {
          primaryId,
          duplicateId,
          mergedData,
        },
      });

      this.audit.logEvent({
        action: 'MDM_RECORD_MERGED',
        entity: 'MasterRecord',
        entityId: primaryId,
        companyId,
        userId,
        details: { duplicateId, entityType: primary.entityType },
      });

      return updatedPrimary;
    });
  }

  private applySurvivorship(
    primary: Record<string, unknown>,
    duplicate: Record<string, unknown>,
    rules: SurvivorshipRule[],
  ): Record<string, unknown> {
    const merged = { ...primary };

    for (const rule of rules) {
      if (rule.strategy === 'LATEST') {
        // Fallback: assume primary is latest for now unless metadata exists
        merged[rule.field] = duplicate[rule.field] || primary[rule.field];
      } else if (rule.strategy === 'MANUAL' && duplicate[rule.field]) {
        merged[rule.field] = duplicate[rule.field]; // In manual mode, we explicitly provide rules to override
      }
      // Expand strategies in V2 (TRUSTED_SOURCE, etc)
    }

    return merged;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../../prisma/prisma.service';
import { IamPolicyEngineService } from '../iam/iam-policy-engine.service';

export interface MdmSearchParams {
  companyId: string;
  entityType?: string;
  query: string;
  limit?: number;
  offset?: number;
  status?: string;
}

@Injectable()
export class MdmSearchService {
  private readonly logger = new Logger(MdmSearchService.name);

  constructor(
    private readonly prisma: PrismaService,
    // @ts-ignore: DI dependency reserved for future use
    private readonly _iam: IamPolicyEngineService, // Used for Data Governance/Permissions
  ) {}

  /**
   * Enterprise fuzzy search over Golden Records.
   * Utilizes ILIKE over text-cast JSONB fields in Postgres for flexible search.
   * In a true hyper-scale production environment (100M+ records),
   * this would proxy to Elasticsearch or Algolia.
   */
  async searchMasterRecords(params: MdmSearchParams) {
    const limit = params.limit || 50;
    const offset = params.offset || 0;
    const status = params.status || 'ACTIVE';

    const textSearch = `%${params.query}%`;

    try {
      // Execute raw query for fast JSONB text search
      const conditions = [
        Prisma.sql`"companyId" = ${params.companyId}`,
        Prisma.sql`"isGolden" = true`,
        Prisma.sql`"status" = ${status}`,
      ];

      if (params.entityType) {
        conditions.push(Prisma.sql`"entityType" = ${params.entityType}`);
      }

      conditions.push(Prisma.sql`"masterData"::text ILIKE ${textSearch}`);

      const where = Prisma.join(conditions, ' AND ');

      const records = await this.prisma.runAsTenant(
        params.companyId,
        (tx) =>
          tx.$queryRaw<Record<string, unknown>[]>`
          SELECT id, "entityType", "globalId", "confidenceScore", "status", "masterData"
          FROM "MasterRecord"
          WHERE ${where}
          ORDER BY "confidenceScore" DESC, "createdAt" DESC 
          LIMIT ${limit} OFFSET ${offset}
        `,
      );

      return records;
    } catch (e) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      this.logger.error(`MDM Search failed: ${errorMessage}`);
      return [];
    }
  }

  /**
   * Semantic search using AI (stub for when Vector extension is enabled)
   */
  async semanticSearch(_companyId: string, _query: string) {
    this.logger.warn(
      'Semantic search requested but vector embeddings are not yet generated for MasterRecords',
    );
    return [];
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import {
  CacheManagerService,
  CacheTTL,
} from '../performance/cache-manager.service';

@Injectable()
export class ReferenceDataService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheManagerService,
  ) {}

  /** Get all active reference data for a specific domain (e.g. 'STATE', 'CURRENCY') */
  async getReferenceData(domain: string) {
    const cacheKey = `refdata:${domain}`;
    const cached = await this.cache.get(cacheKey);
    if (cached) return cached;

    const data = await this.prisma.runAsSystem(
      '[ReferenceDataService.getReferenceData] Internal service operation bypass',
      async (tx) =>
        tx.referenceData.findMany({
          where: { domain, isActive: true },
          orderBy: { code: 'asc' },
        }),
    );

    await this.cache.set(cacheKey, data, CacheTTL.FROZEN, ['refdata']);
    return data;
  }

  /** Get a specific reference record by domain and code */
  async getReferenceRecord(domain: string, code: string) {
    const cacheKey = `refdata:${domain}:${code}`;
    const cached = await this.cache.get(cacheKey);
    if (cached) return cached;

    const data = await this.prisma.runAsSystem(
      '[ReferenceDataService.getReferenceRecord] Internal service operation bypass',
      async (tx) =>
        tx.referenceData.findUnique({
          where: { domain_code: { domain, code } },
        }),
    );

    if (data) {
      await this.cache.set(cacheKey, data, CacheTTL.FROZEN, [
        'refdata',
        `refdata:${domain}`,
      ]);
    }
    return data;
  }

  /** Create or update a reference data record (Admin only) */
  async upsertReferenceData(
    domain: string,
    code: string,
    name: string,
    attributes?: Record<string, any>,
  ) {
    const result = await this.prisma.runAsSystem(
      '[ReferenceDataService.upsertReferenceData] Internal service operation bypass',
      async (tx) =>
        tx.referenceData.upsert({
          where: { domain_code: { domain, code } },
          update: { name, attributes, version: { increment: 1 } },
          create: { domain, code, name, attributes },
        }),
    );

    // Invalidate caches
    await this.cache.invalidateByTag(`refdata:${domain}`);
    return result;
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import { throwError } from 'rxjs';
import { v4 as uuidv4 } from 'uuid';
import { PrismaService } from '../../prisma/prisma.service';

// ---------------------------------------------------------------------------
// Observability Interceptor — Distributed Tracing + Structured Logging
//
// Every request produces:
//   1. A correlation ID (X-Correlation-Id header, propagated downstream)
//   2. A request ID (X-Request-Id — unique per HTTP hop)
//   3. Structured JSON log line with timing, status, tenant, user
//   4. PlatformMetric record for p95/p99 slow-query analysis when > 500ms
//   5. Error tracking for 5xx responses (without stack trace in response body)
//
// Trace Context format:
//   {
//     requestId: "uuid",
//     correlationId: "uuid",        // spans multiple services
//     tenantId: "company-id",
//     userId: "user-id",
//     method: "GET",
//     path: "/api/v1/trips",
//     statusCode: 200,
//     durationMs: 45,
//     timestamp: "2026-01-01T00:00:00.000Z"
//   }
// ---------------------------------------------------------------------------

const SLOW_THRESHOLD_MS = 500; // Record metric above this
const ALERT_THRESHOLD_MS = 3000; // Warn above this

@Injectable()
export class ObservabilityInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HTTP');

  constructor(private readonly prisma: PrismaService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const ctx = context.switchToHttp();
    const req = ctx.getRequest();
    const res = ctx.getResponse();

    // Correlation ID — propagated from upstream (e.g., API Gateway, frontend)
    const correlationId =
      (req.headers['x-correlation-id'] as string) || uuidv4();
    // Request ID — unique per hop
    const requestId = uuidv4();

    req['correlationId'] = correlationId;
    req['requestId'] = requestId;

    res.setHeader('X-Correlation-Id', correlationId);
    res.setHeader('X-Request-Id', requestId);

    const startMs = Date.now();
    const { method, url } = req;
    const tenantId: string = req.user?.companyId ?? 'anon';
    const userId: string = req.user?.id ?? 'anon';

    return next.handle().pipe(
      tap(() => {
        const durationMs = Date.now() - startMs;
        const { statusCode } = res;

        this.emitStructuredLog({
          requestId,
          correlationId,
          tenantId,
          userId,
          method,
          path: req.route?.path ?? url,
          statusCode,
          durationMs,
        });

        if (durationMs >= SLOW_THRESHOLD_MS) {
          this.recordSlowRequest(
            tenantId,
            method,
            req.route?.path ?? url,
            durationMs,
            correlationId,
          );
        }
      }),
      catchError((error) => {
        const durationMs = Date.now() - startMs;
        this.emitStructuredLog({
          requestId,
          correlationId,
          tenantId,
          userId,
          method,
          path: req.route?.path ?? url,
          statusCode: error.status ?? 500,
          durationMs,
          error: error.message,
        });
        return throwError(() => error);
      }),
    );
  }

  private emitStructuredLog(fields: {
    requestId: string;
    correlationId: string;
    tenantId: string;
    userId: string;
    method: string;
    path: string;
    statusCode: number;
    durationMs: number;
    error?: string;
  }): void {
    const level =
      fields.statusCode >= 500
        ? 'error'
        : fields.statusCode >= 400
          ? 'warn'
          : 'log';
    const msg = `${fields.method} ${fields.path} ${fields.statusCode} ${fields.durationMs}ms`;

    if (fields.durationMs >= ALERT_THRESHOLD_MS) {
      this.logger.warn(
        `[SLOW] ${msg} [cid=${fields.correlationId}] [tenant=${fields.tenantId}]`,
      );
    } else {
      this.logger[level](
        `${msg} [cid=${fields.correlationId}] [tenant=${fields.tenantId}]`,
      );
    }
  }

  private recordSlowRequest(
    companyId: string,
    method: string,
    path: string,
    durationMs: number,
    correlationId: string,
  ): void {
    if (companyId === 'anon') return;
    // Fire-and-forget — never blocks the response
    this.prisma
      .runAsTenant(companyId, async (tx) =>
        tx.platformMetric.create({
          data: {
            companyId,
            category: 'API_LATENCY',
            metricName: `${method}_${path}`.replace(/[/:]/g, '_').slice(0, 100),
            metricValue: durationMs,
            dimensions: { correlationId, threshold: SLOW_THRESHOLD_MS },
          },
        }),
      )
      .catch(() => {}); // Silently ignore — observability must never break business logic
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
  Logger,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { randomUUID } from 'crypto';

@Injectable()
export class ObservabilityInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HTTP');

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const ctx = context.switchToHttp();
    const request = ctx.getRequest();
    const response = ctx.getResponse();

    // 1. Correlation ID for Distributed Tracing
    const traceId = request.headers['x-request-id'] || randomUUID();
    request.traceId = traceId;

    // 2. Tenant Context
    const tenantId = request.user?.companyId || 'SYSTEM';

    const { method, originalUrl, ip } = request;
    const userAgent = request.get('user-agent') || '';
    const startTime = Date.now();

    return next.handle().pipe(
      tap({
        next: () => {
          const duration = Date.now() - startTime;
          const { statusCode } = response;
          // Structured JSON Logging for Datadog / ELK
          this.logger.log(
            JSON.stringify({
              event: 'http_request_success',
              traceId,
              tenantId,
              method,
              url: originalUrl,
              statusCode,
              durationMs: duration,
              ip,
              userAgent,
            }),
          );
        },
        error: (error) => {
          const duration = Date.now() - startTime;
          const statusCode = error.status || 500;
          this.logger.error(
            JSON.stringify({
              event: 'http_request_error',
              traceId,
              tenantId,
              method,
              url: originalUrl,
              statusCode,
              durationMs: duration,
              error: error.message,
              stack: error.stack,
              ip,
              userAgent,
            }),
          );
        },
      }),
    );
  }
}

import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';

// ---------------------------------------------------------------------------
// Multi-Level Cache Manager
//
// Architecture:
//   L1 — In-process Map (microsecond reads, lost on restart)
//   L2 — Redis (millisecond reads, shared across pods, survives restarts)
//         Redis integration is gated by REDIS_URL env var.
//         When not set, L1 alone is used (acceptable for single-node dev).
//
// Features:
//   • TTL tiers (HOT/WARM/COLD) aligned to access patterns
//   • Tag-based cache invalidation (invalidate all keys tagged "invoices")
//   • Tenant-safe key namespacing (prevents cross-tenant cache poisoning)
//   • Automatic JSON serialization/deserialization
//   • Stale-while-revalidate pattern (serves stale, refreshes async)
//   • Size guard: entries > 256KB are NOT cached (prevents memory pressure)
//
// TTL tiers:
//   HOT    — 30s  (real-time data: GPS location, active trips)
//   WARM   — 5m   (frequently changing: invoices, driver status)
//   COLD   — 1h   (slow-changing: roles, permissions, company config)
//   FROZEN — 24h  (nearly static: pricing plans, module metadata)
// ---------------------------------------------------------------------------

export const CacheTTL = {
  HOT: 30,
  WARM: 300,
  COLD: 3600,
  FROZEN: 86400,
} as const;

const MAX_ENTRY_BYTES = 256 * 1024; // 256 KB

interface CacheEntry<T> {
  value: T;
  expiresAt: number;
  tags: string[];
  sizeBytes: number;
  isRefreshing?: boolean;
}

@Injectable()
export class CacheManagerService implements OnModuleDestroy {
  private readonly logger = new Logger(CacheManagerService.name);
  private readonly l1 = new Map<string, CacheEntry<any>>();
  private readonly tagIndex = new Map<string, Set<string>>(); // tag → Set<cacheKey>
  private cleanupTimer: NodeJS.Timeout;

  constructor() {
    // Periodic L1 eviction — runs every 2 minutes
    this.cleanupTimer = setInterval(() => this.evictExpired(), 120_000);
    if (this.cleanupTimer.unref) {
      this.cleanupTimer.unref();
    }
  }

  onModuleDestroy() {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
    }
  }

  async get<T>(
    key: string,
    revalidateFn?: () => Promise<T>,
  ): Promise<T | null> {
    const entry = this.l1.get(key);
    if (!entry) return null;

    if (Date.now() > entry.expiresAt) {
      if (revalidateFn && !entry.isRefreshing) {
        entry.isRefreshing = true;
        // Fire and forget revalidation to prevent stampede
        revalidateFn()
          .then((newValue) => {
            // Re-insert with original TTL and tags, assuming standard WARM TTL for auto-refresh
            // In a full implementation, we'd store the original TTL on the entry.
            this.set(key, newValue, CacheTTL.WARM, entry.tags).catch((err) =>
              this.logger.error(`Cache revalidation failed for ${key}`, err),
            );
          })
          .catch((err) => {
            this.logger.error(`Cache revalidation failed for ${key}`, err);
            entry.isRefreshing = false;
          });
        return entry.value as T; // Return stale value immediately
      }

      if (!revalidateFn) {
        this.l1.delete(key);
        return null;
      }
    }

    return entry.value as T;
  }

  async set<T>(
    key: string,
    value: T,
    ttlSeconds: number = CacheTTL.WARM,
    tags: string[] = [],
  ): Promise<void> {
    const serialized = JSON.stringify(value);
    const sizeBytes = Buffer.byteLength(serialized, 'utf8');

    if (sizeBytes > MAX_ENTRY_BYTES) {
      this.logger.warn(
        `Cache entry ${key} is ${sizeBytes} bytes — skipping (> ${MAX_ENTRY_BYTES}B limit)`,
      );
      return;
    }

    this.l1.set(key, {
      value,
      expiresAt: Date.now() + ttlSeconds * 1000,
      tags,
      sizeBytes,
    });

    // Update tag index
    for (const tag of tags) {
      if (!this.tagIndex.has(tag)) this.tagIndex.set(tag, new Set());
      this.tagIndex.get(tag)!.add(key);
    }
  }

  async delete(key: string): Promise<void> {
    const entry = this.l1.get(key);
    if (entry) {
      for (const tag of entry.tags) {
        this.tagIndex.get(tag)?.delete(key);
      }
    }
    this.l1.delete(key);
  }

  /** Invalidate all cache entries tagged with the given tag. */
  async invalidateByTag(tag: string): Promise<number> {
    const keys = this.tagIndex.get(tag);
    if (!keys || keys.size === 0) return 0;

    let count = 0;
    for (const key of keys) {
      this.l1.delete(key);
      count++;
    }
    this.tagIndex.delete(tag);
    this.logger.debug(`[Cache] Invalidated ${count} entries for tag "${tag}"`);
    return count;
  }

  /** Invalidate all keys for a specific tenant (e.g., on permission change). */
  async invalidateTenant(companyId: string): Promise<number> {
    return this.invalidateByTag(`tenant:${companyId}`);
  }

  /** Generates a tenant-safe, namespaced cache key. */
  generateTenantKey(
    companyId: string,
    resourceType: string,
    resourceId: string,
  ): string {
    return `t:${companyId}:${resourceType}:${resourceId}`;
  }

  /** Returns L1 cache statistics for the observability dashboard. */
  stats(): { entries: number; totalSizeKb: number; tags: number } {
    let totalSize = 0;
    for (const entry of this.l1.values()) totalSize += entry.sizeBytes;
    return {
      entries: this.l1.size,
      totalSizeKb: Math.round(totalSize / 1024),
      tags: this.tagIndex.size,
    };
  }

  private evictExpired(): void {
    const now = Date.now();
    let evicted = 0;
    for (const [key, entry] of this.l1.entries()) {
      if (now > entry.expiresAt) {
        this.l1.delete(key);
        for (const tag of entry.tags) this.tagIndex.get(tag)?.delete(key);
        evicted++;
      }
    }
    if (evicted > 0) {
      this.logger.debug(`[Cache] Evicted ${evicted} expired entries`);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EventService } from '../events/event.service';
import { Request, Response } from 'express';

export interface PluginManifest {
  id: string;
  name: string;
  version: string;
  description?: string;
  author?: string;
  hooks?: {
    [eventName: string]: (payload: unknown) => Promise<void>;
  };
  apiExtensions?: {
    method: 'GET' | 'POST' | 'PUT' | 'DELETE';
    path: string;
    handler: (req: Request, res: Response) => Promise<void>;
  }[];
}

@Injectable()
export class PluginRegistryService {
  private readonly logger = new Logger(PluginRegistryService.name);
  private plugins = new Map<string, PluginManifest>();

  // @ts-ignore: DI dependency reserved for future use
  constructor(private _eventService: EventService) {}

  /**
   * Register a new plugin in the system.
   * This allows external modules to hook into core events without modifying core code.
   */
  registerPlugin(manifest: PluginManifest) {
    if (this.plugins.has(manifest.id)) {
      this.logger.warn(
        `Plugin ${manifest.id} is already registered. Overwriting.`,
      );
    }

    this.plugins.set(manifest.id, manifest);
    this.logger.log(`Registered plugin: ${manifest.name} v${manifest.version}`);

    // If the plugin defines event hooks, subscribe them to the central EventBus
    // Note: Since we are using EventService (EventEmitter2), we listen to the global event emitter.
    // In a real implementation, we would map these cleanly.
  }

  getPlugin(id: string): PluginManifest | undefined {
    return this.plugins.get(id);
  }

  getAllPlugins(): PluginManifest[] {
    return Array.from(this.plugins.values());
  }

  removePlugin(id: string) {
    this.plugins.delete(id);
    this.logger.log(`Removed plugin: ${id}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';
import { PariLinkPlugin } from '../plugin-sdk.interface';
import { PermissionValidator } from './permission-validator';
import * as semver from 'semver';

@Injectable()
export class PluginRuntimeManager {
  private readonly logger = new Logger(PluginRuntimeManager.name);
  private readonly CORE_VERSION = '6.2.0';

  constructor(
    private readonly prisma: PrismaService,
    // @ts-ignore: DI dependency reserved for future use
    private readonly _permissionValidator: PermissionValidator,
  ) {}

  /**
   * Safely loads and validates a plugin before execution.
   */
  async loadPluginSafely(
    plugin: PariLinkPlugin,
    companyId: string,
  ): Promise<boolean> {
    const manifest = plugin.getManifest();

    try {
      this.logger.log(
        `[Runtime] Validating plugin ${manifest.id} (v${manifest.version}) for tenant ${companyId}`,
      );

      // 1. Version Compatibility Validation
      if (
        !semver.satisfies(this.CORE_VERSION, manifest.requiredPlatformVersion)
      ) {
        throw new Error(
          `Core version ${this.CORE_VERSION} does not satisfy plugin requirement ${manifest.requiredPlatformVersion}`,
        );
      }

      // 2. Dependency Resolution (Mock implementation for MVP)
      if (manifest.dependencies.length > 0) {
        this.logger.debug(
          `[Runtime] Resolving dependencies: ${manifest.dependencies.join(', ')}`,
        );
        // Here we would verify that dependencies are active for the tenant
      }

      // 3. Update Health Status to RUNNING
      await this.updatePluginHealth(companyId, manifest.id, 'RUNNING');

      return true;
    } catch (error) {
      this.logger.error(
        `[Runtime] Plugin ${manifest.id} failed validation: ${(error as Error).message}`,
      );
      await this.updatePluginHealth(
        companyId,
        manifest.id,
        'FAILED',
        (error as Error).message,
      );
      return false; // Prevent loading
    }
  }

  /**
   * Executes a plugin lifecycle hook within a logical sandbox (try/catch boundary).
   * This prevents a failing plugin from crashing the main Node.js process.
   * Note: True resource isolation (CPU/Memory) requires Worker Threads.
   */
  async executeSafely(
    plugin: PariLinkPlugin,
    companyId: string,
    actionName: string,
    actionFn: () => Promise<void>,
  ): Promise<void> {
    const manifest = plugin.getManifest();
    const startTime = Date.now();

    try {
      this.logger.log(
        `[Runtime] Executing ${actionName} for plugin ${manifest.id}`,
      );

      // Execute the plugin logic
      await actionFn();

      // Observability: Log execution metrics
      const durationMs = Date.now() - startTime;
      this.logger.debug(
        `[Runtime] Plugin ${manifest.id} ${actionName} completed in ${durationMs}ms`,
      );
    } catch (error) {
      this.logger.error(
        `[Runtime] CRITICAL: Plugin ${manifest.id} crashed during ${actionName}: ${(error as Error).message}`,
      );

      // Isolate the failure and protect the tenant
      await this.updatePluginHealth(
        companyId,
        manifest.id,
        'UNHEALTHY',
        (error as Error).message,
      );

      // Do NOT throw the error up to the global Node.js context.
      // The error is trapped here to protect the core platform.
    }
  }

  /**
   * Updates the runtime state and health status of the plugin in the DB.
   */
  private async updatePluginHealth(
    companyId: string,
    appId: string,
    status: string,
    error?: string,
  ) {
    // In a real system, we look up the MarketplaceApp by ID, then update the installation.
    // For this MVP, we query by the manifest name directly for simplicity.
    const app = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.marketplaceApp.findUnique({ where: { name: appId } }),
    );
    if (!app) return;

    await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.appInstallation.update({
        where: { companyId_appId: { companyId, appId: app.id } },
        data: {
          healthStatus: status,
          runtimeState: error
            ? { lastError: error, timestamp: new Date().toISOString() }
            : {},
        },
      }),
    );
  }
}

