import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';

@Injectable()
export class DriverTripsService {
  constructor(private prisma: PrismaService) {}

  async getActiveTrip(companyId: string, driverId: string) {
    if (!driverId) throw new UnauthorizedException('Driver context missing');

    // Find trips that are dispatched or in transit for the driver
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findFirst({
        where: {
          companyId,
          driverId,
          status: { in: ['PLANNED', 'DISPATCHED', 'IN_TRANSIT'] },
        },
        include: {
          vehicle: { select: { licensePlate: true, type: true } },
          loads: {
            include: {
              customer: { select: { name: true, phone: true } },
            },
          },
        },
        orderBy: { createdAt: 'asc' }, // Get the oldest active trip first
      }),
    );

    return trip;
  }

  async updateTripStatus(
    companyId: string,
    driverId: string,
    tripId: string,
    status: string,
    _location: any,
  ) {
    if (!driverId) throw new UnauthorizedException('Driver context missing');

    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId, driverId },
      }),
    );

    if (!trip) {
      throw new UnauthorizedException('Trip not found or access denied');
    }

    // Optionally log location in LocationHistory here

    return await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.update({
        where: { id: tripId },
        data: { status },
      }),
    );
  }
}

import {
  Injectable,
  OnModuleInit,
  OnModuleDestroy,
  Logger,
  ConflictException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaClient, Prisma } from '@prisma/client';
import { queryMonitorStorage } from '../common/query-monitor.storage';

@Injectable()
export class PrismaService
  extends PrismaClient<
    Prisma.PrismaClientOptions,
    'query' | 'info' | 'warn' | 'error'
  >
  implements OnModuleInit, OnModuleDestroy
{
  private readonly logger = new Logger(PrismaService.name);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private readonly dmmfModels = new Map<string, any>();
  private readonly systemClient: PrismaClient;

  constructor() {
    let datasourceUrl =
      process.env.APP_DATABASE_URL || process.env.DATABASE_URL;
    if (datasourceUrl) {
      try {
        const url = new URL(datasourceUrl);
        if (process.env.USE_PGBOUNCER === 'true') {
          url.searchParams.set('pgbouncer', 'true');
        }
        if (process.env.NODE_ENV === 'test') {
          url.searchParams.set('connection_limit', '2');
          url.searchParams.set('pool_timeout', '10');
        } else {
          // Connection math (max_connections=100, reserve 10 for maintenance → budget=90):
          // Main datasource:   16 connections/instance
          // System datasource:  2 connections/instance
          // Total per instance: 42 connections
          // 2 instances × 42 = 84 = budget.
          url.searchParams.set('connection_limit', '40');
        }
        datasourceUrl = url.toString();
      } catch (e) {
        // ignore invalid URL parsing errors
      }
    }

    super({
      datasourceUrl,
      log: [
        { emit: 'event', level: 'query' },
        { emit: 'event', level: 'error' },
        { emit: 'event', level: 'warn' },
      ],
    });

    this.$on('error', (e) => this.logger.error(`Prisma Error: ${e.message}`));
    this.$on('warn', (e) => this.logger.warn(`Prisma Warn: ${e.message}`));

    let systemDatasourceUrl = process.env.SYSTEM_DATABASE_URL || datasourceUrl;
    if (systemDatasourceUrl) {
      try {
        const url = new URL(systemDatasourceUrl);
        if (process.env.NODE_ENV === 'test') {
          url.searchParams.set('connection_limit', '5');
        } else {
          // System datasource: 2 connections/instance.
          // (16 main + 2 system) × 5 instances = 90 = budget.
          url.searchParams.set('connection_limit', '2');
        }
        systemDatasourceUrl = url.toString();
      } catch (e) {}
    }
    this.systemClient = new PrismaClient({
      datasourceUrl: systemDatasourceUrl,
      log: [
        { emit: 'event', level: 'query' },
        { emit: 'event', level: 'error' },
        { emit: 'event', level: 'warn' },
      ],
    });
  }

  async onModuleInit() {
    // Cache DMMF models and their fields for O(1) lookup during soft-delete middleware
    for (const model of Prisma.dmmf.datamodel.models) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const fieldsMap = new Map<string, any>();
      for (const field of model.fields) {
        fieldsMap.set(field.name, field);
      }
      this.dmmfModels.set(model.name, { ...model, fieldsMap });
    }
    // await this.$connect(); // Bypassed for local load testing without a running DB
    this.setupSoftDeleteMiddleware();
    await this.assertRequestPathIsNotPrivileged();
  }

  /**
   * The request path must never connect as a SUPERUSER or a BYPASSRLS role.
   *
   * Both would make every RLS policy inert -- silently. A superuser ignores
   * row security entirely, and BYPASSRLS does the same by design; neither
   * logs anything, and every tenant query would quietly return every tenant's
   * rows while all 231 policies still look correct in pg_policies.
   *
   * The failure is one typo away. The datasource above resolves as
   *     process.env.APP_DATABASE_URL || process.env.DATABASE_URL
   * and .env.example documents DATABASE_URL as "migrations and admin only;
   * privileged". So an unset or misspelled APP_DATABASE_URL in any single
   * environment silently promotes the request path to the admin role. A
   * one-off check proves one environment at one moment; this proves it at
   * every boot, in every environment, or refuses to serve.
   *
   * SYSTEM_DATABASE_URL is deliberately NOT checked here: parilink_sys is
   * supposed to hold BYPASSRLS. Whether an empty SYSTEM_DATABASE_URL should
   * be fatal rather than silently degrading runAsSystem to zero rows is a
   * separate decision -- see the note in .env.example.
   */
  private async assertRequestPathIsNotPrivileged(): Promise<void> {
    // An opt-out exists for the no-database load-testing mode the commented
    // $connect() above refers to, but it cannot be used in production.
    if (
      process.env.SKIP_RLS_ROLE_CHECK === 'true' &&
      process.env.NODE_ENV !== 'production'
    ) {
      this.logger.warn(
        '[RLS] request-path role assertion SKIPPED (SKIP_RLS_ROLE_CHECK=true). ' +
          'This flag is ignored when NODE_ENV=production.',
      );
      return;
    }

    const rows = await this.$queryRaw<
      Array<{ current_user: string; is_superuser: string; bypassrls: boolean }>
    >`SELECT current_user,
             current_setting('is_superuser') AS is_superuser,
             (SELECT rolbypassrls FROM pg_roles WHERE rolname = current_user) AS bypassrls`;

    const role = rows[0];
    if (!role) {
      throw new Error(
        'FATAL: could not determine the request-path database role. Refusing to start.',
      );
    }

    if (role.is_superuser === 'on' || role.bypassrls) {
      throw new Error(
        `FATAL: request-path connection is '${role.current_user}' ` +
          `(superuser=${role.is_superuser}, bypassrls=${role.bypassrls}). ` +
          'RLS is INERT on this connection -- every tenant policy is bypassed. ' +
          'Set APP_DATABASE_URL to a NOSUPERUSER NOBYPASSRLS role.',
      );
    }

    this.logger.log(
      `[RLS] request path connected as '${role.current_user}' (no superuser, no bypass)`,
    );
  }

  async onModuleDestroy() {
    await this.$disconnect();
    await this.systemClient.$disconnect();
  }

  private setupSoftDeleteMiddleware() {
    this.$use(async (params, next) => {
      const store = queryMonitorStorage.getStore();
      if (store) {
        store.count++;
      }

      if (!params.model) return next(params);

      const model = this.dmmfModels.get(params.model);
      if (!model) return next(params);

      const hasDeletedAt = model.fields.some(
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (f: any) => f.name === 'deletedAt',
      );

      if (!hasDeletedAt) return next(params);

      if (
        params.action === 'findUnique' ||
        params.action === 'findFirst' ||
        params.action === 'findMany'
      ) {
        if (params.action === 'findUnique') {
          params.action = 'findFirst';
        }
        params.args = params.args || {};

        // Detect if this is a drill-down lookup (explicitly querying by ID)
        const isDrillDown = params.args?.where?.id !== undefined;

        const injectSoftDelete = (
          args: any,
          modelName: string,
          isRoot = false,
        ) => {
          if (!args) return;
          const currentModel = this.dmmfModels.get(modelName);
          if (!currentModel) return;

          const hasDelAt = currentModel.fields.some(
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (f: any) => f.name === 'deletedAt',
          );
          if (hasDelAt) {
            if (!args.where) {
              args.where = {};
            }
            if (isRoot && isDrillDown) {
              // Bypass soft-delete injection for root drill-down queries
            } else if (args.where.deletedAt === undefined) {
              args.where.deletedAt = null;
            }
          }

          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const processNested = (container: any) => {
            if (!container) return;
            for (const key of Object.keys(container)) {
              const val = container[key];
              const field = currentModel.fieldsMap.get(key);
              if (field && field.kind === 'object') {
                if (val === true) {
                  container[key] = {};
                  if (field.isList) {
                    injectSoftDelete(container[key], field.type, false);
                  } else {
                    // For to-one relations, we just process nested includes but don't inject `where` on this level
                    processNestedIncludeOnly(container[key], field.type);
                  }
                } else if (typeof val === 'object' && val !== null) {
                  if (field.isList) {
                    injectSoftDelete(val, field.type, false);
                  } else {
                    processNestedIncludeOnly(val, field.type);
                  }
                }
              }
            }
          };

          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const processNestedIncludeOnly = (args: any, modelName: string) => {
            if (!args) return;
            const nestedModel = this.dmmfModels.get(modelName);
            if (!nestedModel) return;

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const nestedProcess = (container: any) => {
              if (!container) return;
              for (const key of Object.keys(container)) {
                const val = container[key];
                const field = nestedModel.fieldsMap.get(key);
                if (field && field.kind === 'object') {
                  if (val === true) {
                    container[key] = {};
                    if (field.isList) {
                      injectSoftDelete(container[key], field.type, false);
                    } else {
                      processNestedIncludeOnly(container[key], field.type);
                    }
                  } else if (typeof val === 'object' && val !== null) {
                    if (field.isList) {
                      injectSoftDelete(val, field.type, false);
                    } else {
                      processNestedIncludeOnly(val, field.type);
                    }
                  }
                }
              }
            };
            nestedProcess(args.include);
            nestedProcess(args.select);
          };

          processNested(args.include);
          processNested(args.select);
        };

        injectSoftDelete(params.args, params.model, true);
      }

      const result = await next(params);

      // Post-process the result to append deleted: true flag
      if (params.action === 'findFirst' || params.action === 'findMany') {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const flagDeleted = (obj: any, seen = new Set()) => {
          if (!obj || typeof obj !== 'object') return;
          if (seen.has(obj)) return;
          seen.add(obj);

          if (obj.deletedAt !== null && obj.deletedAt !== undefined) {
            obj.deleted = true;
          }

          for (const key of Object.keys(obj)) {
            if (Array.isArray(obj[key])) {
              obj[key].forEach((item: any) => flagDeleted(item, seen));
            } else if (typeof obj[key] === 'object') {
              flagDeleted(obj[key], seen);
            }
          }
        };

        if (Array.isArray(result)) {
          result.forEach((item) => flagDeleted(item));
        } else {
          flagDeleted(result);
        }
      }

      return result;
      // We DO NOT convert 'update' to 'updateMany' because updateMany does not support 'include'/'select'
      // and returns a BatchPayload { count: number } instead of the updated object.
      // If we want to prevent updating deleted records, we rely on findFirst/findUnique checks beforehand,
      // which the services already do.
      if (params.action === 'updateMany') {
        params.args = params.args || {};
        if (params.args.where) {
          if (params.args.where.deletedAt === undefined) {
            params.args.where = { ...params.args.where };
          }
        } else {
          params.args.where = {};
        }
      }
      if (params.action === 'delete') {
        params.action = 'update';
        params.args = params.args || {};
        params.args.data = { deletedAt: new Date() };
      }
      if (params.action === 'deleteMany') {
        params.action = 'updateMany';
        params.args = params.args || {};
        if (params.args.data !== undefined) {
          params.args.data = { ...params.args.data, deletedAt: new Date() };
        } else {
          params.args.data = { deletedAt: new Date() };
        }
      }
      return next(params);
    });
  }

  /**
   * Executes a callback within a Prisma transaction that has RLS enabled
   * for the given companyId.
   */
  async runAsTenant<T>(
    companyId: string,
    callback: (
      tx: Omit<
        PrismaClient,
        | '$connect'
        | '$disconnect'
        | '$on'
        | '$transaction'
        | '$use'
        | '$extends'
      >,
    ) => Promise<T>,
  ): Promise<T> {
    return this.$transaction(async (tx) => {
      // Set the PostgreSQL local configuration variable for this transaction
      await tx.$executeRaw`SELECT set_config('app.current_company_id', ${companyId}, true)`;

      // Wrap the transaction object to intercept raw SQL execution inside the callback.
      //
      // SECURITY NOTE (2026-09-17): A raw set_config('app.current_company_id', ...) call
      // inside a runAsTenant transaction can repoint tenant context mid-transaction,
      // allowing cross-tenant data access. This was confirmed exploitable at the database
      // level via BOTH $executeRawUnsafe AND $queryRawUnsafe:
      //   - $executeRawUnsafe: intercepted since original implementation
      //   - $queryRawUnsafe: gap discovered and closed here — SqlGeneratorService uses this
      //     method with LLM-influenced SQL and CopilotService is live in the DI container
      //     (registered in AiModule, imported by AppModule) even though no HTTP controller
      //     currently calls it. One method call away from being active.
      // All four raw-query methods are now intercepted uniformly.
      const INTERCEPTED_RAW_METHODS = new Set([
        '$executeRaw',
        '$executeRawUnsafe',
        '$queryRaw',
        '$queryRawUnsafe',
      ]);

      const safeTx = new Proxy(tx, {
        get(target, prop, receiver) {
          if (typeof prop === 'string' && INTERCEPTED_RAW_METHODS.has(prop)) {
            return function (this: any, ...args: any[]) {
              let queryStr = '';
              const firstArg = args[0];

              if (Array.isArray(firstArg)) {
                // Prisma.Sql template literal — strings[] joined with param placeholders
                queryStr = firstArg.join('');
              } else if (firstArg && typeof firstArg.text === 'string') {
                // Prisma.Sql object
                queryStr = firstArg.text;
              } else if (typeof firstArg === 'string') {
                // Raw string ($executeRawUnsafe / $queryRawUnsafe)
                queryStr = firstArg;
              }

              if (/set_config\s*\(/i.test(queryStr)) {
                throw new Error(
                  'Forbidden raw query pattern: session configuration injection is blocked by security interceptor',
                );
              }

              return Reflect.get(target, prop, receiver).apply(this, args);
            };
          }
          return Reflect.get(target, prop, receiver);
        },
      });

      // Execute the business logic within the RLS-constrained transaction
      return callback(safeTx);
    });
  }

  /**
   * Executes a callback within a Prisma transaction that bypasses RLS policies
   * for system/admin operations across all companies.
   * A valid reason MUST be provided for security auditing.
   *
   * REASON STRING, HONESTLY: this only enforces length (>=5 chars), not
   * content. ~74 of the ~230 call sites in this codebase currently pass the
   * literal string 'System operation or legacy bypass', which satisfies the
   * length check but is not a real audit trail -- it can't tell you *why*
   * RLS was bypassed for a given call. Rejecting that placeholder outright
   * was considered and deliberately NOT done here: it would break ~74 call
   * sites at once, and reviewing/rewriting each one's actual reason is real
   * work that deserves its own change, not something to fold into this
   * security pass. New code added in this pass (runAsTenantById below)
   * passes a real, dynamic, per-call reason. Backfilling the other 74 is
   * flagged as follow-up work, not silently dropped.
   */
  async runAsSystem<T>(
    reason: string,
    callback: (
      tx: Omit<
        PrismaClient,
        | '$connect'
        | '$disconnect'
        | '$on'
        | '$transaction'
        | '$use'
        | '$extends'
      >,
    ) => Promise<T>,
  ): Promise<T> {
    if (!reason || reason.trim().length < 5) {
      throw new Error('A valid reason must be provided to bypass RLS.');
    }

    this.logger.warn(
      `[SECURITY_AUDIT] SYSTEM_BYPASS: Bypassing RLS. Reason: ${reason}`,
    );

    // Execute the business logic using the system-level connection inside a transaction
    // to guarantee connection isolation, configuring maxWait to prevent pool exhaustion timeouts.
    return this.systemClient.$transaction(
      async (tx) => {
        return callback(tx);
      },
      {
        maxWait: 10000, // 10 seconds to wait for a connection in the pool
        timeout: 20000, // 20 seconds max for the transaction itself
      },
    );
  }

  /**
   * Fetches a single record by id while RLS is bypassed (a system-level
   * lookup), then structurally re-checks that the fetched record's
   * companyId matches the caller's companyId before returning it.
   *
   * This replaces the "runAsSystem + manually recheck companyId" pattern
   * used at 15+ call sites in this codebase. That pattern is correct at
   * every site sampled during audit, but nothing enforces the recheck --
   * it's just a convention every call site has to remember to write, and
   * one missed recheck is a full tenant leak (fetch someone else's record
   * by guessing/enumerating an id). Using this helper instead makes the
   * recheck structurally unskippable: there is no code path here that
   * returns a record without it.
   *
   * Throws NotFoundException -- not ForbiddenException -- on both "no such
   * record" and "record exists but belongs to another company", on
   * purpose: a 403 would confirm to the caller that a record with that id
   * exists in some other tenant, which is itself a (small) information
   * leak. 404 for both cases tells an attacker nothing more than "you
   * don't have this".
   */
  async runAsTenantById<T extends { companyId: string | null }>(
    model: string,
    id: string,
    companyId: string,
  ): Promise<T> {
    if (!companyId) {
      throw new NotFoundException(`${model} not found.`);
    }

    const record = await this.runAsSystem<T | null>(
      `runAsTenantById: fetch ${model} ${id} for tenant-scope recheck (caller company ${companyId})`,
      async (tx) => {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const delegate = (tx as any)[model];
        if (!delegate || typeof delegate.findUnique !== 'function') {
          throw new Error(`runAsTenantById: unknown Prisma model "${model}".`);
        }
        return delegate.findUnique({ where: { id } });
      },
    );

    if (!record || record.companyId !== companyId) {
      throw new NotFoundException(`${model} not found.`);
    }

    return record;
  }

  /**
   * Framework-Level Optimistic Concurrency Control (OCC) Updater.
   * Eliminates the duplicate updateMany -> check count -> findFirst pattern.
   */
  async updateWithOcc<T>(
    tx: Omit<
      PrismaClient,
      '$connect' | '$disconnect' | '$on' | '$transaction' | '$use' | '$extends'
    >,
    modelName: string,
    id: string,
    existingUpdatedAt: Date,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    data: any,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    include?: any,
  ): Promise<T> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const model = (tx as any)[modelName];
    const updateResult = await model.updateMany({
      where: { id, updatedAt: existingUpdatedAt },
      data: { ...data, updatedAt: new Date() },
    });

    if (updateResult.count === 0) {
      throw new ConflictException(
        `${modelName} was modified by another process. Please refresh and try again.`,
      );
    }

    const configResult = await tx.$queryRaw<
      { current_company_id: string | null }[]
    >`SELECT current_setting('app.current_company_id', true) as current_company_id`;
    const companyId = configResult[0]?.current_company_id;

    const finalWhere: any = { id };
    if (companyId) {
      finalWhere.companyId = companyId;
    }

    const updatedEntity = await model.findFirst({
      where: finalWhere,
      include,
    });

    if (!updatedEntity) {
      throw new NotFoundException(`${modelName} not found after update.`);
    }

    return updatedEntity;
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { createPaginationResponse } from '../platform/api/utils/pagination.util';

@Injectable()
export class ProfitabilityService {
  constructor(private prisma: PrismaService) {}

  async tripPnl(companyId: string, tripId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findUnique({
        where: { id: tripId, companyId },
        select: {
          id: true,
          tripNumber: true,
          status: true,
          startDate: true,
          endDate: true,
          vehicleId: true,
          fuelExpenses: true,
          otherExpenses: true,
        },
      });

      if (!trip) {
        throw new NotFoundException(`Trip with ID ${tripId} not found`);
      }

      const firstLoad = await tx.load.findFirst({
        where: { tripId: trip.id, deletedAt: null },
        select: { originCity: true, destinationCity: true },
        orderBy: { createdAt: 'asc' },
      });

      const loadsAggr = await tx.load.aggregate({
        _sum: { rate: true },
        where: { tripId: trip.id, deletedAt: null },
      });
      const revenue = loadsAggr._sum.rate ?? 0;

      let fuel = 0;
      if (trip.vehicleId && trip.startDate) {
        const fuelAggr = await tx.fuelTransaction.aggregate({
          _sum: { totalCost: true },
          where: {
            vehicleId: trip.vehicleId,
            transactionTime: {
              gte: trip.startDate,
              ...(trip.endDate ? { lte: trip.endDate } : {}),
            },
          },
        });
        fuel = fuelAggr._sum.totalCost ?? trip.fuelExpenses ?? 0;
      } else {
        fuel = trip.fuelExpenses ?? 0;
      }

      const tollAggr = await tx.tollTransaction.aggregate({
        _sum: { amount: true },
        where: { tripId: trip.id },
      });
      const toll = tollAggr._sum.amount ?? 0;

      const expensesAggr = await tx.expense.aggregate({
        _sum: { amount: true },
        where: {
          tripId: trip.id,
          type: {
            notIn: [
              'FUEL',
              'TOLL',
              'DIESEL',
              'fuel',
              'toll',
              'diesel',
              'Fuel',
              'Toll',
              'Diesel',
            ],
          },
        },
      });
      const bhattaOther =
        (expensesAggr._sum.amount ?? 0) + (trip.otherExpenses ?? 0);

      const totalCost = fuel + toll + bhattaOther;
      const profit = revenue - totalCost;
      const marginPct =
        revenue > 0 ? Math.round((profit / revenue) * 1000) / 10 : 0;

      return {
        trip: {
          id: trip.id,
          number: trip.tripNumber,
          status: trip.status,
        },
        from: firstLoad?.originCity ?? null,
        to: firstLoad?.destinationCity ?? null,
        revenue,
        fuel,
        toll,
        bhattaOther,
        totalCost,
        profit,
        marginPct,
        profitable: profit >= 0,
      };
    });
  }

  async listTripPnl(companyId: string, page = 1, limit = 20) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const skip = (page - 1) * limit;

      const [trips, total] = await Promise.all([
        tx.trip.findMany({
          where: { companyId },
          skip,
          take: limit,
          select: {
            id: true,
            tripNumber: true,
            status: true,
            startDate: true,
            endDate: true,
            vehicleId: true,
            fuelExpenses: true,
            otherExpenses: true,
          },
        }),
        tx.trip.count({ where: { companyId } }),
      ]);

      const data = await Promise.all(
        trips.map(async (trip) => {
          const firstLoad = await tx.load.findFirst({
            where: { tripId: trip.id, deletedAt: null },
            select: { originCity: true, destinationCity: true },
            orderBy: { createdAt: 'asc' },
          });

          const loadsAggr = await tx.load.aggregate({
            _sum: { rate: true },
            where: { tripId: trip.id, deletedAt: null },
          });
          const revenue = loadsAggr._sum.rate ?? 0;

          let fuel = 0;
          if (trip.vehicleId && trip.startDate) {
            const fuelAggr = await tx.fuelTransaction.aggregate({
              _sum: { totalCost: true },
              where: {
                vehicleId: trip.vehicleId,
                transactionTime: {
                  gte: trip.startDate,
                  ...(trip.endDate ? { lte: trip.endDate } : {}),
                },
              },
            });
            fuel = fuelAggr._sum.totalCost ?? trip.fuelExpenses ?? 0;
          } else {
            fuel = trip.fuelExpenses ?? 0;
          }

          const tollAggr = await tx.tollTransaction.aggregate({
            _sum: { amount: true },
            where: { tripId: trip.id },
          });
          const toll = tollAggr._sum.amount ?? 0;

          const expensesAggr = await tx.expense.aggregate({
            _sum: { amount: true },
            where: {
              tripId: trip.id,
              type: {
                notIn: [
                  'FUEL',
                  'TOLL',
                  'DIESEL',
                  'fuel',
                  'toll',
                  'diesel',
                  'Fuel',
                  'Toll',
                  'Diesel',
                ],
              },
            },
          });
          const bhattaOther =
            (expensesAggr._sum.amount ?? 0) + (trip.otherExpenses ?? 0);

          const totalCost = fuel + toll + bhattaOther;
          const profit = revenue - totalCost;
          const marginPct =
            revenue > 0 ? Math.round((profit / revenue) * 1000) / 10 : 0;

          return {
            trip: {
              id: trip.id,
              number: trip.tripNumber,
              status: trip.status,
            },
            from: firstLoad?.originCity ?? null,
            to: firstLoad?.destinationCity ?? null,
            revenue,
            fuel,
            toll,
            bhattaOther,
            totalCost,
            profit,
            marginPct,
            profitable: profit >= 0,
          };
        }),
      );

      data.sort((a, b) => a.profit - b.profit);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async vehiclePnl(companyId: string, vehicleId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const vehicle = await tx.vehicle.findUnique({
        where: { id: vehicleId, companyId },
      });
      if (!vehicle) throw new NotFoundException('Vehicle not found');

      const trips = await tx.trip.findMany({
        where: { companyId, vehicleId },
        select: {
          id: true,
          startDate: true,
          endDate: true,
          fuelExpenses: true,
          otherExpenses: true,
        },
      });

      let totalRevenue = 0;
      let totalCost = 0;

      for (const trip of trips) {
        const loadsAggr = await tx.load.aggregate({
          _sum: { rate: true },
          where: { tripId: trip.id, deletedAt: null },
        });
        const revenue = loadsAggr._sum.rate ?? 0;
        totalRevenue += revenue;

        let fuel = 0;
        if (trip.startDate) {
          const fuelAggr = await tx.fuelTransaction.aggregate({
            _sum: { totalCost: true },
            where: {
              vehicleId,
              transactionTime: {
                gte: trip.startDate,
                ...(trip.endDate ? { lte: trip.endDate } : {}),
              },
            },
          });
          fuel = fuelAggr._sum.totalCost ?? trip.fuelExpenses ?? 0;
        } else {
          fuel = trip.fuelExpenses ?? 0;
        }

        const tollAggr = await tx.tollTransaction.aggregate({
          _sum: { amount: true },
          where: { tripId: trip.id },
        });
        const toll = tollAggr._sum.amount ?? 0;

        const expensesAggr = await tx.expense.aggregate({
          _sum: { amount: true },
          where: {
            tripId: trip.id,
            type: {
              notIn: [
                'FUEL',
                'TOLL',
                'DIESEL',
                'fuel',
                'toll',
                'diesel',
                'Fuel',
                'Toll',
                'Diesel',
              ],
            },
          },
        });
        const bhattaOther =
          (expensesAggr._sum.amount ?? 0) + (trip.otherExpenses ?? 0);

        totalCost += fuel + toll + bhattaOther;
      }

      const totalProfit = totalRevenue - totalCost;
      const avgMarginPct =
        totalRevenue > 0
          ? Math.round((totalProfit / totalRevenue) * 1000) / 10
          : 0;

      return {
        vehicleId,
        totalRevenue,
        totalCost,
        totalProfit,
        tripCount: trips.length,
        avgMarginPct,
      };
    });
  }

  async companySummary(companyId: string, from?: string, to?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Set bounds if none provided (e.g. 90 days default)
      let startDateBound = from ? new Date(from) : null;
      if (!startDateBound) {
        startDateBound = new Date();
        startDateBound.setDate(startDateBound.getDate() - 90);
      }
      const endDateBound = to ? new Date(to) : null;

      const whereClause: any = {
        companyId,
        startDate: { gte: startDateBound },
      };
      if (endDateBound) {
        whereClause.startDate.lte = endDateBound;
      }

      const trips = await tx.trip.findMany({
        where: whereClause,
        select: {
          id: true,
          tripNumber: true,
          startDate: true,
          endDate: true,
          vehicleId: true,
          fuelExpenses: true,
          otherExpenses: true,
        },
      });

      const tripIds = trips.map((t) => t.id);

      const [loadsRev, tollGroup, expGroup, firstLoads, fuelTxns] =
        await Promise.all([
          tx.load.groupBy({
            by: ['tripId'],
            _sum: { rate: true },
            where: { companyId, deletedAt: null, tripId: { in: tripIds } },
          }),
          tx.tollTransaction.groupBy({
            by: ['tripId'],
            _sum: { amount: true },
            where: { companyId, tripId: { in: tripIds } },
          }),
          tx.expense.groupBy({
            by: ['tripId'],
            _sum: { amount: true },
            where: {
              companyId,
              tripId: { in: tripIds },
              type: {
                notIn: [
                  'FUEL',
                  'TOLL',
                  'DIESEL',
                  'fuel',
                  'toll',
                  'diesel',
                  'Fuel',
                  'Toll',
                  'Diesel',
                ],
              },
            },
          }),
          tx.load.findMany({
            where: { companyId, deletedAt: null, tripId: { in: tripIds } },
            select: { tripId: true, originCity: true, destinationCity: true },
            orderBy: { createdAt: 'asc' },
          }),
          tx.fuelTransaction.findMany({
            where: { companyId, transactionTime: { gte: startDateBound } },
          }),
        ]);

      const revenueMap = new Map(
        loadsRev.map((l: any) => [
          l.tripId,
          l._sum.rate ? Number(l._sum.rate) : 0,
        ]),
      );
      const tollMap = new Map(
        tollGroup.map((t: any) => [
          t.tripId,
          t._sum.amount ? Number(t._sum.amount) : 0,
        ]),
      );
      const expMap = new Map(
        expGroup.map((e: any) => [
          e.tripId,
          e._sum.amount ? Number(e._sum.amount) : 0,
        ]),
      );

      const routeMap = new Map();
      for (const l of firstLoads) {
        if (!routeMap.has(l.tripId)) {
          routeMap.set(l.tripId, `${l.originCity}→${l.destinationCity}`);
        }
      }

      let totalRevenue = 0;
      let totalCost = 0;

      const vehicleStats: Record<
        string,
        { revenue: number; cost: number; profit: number }
      > = {};
      const laneStats: Record<
        string,
        { revenue: number; cost: number; profit: number }
      > = {};

      for (const trip of trips) {
        const revenue = revenueMap.get(trip.id) ?? 0;
        totalRevenue += revenue;

        let fuel = 0;
        if (trip.vehicleId && trip.startDate) {
          fuel = fuelTxns
            .filter(
              (f: any) =>
                f.vehicleId === trip.vehicleId &&
                f.transactionTime &&
                trip.startDate &&
                f.transactionTime >= trip.startDate &&
                (!trip.endDate || f.transactionTime <= trip.endDate),
            )
            .reduce((sum: number, f: any) => sum + Number(f.totalCost), 0);
        }
        if (fuel === 0 && trip.fuelExpenses) fuel = trip.fuelExpenses;

        const toll = tollMap.get(trip.id) ?? 0;
        const bhattaOther =
          (expMap.get(trip.id) ?? 0) + (trip.otherExpenses ?? 0);

        const tripCost = fuel + toll + bhattaOther;
        totalCost += tripCost;
        const tripProfit = revenue - tripCost;

        if (trip.vehicleId) {
          if (!vehicleStats[trip.vehicleId]) {
            vehicleStats[trip.vehicleId] = { revenue: 0, cost: 0, profit: 0 };
          }
          vehicleStats[trip.vehicleId].revenue += revenue;
          vehicleStats[trip.vehicleId].cost += tripCost;
          vehicleStats[trip.vehicleId].profit += tripProfit;
        }

        const lane = routeMap.get(trip.id);
        if (lane) {
          if (!laneStats[lane]) {
            laneStats[lane] = { revenue: 0, cost: 0, profit: 0 };
          }
          laneStats[lane].revenue += revenue;
          laneStats[lane].cost += tripCost;
          laneStats[lane].profit += tripProfit;
        }
      }

      const totalProfit = totalRevenue - totalCost;

      let bestTruck = null;
      let worstTruck = null;
      const vehicleEntries = Object.entries(vehicleStats).sort(
        (a, b) => b[1].profit - a[1].profit,
      );
      if (vehicleEntries.length > 0) {
        bestTruck = {
          vehicleId: vehicleEntries[0][0],
          profit: vehicleEntries[0][1].profit,
        };
        worstTruck = {
          vehicleId: vehicleEntries[vehicleEntries.length - 1][0],
          profit: vehicleEntries[vehicleEntries.length - 1][1].profit,
        };
      }

      let bestLane = null;
      let worstLane = null;
      const laneEntries = Object.entries(laneStats).sort(
        (a, b) => b[1].profit - a[1].profit,
      );
      if (laneEntries.length > 0) {
        bestLane = {
          lane: laneEntries[0][0],
          profit: laneEntries[0][1].profit,
        };
        worstLane = {
          lane: laneEntries[laneEntries.length - 1][0],
          profit: laneEntries[laneEntries.length - 1][1].profit,
        };
      }

      return {
        totalRevenue,
        totalCost,
        totalProfit,
        tripCount: trips.length,
        avgMarginPct:
          totalRevenue > 0
            ? Math.round((totalProfit / totalRevenue) * 1000) / 10
            : 0,
        bestTruck,
        worstTruck,
        bestLane,
        worstLane,
      };
    });
  }

  async aggregateVehicles(companyId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // For this step, we'll implement a simple snapshot aggregation
      // of all closed trips in the current month to feed TruckProfitability.
      // In a real production system, this would iterate over months and all expenses.

      const startOfMonth = new Date();
      startOfMonth.setDate(1);
      startOfMonth.setHours(0, 0, 0, 0);

      const trips = await tx.trip.findMany({
        where: {
          companyId,
          status: 'COMPLETED',
          endDate: { gte: startOfMonth },
        },
        select: {
          id: true,
          vehicleId: true,
          fuelExpenses: true,
          otherExpenses: true,
        },
      });

      const vehicleStats: Record<string, any> = {};

      for (const trip of trips) {
        if (!trip.vehicleId) continue;
        if (!vehicleStats[trip.vehicleId]) {
          vehicleStats[trip.vehicleId] = {
            revenue: 0,
            fuelCost: 0,
            tollCost: 0,
            maintCost: 0,
            driverCost: 0,
            otherCost: 0,
          };
        }

        const loadsAggr = await tx.load.aggregate({
          _sum: { rate: true },
          where: { tripId: trip.id, deletedAt: null },
        });
        vehicleStats[trip.vehicleId].revenue += loadsAggr._sum.rate ?? 0;

        const tollAggr = await tx.tollTransaction.aggregate({
          _sum: { amount: true },
          where: { tripId: trip.id },
        });
        vehicleStats[trip.vehicleId].tollCost += tollAggr._sum.amount ?? 0;

        vehicleStats[trip.vehicleId].fuelCost += trip.fuelExpenses ?? 0;

        // Driver cost (bhatta)
        const driverExpAggr = await tx.expense.aggregate({
          _sum: { amount: true },
          where: {
            tripId: trip.id,
            type: { in: ['BHATTA', 'DRIVER_ALLOWANCE', 'bhatta'] },
          },
        });
        vehicleStats[trip.vehicleId].driverCost +=
          driverExpAggr._sum.amount ?? 0;

        // Other cost
        const otherExpAggr = await tx.expense.aggregate({
          _sum: { amount: true },
          where: {
            tripId: trip.id,
            type: {
              notIn: [
                'FUEL',
                'TOLL',
                'DIESEL',
                'BHATTA',
                'DRIVER_ALLOWANCE',
                'bhatta',
              ],
            },
          },
        });
        vehicleStats[trip.vehicleId].otherCost +=
          (otherExpAggr._sum.amount ?? 0) + (trip.otherExpenses ?? 0);
      }

      for (const [vehicleId, stats] of Object.entries(vehicleStats)) {
        // We do not overwrite maintCost here since it is updated directly when Jobs are closed.
        const netProfit =
          stats.revenue -
          (stats.fuelCost +
            stats.tollCost +
            stats.driverCost +
            stats.otherCost);

        await tx.truckProfitability.upsert({
          where: {
            companyId_vehicleId_month: {
              companyId,
              vehicleId,
              month: startOfMonth,
            },
          },
          update: {
            revenue: stats.revenue,
            fuelCost: stats.fuelCost,
            tollCost: stats.tollCost,
            driverCost: stats.driverCost,
            otherCost: stats.otherCost,
            // netProfit is calculated by triggers or on-the-fly, but we'll store a baseline
            netProfit: netProfit,
          },
          create: {
            companyId,
            vehicleId,
            month: startOfMonth,
            revenue: stats.revenue,
            fuelCost: stats.fuelCost,
            tollCost: stats.tollCost,
            driverCost: stats.driverCost,
            otherCost: stats.otherCost,
            netProfit: netProfit,
            maintCost: 0,
          },
        });
      }

      return {
        success: true,
        aggregatedVehicles: Object.keys(vehicleStats).length,
      };
    });
  }

  async listVehiclePnl(companyId: string, from?: string, to?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Aggregate the TruckProfitability records
      const whereClause: any = { companyId };
      if (from || to) {
        whereClause.month = {};
        if (from) whereClause.month.gte = new Date(from);
        if (to) whereClause.month.lte = new Date(to);
      }

      const records = await tx.truckProfitability.findMany({
        where: whereClause,
        include: {
          vehicle: {
            select: { id: true, licensePlate: true, status: true, type: true },
          },
        },
      });

      // Group by vehicleId across all matching months
      const grouped: Record<string, any> = {};

      for (const r of records) {
        if (!grouped[r.vehicleId]) {
          grouped[r.vehicleId] = {
            vehicle: r.vehicle,
            revenue: 0,
            fuelCost: 0,
            tollCost: 0,
            maintCost: 0,
            driverCost: 0,
            otherCost: 0,
            netProfit: 0,
            distance: 0, // Mock distance for Rs/km
          };
        }
        grouped[r.vehicleId].revenue += r.revenue;
        grouped[r.vehicleId].fuelCost += r.fuelCost;
        grouped[r.vehicleId].tollCost += r.tollCost;
        grouped[r.vehicleId].maintCost += r.maintCost;
        grouped[r.vehicleId].driverCost += r.driverCost;
        grouped[r.vehicleId].otherCost += r.otherCost;

        // Re-calculate net profit accurately including maintCost
        grouped[r.vehicleId].netProfit +=
          r.revenue -
          (r.fuelCost + r.tollCost + r.driverCost + r.otherCost + r.maintCost);

        // Rough estimate of km driven for Rs/km metric
        grouped[r.vehicleId].distance += (r.fuelCost / 80) * 4; // Assume Rs 80/L and 4km/L
      }

      const results = Object.values(grouped).map((v: any) => {
        return {
          ...v,
          profitPerKm: v.distance > 0 ? v.netProfit / v.distance : 0,
          marginPct: v.revenue > 0 ? (v.netProfit / v.revenue) * 100 : 0,
        };
      });

      // Sort by netProfit descending
      results.sort((a, b) => b.netProfit - a.netProfit);

      return results;
    });
  }
}

import {
  Controller,
  Post,
  Get,
  Param,
  Body,
