      const mockTrip = { id: 'trip-1', loads: [] };
      mockTx.trip.findFirst.mockResolvedValue(mockTrip);
      mockTx.load.updateMany.mockResolvedValue({ count: 2 });
      mockTx.trip.findFirst
        .mockResolvedValueOnce(mockTrip)
        .mockResolvedValueOnce({
          ...mockTrip,
          loads: [{ id: 'load-1' }, { id: 'load-2' }],
        });

      mockTx.load.findMany.mockResolvedValue([
        { id: 'load-1' },
        { id: 'load-2' },
      ]);

      await service.assignLoads('company-1', 'trip-1', ['load-1', 'load-2']);
      expect(mockTx.$executeRaw).toHaveBeenCalled();
    });

    it('should throw NotFoundException if trip not found', async () => {
      mockTx.trip.findFirst.mockResolvedValue(null);
      mockTx.load.findMany.mockResolvedValue([{ id: 'load-1' }]);
      await expect(
        service.assignLoads('company-1', 'trip-999', ['load-1']),
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('remove', () => {
    it('should soft-delete trip, unassign loads, and set status to CANCELLED', async () => {
      const mockTrip = { id: 'trip-1', tripNumber: 'TRP-001' };
      mockTx.trip.findFirst.mockResolvedValue(mockTrip);
      mockTx.load.updateMany.mockResolvedValue({ count: 2 });
      mockTx.trip.update.mockResolvedValue({
        ...mockTrip,
        deletedAt: new Date(),
        status: 'CANCELLED',
      });

      const result = await service.remove('company-1', 'trip-1');

      expect(mockTx.load.updateMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({
            companyId: 'company-1',
            tripId: 'trip-1',
          }),
          data: { tripId: null, status: 'PENDING' },
        }),
      );
      expect(result.status).toBe('CANCELLED');
    });
  });
});

import { createDefaultTripDesks } from './trip-desks.util';
import { CreateLorryReceiptDto } from '../lorry-receipts/dto/create-lorry-receipt.dto';

import { AuditService } from '../platform/audit/audit.service';
import { Prisma, ReviewRole } from '@prisma/client';
import {
  getPaginationParams,
  createPaginationResponse,
} from '../platform/api/utils/pagination.util';
import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateTripDto } from './dto/create-trip.dto';
import { WorkflowService } from '../workflow/workflow.service';
import { UpdateTripDto } from './dto/update-trip.dto';
import { TripQueryDto } from './dto/trip-query.dto';
import { CreateTripReviewDto } from './dto/create-trip-review.dto';
import { EventEmitter2 } from '@nestjs/event-emitter';
import * as crypto from 'crypto';
import { EventStoreService } from '../platform/digital-twin/event-store.service';
import { IamPolicyEngineService } from '../platform/iam/iam-policy-engine.service';

@Injectable()
export class TripsService {
  constructor(
    private readonly auditService: AuditService,
    private prisma: PrismaService,
    private eventEmitter: EventEmitter2,
    private workflow: WorkflowService,
    private readonly eventStore: EventStoreService,
    private readonly iam: IamPolicyEngineService,
  ) {}

  async create(companyId: string, createTripDto: CreateTripDto) {
    const trip = await this.prisma.runAsTenant(companyId, async (tx) => {
      const data: any = { ...createTripDto, companyId };
      data.status = data.status ?? 'PLANNED';
      if (data.startDate) data.startDate = new Date(data.startDate);
      if (data.endDate) data.endDate = new Date(data.endDate);
      if (data.eta) data.eta = new Date(data.eta);

      if (!data.tripNumber) {
        data.tripNumber = `TRP-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
      } else {
        const existingTripNum = await tx.trip.findFirst({
          where: { tripNumber: data.tripNumber, companyId },
        });
        if (existingTripNum) {
          throw new ConflictException(
            `Trip number ${data.tripNumber} already exists.`,
          );
        }
      }

      // 1. Lock and Verify Driver OCC
      if (data.driverId) {
        const driver = await tx.driver.findFirst({
          where: { id: data.driverId, companyId },
        });
        if (!driver || driver.status !== 'AVAILABLE') {
          throw new ConflictException(`Driver is not available for assignment`);
        }
        await this.prisma.updateWithOcc(
          tx,
          'driver',
          driver.id,
          driver.updatedAt,
          { status: 'DISPATCHED' },
        );
      }

      // 2. Lock and Verify Vehicle OCC
      if (data.vehicleId) {
        const vehicle = await tx.vehicle.findFirst({
          where: { id: data.vehicleId, companyId },
        });
        if (!vehicle || vehicle.status !== 'IN_SERVICE') {
          throw new ConflictException(
            `Vehicle is not available for assignment`,
          );
        }
        await this.prisma.updateWithOcc(
          tx,
          'vehicle',
          vehicle.id,
          vehicle.updatedAt,
          { status: 'DISPATCHED' },
        );
      }

      // 3. Lock and Verify Trailer OCC
      if (data.trailerId) {
        const trailer = await tx.vehicle.findFirst({
          where: { id: data.trailerId, companyId, type: 'TRAILER' },
        });
        if (!trailer || trailer.status !== 'IN_SERVICE') {
          throw new ConflictException(
            `Trailer is not available for assignment`,
          );
        }
        await this.prisma.updateWithOcc(
          tx,
          'vehicle',
          trailer.id,
          trailer.updatedAt,
          { status: 'DISPATCHED' },
        );
      }

      const trip = await tx.trip.create({
        data,
        include: { driver: true, vehicle: true, trailer: true, loads: true },
      });

      // Auto-create the 5 mandatory TripDesks
      await createDefaultTripDesks(tx, companyId, trip.id);

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'TRIP',
        trigger: 'TRIP_CREATED',
        entityData: trip,
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Trip creation rejected by business rules.',
        );
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: trip.id,
          action: 'CREATE',
          details: { tripNumber: trip.tripNumber, status: trip.status },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'TRIP',
        streamId: trip.id,
        eventType: 'TripCreated',
        payload: { ...trip },
      });

      return trip;
    });

    this.eventEmitter.emit('trip.created', {
      companyId,
      tripId: trip.id,
      tripNumber: trip.tripNumber,
      status: trip.status,
    });

    return trip;
  }

  async generateLorryReceipt(
    companyId: string,
    tripId: string,
    dto: CreateLorryReceiptDto,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findFirst({
        where: { id: tripId, companyId },
        select: { vehicleId: true, driverId: true, lorryReceipt: true },
      });
      if (!trip) throw new NotFoundException('Trip not found');
      if (!trip.vehicleId || !trip.driverId) {
        throw new BadRequestException(
          'Trip must have an assigned vehicle and driver to generate LR',
        );
      }
      if (trip.lorryReceipt) {
        throw new ConflictException(
          'Lorry Receipt already exists for this trip',
        );
      }

      const lrNumber = `LR-${Date.now().toString().slice(-6)}-${crypto.randomBytes(2).toString('hex').toUpperCase()}`;

      const lr = await tx.lorryReceipt.create({
        data: {
          companyId,
          lrNumber,
          tripId,
          vehicleId: trip.vehicleId,
          driverId: trip.driverId,
          consignorName: dto.consignorName,
          consigneeName: dto.consigneeName,
          product: dto.product,
          grossWeight: dto.grossWeight,
          tareWeight: dto.tareWeight,
          netWeight: dto.netWeight,
          gstNo: dto.gstNo,
          gateInTime: dto.gateInTime ? new Date(dto.gateInTime) : null,
          gateOutTime: dto.gateOutTime ? new Date(dto.gateOutTime) : null,
        },
      });
      return lr;
    });
  }

  async findAll(companyId: string, query: TripQueryDto) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const {
        page = 1,
        limit = 10,
        search,
        status,
        driverId,
        vehicleId,
      } = query;
      const { skip, take } = getPaginationParams(page, limit);

      const where: Prisma.TripWhereInput = { companyId };

      if (search) {
        where.OR = [
          { tripNumber: { contains: search, mode: 'insensitive' } },
          { driver: { firstName: { contains: search, mode: 'insensitive' } } },
          { driver: { lastName: { contains: search, mode: 'insensitive' } } },
          {
            vehicle: {
              licensePlate: { contains: search, mode: 'insensitive' },
            },
          },
        ];
      }

      if (status) where.status = status;
      if (driverId) where.driverId = driverId;
      if (vehicleId) where.vehicleId = vehicleId;

      const [data, total] = await Promise.all([
        tx.trip.findMany({
          where,
          skip,
          take,
          orderBy: { createdAt: 'desc' },
          include: {
            driver: true,
            vehicle: true,
            trailer: true,
            loads: { include: { customer: true } },
          },
        }),
        tx.trip.count({ where }),
      ]);

      return createPaginationResponse(data, total, page, limit);
    });
  }

  async findOne(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findFirst({
        where: { id, companyId },
        include: {
          driver: true,
          vehicle: true,
          trailer: true,
          loads: {
            select: {
              id: true,
              originCity: true,
              destinationCity: true,
              createdAt: true,
            },
            orderBy: { createdAt: 'asc' },
          },
          tripReviews: true,
        },
      });

      if (!trip) {
        throw new NotFoundException(`Trip with ID ${id} not found`);
      }
      return trip;
    });
  }

  async update(companyId: string, id: string, updateTripDto: UpdateTripDto) {
    const result = await this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id, companyId },
      });
      if (!existingTrip) throw new NotFoundException();

      const data: any = { ...updateTripDto };
      if (data.startDate) data.startDate = new Date(data.startDate);
      if (data.endDate) data.endDate = new Date(data.endDate);
      if (data.eta) data.eta = new Date(data.eta);

      if (data.tripNumber && data.tripNumber !== existingTrip.tripNumber) {
        const duplicate = await tx.trip.findFirst({
          where: { tripNumber: data.tripNumber, companyId },
        });
        if (duplicate) {
          throw new ConflictException(
            `Trip number ${data.tripNumber} already exists.`,
          );
        }
      }

      // 1. Resource Reassignment - Driver
      if (data.driverId && data.driverId !== existingTrip.driverId) {
        const newDriver = await tx.driver.findFirst({
          where: { id: data.driverId, companyId },
        });
        if (!newDriver || newDriver.status !== 'AVAILABLE') {
          throw new ConflictException(
            'New driver is not available for assignment',
          );
        }
        await this.prisma.updateWithOcc(
          tx,
          'driver',
          newDriver.id,
          newDriver.updatedAt,
          { status: 'DISPATCHED' },
        );
        if (existingTrip.driverId) {
          await tx.driver.updateMany({
            where: { id: existingTrip.driverId, companyId },
            data: { status: 'AVAILABLE' },
          });
        }
      }

      // 2. Resource Reassignment - Vehicle
      if (data.vehicleId && data.vehicleId !== existingTrip.vehicleId) {
        const newVehicle = await tx.vehicle.findFirst({
          where: { id: data.vehicleId, companyId },
        });
        if (!newVehicle || newVehicle.status !== 'IN_SERVICE') {
          throw new ConflictException(
            'New vehicle is not available for assignment',
          );
        }
        await this.prisma.updateWithOcc(
          tx,
          'vehicle',
          newVehicle.id,
          newVehicle.updatedAt,
          { status: 'DISPATCHED' },
        );
        if (existingTrip.vehicleId) {
          await tx.vehicle.updateMany({
            where: { id: existingTrip.vehicleId, companyId },
            data: { status: 'IN_SERVICE' },
          });
        }
      }

      // 3. Resource Reassignment - Trailer
      if (data.trailerId && data.trailerId !== existingTrip.trailerId) {
        const newTrailer = await tx.vehicle.findFirst({
          where: { id: data.trailerId, companyId, type: 'TRAILER' },
        });
        if (!newTrailer || newTrailer.status !== 'IN_SERVICE') {
          throw new ConflictException(
            'New trailer is not available for assignment',
          );
        }
        await this.prisma.updateWithOcc(
          tx,
          'vehicle',
          newTrailer.id,
          newTrailer.updatedAt,
          { status: 'DISPATCHED' },
        );
        if (existingTrip.trailerId) {
          await tx.vehicle.updateMany({
            where: { id: existingTrip.trailerId, companyId },
            data: { status: 'IN_SERVICE' },
          });
        }
      }

      // Prevent backwards state transitions
      if (
        (existingTrip.status === 'COMPLETED' ||
          existingTrip.status === 'CANCELLED') &&
        data.status &&
        data.status !== existingTrip.status
      ) {
        throw new BadRequestException(
          `Cannot change status of a ${existingTrip.status} trip`,
        );
      }

      // Free up resources when trip is COMPLETED or CANCELLED
      if (
        data.status &&
        (data.status === 'COMPLETED' || data.status === 'CANCELLED') &&
        existingTrip.status !== 'COMPLETED' &&
        existingTrip.status !== 'CANCELLED'
      ) {
        if (existingTrip.driverId) {
          await tx.driver.updateMany({
            where: { id: existingTrip.driverId, companyId },
            data: { status: 'AVAILABLE' },
          });
        }
        if (existingTrip.vehicleId) {
          await tx.vehicle.updateMany({
            where: { id: existingTrip.vehicleId, companyId },
            data: { status: 'IN_SERVICE' },
          });
        }
        if (existingTrip.trailerId) {
          await tx.vehicle.updateMany({
            where: { id: existingTrip.trailerId, companyId },
            data: { status: 'IN_SERVICE' },
          });
        }

        if (data.status === 'CANCELLED') {
          // Unassign loads when trip is cancelled
          await tx.load.updateMany({
            where: { tripId: id, companyId },
            data: { tripId: null, status: 'PENDING' },
          });
        }
      }

      const updatedTrip = await this.prisma.updateWithOcc<any>(
        tx,
        'trip',
        id,
        existingTrip.updatedAt,
        data,
        { driver: true, vehicle: true, trailer: true, loads: true },
      );

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: updatedTrip.id,
          action: 'UPDATE',
          beforeValue: { status: existingTrip.status },
          afterValue: { status: updatedTrip.status },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'TRIP',
        streamId: updatedTrip.id,
        eventType: 'TripUpdated',
        payload: data,
      });

      return { updatedTrip, existingStatus: existingTrip.status };
    });

    if (
      result.existingStatus !== 'IN_TRANSIT' &&
      result.updatedTrip.status === 'IN_TRANSIT'
    ) {
      this.eventEmitter.emit('trip.started', result.updatedTrip);
    } else if (
      result.existingStatus !== 'COMPLETED' &&
      result.updatedTrip.status === 'COMPLETED'
    ) {
      this.eventEmitter.emit('trip.completed', result.updatedTrip);
    } else {
      this.eventEmitter.emit('trip.updated', result.updatedTrip);
    }

    return result.updatedTrip;
  }

  async assignLoads(companyId: string, id: string, loadIds: string[]) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id, companyId },
      });
      if (!existingTrip) throw new NotFoundException();

      // Rule Engine Integration
      const ruleResult = await this.workflow.evaluateRules(companyId, {
        entityType: 'TRIP',
        trigger: 'ASSIGN_LOADS',
        entityData: { trip: existingTrip, loadIds },
      });

      if (ruleResult.triggeredActions.some((a) => a.actionType === 'REJECT')) {
        throw new BadRequestException(
          'Load assignment rejected by business rules.',
        );
      }

      // Verify that all loads are unassigned before assigning them
      const availableLoads = await tx.load.findMany({
        where: {
          id: { in: loadIds },
          companyId,
          tripId: null,
          status: 'PENDING',
        },
      });

      if (availableLoads.length !== loadIds.length) {
        throw new ConflictException(
          'One or more loads are already assigned to another trip or do not exist.',
        );
      }

      // Assign tripId to each load atomically using raw SQL to guarantee row-level lock check
      const rowCount = await tx.$executeRaw`
        UPDATE "Load" 
        SET "tripId" = ${id}::uuid, status = 'ASSIGNED' 
        WHERE id::text IN (${Prisma.join(loadIds)}) 
          AND "companyId"::text = ${companyId} 
          AND "tripId" IS NULL 
          AND status = 'PENDING'
      `;

      if (rowCount !== loadIds.length) {
        throw new ConflictException(
          'One or more loads were already assigned by a concurrent request.',
        );
      }

      const updatedTrip = await tx.trip.findFirst({
        where: { id, companyId },
        include: { loads: true },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: id,
          action: 'ASSIGN_LOADS',
          details: { loadIds },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'TRIP',
        streamId: id,
        eventType: 'LoadsAssigned',
        payload: { loadIds },
      });

      return updatedTrip;
    });
  }

  async remove(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id, companyId },
      });
      if (!existingTrip) throw new NotFoundException();

      if (
        existingTrip.status === 'COMPLETED' ||
        existingTrip.status === 'CANCELLED'
      ) {
        throw new BadRequestException(
          `Cannot delete a trip that is already ${existingTrip.status}`,
        );
      }

      // Unassign loads when trip is cancelled/removed
      await tx.load.updateMany({
        where: { tripId: id, companyId },
        data: { tripId: null, status: 'PENDING' },
      });

      // Free up resources
      if (existingTrip.driverId) {
        await tx.driver.updateMany({
          where: { id: existingTrip.driverId, companyId },
          data: { status: 'AVAILABLE' },
        });
      }
      if (existingTrip.vehicleId) {
        await tx.vehicle.updateMany({
          where: { id: existingTrip.vehicleId, companyId },
          data: { status: 'IN_SERVICE' },
        });
      }
      if (existingTrip.trailerId) {
        await tx.vehicle.updateMany({
          where: { id: existingTrip.trailerId, companyId },
          data: { status: 'IN_SERVICE' },
        });
      }

      const deletedTrip = await tx.trip.update({
        where: { id, companyId },
        data: { deletedAt: new Date(), status: 'CANCELLED' },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: deletedTrip.id,
          action: 'DELETE',
          details: { tripNumber: deletedTrip.tripNumber },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'TRIP',
        streamId: deletedTrip.id,
        eventType: 'TripCancelled',
        payload: {},
      });

      return deletedTrip;
    });
  }

  async closeTrip(companyId: string, id: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const existingTrip = await tx.trip.findFirst({
        where: { id, companyId },
        include: { TripDesk: true },
      });
      if (!existingTrip) throw new NotFoundException('Trip not found');

      if (existingTrip.status === 'COMPLETED') {
        throw new BadRequestException('Trip is already completed');
      }

      const pendingDesks =
        existingTrip.TripDesk?.filter((d) => d.status === 'PENDING') || [];
      if (pendingDesks.length > 0) {
        const deskNames = pendingDesks.map((d) => d.desk).join(', ');
        throw new BadRequestException(
          `Cannot close trip. Pending desks: ${deskNames}`,
        );
      }

      const updatedTrip = await tx.trip.update({
        where: { id, companyId },
        data: { status: 'COMPLETED', endDate: new Date() },
      });

      // Free up resources
      if (updatedTrip.driverId) {
        await tx.driver.updateMany({
          where: { id: updatedTrip.driverId, companyId },
          data: { status: 'AVAILABLE' },
        });
      }
      if (updatedTrip.vehicleId) {
        await tx.vehicle.updateMany({
          where: { id: updatedTrip.vehicleId, companyId },
          data: { status: 'IN_SERVICE' },
        });
      }
      if (updatedTrip.trailerId) {
        await tx.vehicle.updateMany({
          where: { id: updatedTrip.trailerId, companyId },
          data: { status: 'IN_SERVICE' },
        });
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Trip',
          entityType: 'Trip',
          entityId: id,
          action: 'UPDATE',
          details: { status: 'COMPLETED' },
          source: 'API',
        },
        null,
        tx,
      );

      return updatedTrip;
    });
  }

  async submitDriverScore(
    companyId: string,
    id: string,
    data: {
      onTime: boolean;
      podUploaded: boolean;
      fuelScore: number;
      damageScore: number;
      behaviourScore: number;
    },
    ratedBy: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findFirst({ where: { id, companyId } });
      if (!trip) throw new NotFoundException('Trip not found');
      if (!trip.driverId)
        throw new BadRequestException('Trip has no driver assigned');

      // Calculate weighted total (0-100)
      // onTime (20), podUploaded (10), fuelScore (30), damageScore (20), behaviourScore (20)
      const onTimeVal = data.onTime ? 20 : 0;
      const podVal = data.podUploaded ? 10 : 0;
      // Convert fuel/damage/behaviour out of 10 or 100 to the weight
      // Assume inputs are 0-100 scales for fuel, damage, behaviour
      const fuelVal = (Math.max(0, Math.min(100, data.fuelScore)) / 100) * 30;
      const damageVal =
        (Math.max(0, Math.min(100, data.damageScore)) / 100) * 20;
      const behaviourVal =
        (Math.max(0, Math.min(100, data.behaviourScore)) / 100) * 20;

      const total = onTimeVal + podVal + fuelVal + damageVal + behaviourVal;

      return tx.driverScore.create({
        data: {
          companyId,
          driverId: trip.driverId,
          tripId: trip.id,
          onTime: data.onTime,
          podUploaded: data.podUploaded,
          // @ts-ignore
          fuelScore: data.fuelScore,
          damageScore: data.damageScore,
          behaviourScore: data.behaviourScore,
          total,
          ratedBy,
          ratedAt: new Date(),
        },
      });
    });
  }
  async getTripReviews(companyId: string, tripId: string) {
    return this.prisma.tripReview.findMany({
      where: { companyId, tripId },
      orderBy: { createdAt: 'asc' },
    });
  }

  async submitReview(
    companyId: string,
    tripId: string,
    reviewerId: string,
    dto: CreateTripReviewDto,
  ) {
    // 1. Role-based RBAC Enforcements
    let requiredPermission = 'trips:update';
    if (dto.reviewerRole === ReviewRole.DISPATCHER)
      requiredPermission = 'dispatch:manage';
    if (dto.reviewerRole === ReviewRole.FLEET_MANAGER)
      requiredPermission = 'fleet:write';
    if (dto.reviewerRole === ReviewRole.WORKSHOP_MECHANIC)
      requiredPermission = 'workshop:mechanic';
    if (dto.reviewerRole === ReviewRole.GATE_SECURITY)
      requiredPermission = 'workshop:gate';
    if (dto.reviewerRole === ReviewRole.CUSTOMER_CONTACT)
      requiredPermission = 'admin:manage'; // Customer fallback to admin

    const [resource, action] = requiredPermission.split(':');

    const userRecord = await this.prisma.runAsTenant(companyId, (tx) =>
      tx.user.findFirst({
        where: { id: reviewerId, companyId },
        select: { roleId: true },
      }),
    );

    if (!userRecord) {
      throw new ForbiddenException('User not found in tenant context');
    }

    const auth = await this.iam.authorize({
      userId: reviewerId,
      companyId,
      roleId: userRecord.roleId,
      resource,
      action,
    });

    if (!auth.granted) {
      throw new ForbiddenException(
        `You do not have the ${requiredPermission} permission required to submit a ${dto.reviewerRole} review.`,
      );
    }

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const trip = await tx.trip.findFirst({
        where: { id: tripId, companyId },
      });
      if (!trip) throw new NotFoundException('Trip not found');
      if (!trip.driverId)
        throw new BadRequestException('Trip has no driver assigned');
      if (trip.status !== 'COMPLETED')
        throw new BadRequestException(
          'Reviews can only be submitted after the trip is COMPLETED.',
        );

      const existing = await tx.tripReview.findFirst({
        where: { tripId: tripId, reviewerRole: dto.reviewerRole },
      });
      if (existing)
        throw new ConflictException(
          `Review for role ${dto.reviewerRole} already exists`,
        );

      const review = await tx.tripReview.create({
        data: {
          companyId,
          tripId: tripId,
          reviewerId,
          reviewerRole: dto.reviewerRole,
          rating: dto.rating,
          comment: dto.comment,
        },
      });

      const allReviews = await tx.tripReview.findMany({
        where: { tripId: tripId },
      });

      if (allReviews.length === 5) {
        // Calculate mileage efficiency (actual distance / fuel used)
        const distance = trip.actualDistance || trip.estimatedDistance || 0;
        const fuel = trip.fuelExpenses || 0;
        let mileageScore = 5.0; // Default if no fuel data

        if (fuel > 0 && distance > 0) {
          const actualKmL = distance / fuel;
          const EXPECTED_KM_LITER = 5.0;
          // Max 5 points, Min 1 point
          mileageScore = Math.min(
            5,
            Math.max(1, (actualKmL / EXPECTED_KM_LITER) * 5),
          );
        }

        const scores: any = {
          dispatcherScore:
            allReviews.find((r) => r.reviewerRole === ReviewRole.DISPATCHER)
              ?.rating || 0,
          fleetManagerScore:
            allReviews.find((r) => r.reviewerRole === ReviewRole.FLEET_MANAGER)
              ?.rating || 0,
          workshopScore:
            allReviews.find(
              (r) => r.reviewerRole === ReviewRole.WORKSHOP_MECHANIC,
            )?.rating || 0,
          securityScore:
            allReviews.find((r) => r.reviewerRole === ReviewRole.GATE_SECURITY)
              ?.rating || 0,
          customerScore:
            allReviews.find(
              (r) => r.reviewerRole === ReviewRole.CUSTOMER_CONTACT,
            )?.rating || 0,
          mileageScore,
        };

        const avgRoleScore =
          (scores.dispatcherScore +
            scores.fleetManagerScore +
            scores.workshopScore +
            scores.securityScore +
            scores.customerScore) /
          5;
        // Total score factors in the mileage score (e.g. 70% role, 30% mileage)
        const total = avgRoleScore * 0.7 + mileageScore * 0.3;

        await tx.driverScore.create({
          data: {
            companyId,
            driverId: trip.driverId,
            tripId: trip.id,
            ...scores,
            total,
            ratedBy: 'SYSTEM_AGGREGATE',
            ratedAt: new Date(),
          },
        });

        // Update the driver's overall running average score
        const driverScores = await tx.driverScore.findMany({
          where: { driverId: trip.driverId },
        });
        const runningTotal =
          driverScores.reduce((sum, ds) => sum + ds.total, 0) /
          driverScores.length;

        await tx.driver.update({
          where: { id: trip.driverId },
          data: { overallScore: runningTotal },
        });

        this.eventEmitter.emit('driver.score.updated', {
          companyId,
          driverId: trip.driverId,
          tripId: trip.id,
          score: runningTotal,
        });
      }

      return review;
    });
  }
}

