import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { AuditService } from '../../platform/audit/audit.service';

@Injectable()
export class ComplianceService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly auditService: AuditService,
  ) {}

  async logHosViolation(companyId: string, data: any, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const violation = await tx.hosViolation.create({
        data: {
          companyId,
          driverId: data.driverId,
          rule: data.rule,
          violationTime: data.violationTime,
          durationMinutes: data.durationMinutes,
          severity: data.severity,
          status: 'OPEN',
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Compliance',
          entityType: 'HosViolation',
          entityId: violation.id,
          action: 'CREATE',
          details: { driverId: data.driverId, rule: data.rule },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamId: data.driverId,
        streamType: 'DRIVER',
        eventType: 'HosViolationLogged',
        payload: {
          rule: data.rule,
          severity: data.severity,
          violationTime: data.violationTime,
        },
        userId,
      });

      return violation;
    });
  }

  async getHosViolations(companyId: string, driverId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (driverId) where.driverId = driverId;
      return tx.hosViolation.findMany({
        where,
        orderBy: { violationTime: 'desc' },
      });
    });
  }

  async submitDvir(companyId: string, data: any, userId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const dvir = await tx.dvirLog.create({
        data: {
          companyId,
          vehicleId: data.vehicleId,
          driverId: data.driverId,
          type: data.type,
          status: data.status,
          defects: data.defects || [],
          inspectorName: data.inspectorName,
          signature: data.signature,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Compliance',
          entityType: 'DvirLog',
          entityId: dvir.id,
          action: 'CREATE',
          details: {
            vehicleId: data.vehicleId,
            driverId: data.driverId,
            status: data.status,
          },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamId: dvir.id,
        streamType: 'COMPLIANCE',
        eventType: 'DvirSubmitted',
        payload: {
          vehicleId: data.vehicleId,
          driverId: data.driverId,
          status: data.status,
        },
        userId,
      });

      if (data.status === 'UNSAFE' || data.status === 'NEEDS_REPAIR') {
        // Tag vehicle status
        await tx.vehicle.update({
          where: { id: data.vehicleId },
          data: { status: 'MAINTENANCE_DUE' },
        });

        await this.eventStore.append({
          tenantId: companyId,
          streamId: data.vehicleId,
          streamType: 'VEHICLE',
          eventType: 'VehicleFlaggedForRepair',
          payload: { reason: 'DVIR_DEFECTS', defects: data.defects },
          userId,
        });
      }

      return dvir;
    });
  }

  async getDvirLogs(companyId: string, vehicleId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (vehicleId) where.vehicleId = vehicleId;
      return tx.dvirLog.findMany({ where, orderBy: { createdAt: 'desc' } });
    });
  }

  async registerVehicle(
    companyId: string,
    vehicleId: string,
    data: any,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const reg = await tx.vehicleRegistration.upsert({
        where: { vehicleId },
        update: {
          state: data.state,
          plateNumber: data.plateNumber,
          issueDate: data.issueDate,
          expiryDate: data.expiryDate,
          documentUrl: data.documentUrl,
        },
        create: {
          companyId,
          vehicleId,
          state: data.state,
          plateNumber: data.plateNumber,
          issueDate: data.issueDate,
          expiryDate: data.expiryDate,
          documentUrl: data.documentUrl,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Compliance',
          entityType: 'VehicleRegistration',
          entityId: reg.id,
          action: 'UPSERT',
          details: { vehicleId, plateNumber: data.plateNumber },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamId: vehicleId,
        streamType: 'VEHICLE',
        eventType: 'VehicleRegistered',
        payload: {
          state: data.state,
          plateNumber: data.plateNumber,
          expiryDate: data.expiryDate,
        },
        userId,
      });

      return reg;
    });
  }

  async logInsurance(
    companyId: string,
    vehicleId: string,
    data: any,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const ins = await tx.insuranceLog.create({
        data: {
          companyId,
          vehicleId,
          provider: data.provider,
          policyNumber: data.policyNumber,
          coverageType: data.coverageType,
          premiumAmount: data.premiumAmount,
          issueDate: data.issueDate,
          expiryDate: data.expiryDate,
          documentUrl: data.documentUrl,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Compliance',
          entityType: 'InsuranceLog',
          entityId: ins.id,
          action: 'CREATE',
          details: {
            vehicleId,
            provider: data.provider,
            policyNumber: data.policyNumber,
          },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamId: vehicleId,
        streamType: 'VEHICLE',
        eventType: 'VehicleInsuranceLogged',
        payload: {
          provider: data.provider,
          policyNumber: data.policyNumber,
          expiryDate: data.expiryDate,
        },
        userId,
      });

      return ins;
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

@Injectable()
export class ComplianceEngine {
  private readonly logger = new Logger(ComplianceEngine.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  /**
   * Evaluates document expiry for Fleet Assets (Vehicles/Drivers).
   */
  async evaluateDocumentCompliance(
    companyId: string,
    assetType: 'VEHICLE' | 'DRIVER',
    assetId: string,
    documents: any[],
  ) {
    this.logger.log(`Evaluating compliance for ${assetType} ${assetId}`);

    const now = new Date();
    const expiryThreshold = new Date();
    expiryThreshold.setDate(now.getDate() + 30); // Alert 30 days prior

    let isCompliant = true;
    let criticalExpiry = false;

    for (const doc of documents) {
      if (doc.expiryDate) {
        const expiry = new Date(doc.expiryDate);

        if (expiry < now) {
          isCompliant = false;
          criticalExpiry = true;
          this.logger.error(
            `Critical Compliance Failure: ${doc.type} expired on ${assetType} ${assetId}`,
          );

          await this.eventStore.append({
            tenantId: companyId,
            streamId: assetId,
            streamType: assetType,
            eventType: 'DocumentExpired',
            payload: { type: doc.type, expiry: doc.expiryDate },
            userId: 'SYSTEM',
          });
        } else if (expiry < expiryThreshold) {
          // Warning threshold
          this.logger.warn(
            `Compliance Warning: ${doc.type} expiring soon on ${assetType} ${assetId}`,
          );

          await this.eventStore.append({
            tenantId: companyId,
            streamId: assetId,
            streamType: assetType,
            eventType: 'DocumentExpiring',
            payload: { type: doc.type, expiry: doc.expiryDate },
            userId: 'SYSTEM',
          });
        }
      }
    }

    // Auto-block asset if critically non-compliant
    if (criticalExpiry) {
      try {
        const model = (this.prisma as any)[assetType.toLowerCase()];
        const asset = await model.findUnique({
          where: { id: assetId },
          select: { status: true },
        });

        if (asset && asset.status === 'ACTIVE') {
          await this.lifecycle.transitionState({
            companyId,
            entityType: assetType === 'VEHICLE' ? 'Vehicle' : 'Driver',
            entityId: assetId,
            fromState: asset.status,
            toState: 'BLOCKED',
            userId: 'SYSTEM',
            reason: 'Auto-blocked due to expired critical compliance documents',
          });
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        this.logger.error(
          `Failed to auto-block non-compliant asset: ${errorMessage}`,
        );
      }
    }

    return isCompliant;
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import {
  IAnalyticsProvider,
  AnalyticsRegistryService,
} from '../../platform/analytics/analytics-registry.service';

export interface FleetAnalyticsResult {
  fleetUtilizationPercentage: number;
  downtimeHours: number;
  maintenanceCost: number;
  fuelEfficiencyKmpl: number;
  costPerKm: number;
  breakdownFrequency: number;
  vehicleAvailabilityPercentage: number;
}

@Injectable()
export class FleetAnalyticsService implements OnModuleInit, IAnalyticsProvider {
  private readonly logger = new Logger(FleetAnalyticsService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly analyticsRegistry: AnalyticsRegistryService,
  ) {}

  onModuleInit() {
    this.analyticsRegistry.register(this);
  }

  getDomainName(): string {
    return 'fleet';
  }

  async getAnalytics(companyId: string, timeframe: string): Promise<any> {
    return this.getVehicleAnalytics(companyId, timeframe, 1);
  }

  /**
   * Generates comprehensive asset ROI and performance analytics.
   */
  async getVehicleAnalytics(
    companyId: string,
    vehicleId: string,
    periodDays = 30,
  ): Promise<FleetAnalyticsResult | null> {
    this.logger.log(
      `Calculating Fleet Analytics for Vehicle ${vehicleId} over ${periodDays} days`,
    );

    return this.prisma.runAsTenant(companyId, async (tx) => {
      // Mock metrics generation. In a real system, these would aggregate `EventStore` streams
      // or `Trip` / `Expense` / `Maintenance` records over the requested period.

      const vehicle = await tx.vehicle.findUnique({ where: { id: vehicleId } });
      if (!vehicle) return null;

      // Mock aggregation logic to satisfy the Enterprise requirements
      const totalPossibleHours = periodDays * 24;

      // Assume 2 breakdowns per month on average
      const breakdowns = 2;
      const downtimeHours = breakdowns * 48; // 48 hrs per breakdown

      // Maintenance & Fuel Costs
      const maintenanceCost = 1500; // Mock $1500
      const totalFuelVolume = 500; // Liters/Gallons
      const totalDistance = 2500; // KM/Miles
      const fuelCost = totalFuelVolume * 1.1;
      const driverCost = totalDistance * 1.5;

      const totalCost = maintenanceCost + fuelCost + driverCost;

      // Derived Metrics
      const fuelEfficiencyKmpl = totalDistance / (totalFuelVolume || 1);
      const costPerKm = totalCost / (totalDistance || 1);
      const availabilityPercentage =
        ((totalPossibleHours - downtimeHours) / totalPossibleHours) * 100;

      // Simulated Utilization (hours driven / available hours)
      const drivingHours = totalDistance / 50; // assuming avg 50 km/h
      const fleetUtilizationPercentage =
        (drivingHours / (totalPossibleHours - downtimeHours)) * 100;

      return {
        fleetUtilizationPercentage: parseFloat(
          fleetUtilizationPercentage.toFixed(2),
        ),
        downtimeHours,
        maintenanceCost,
        fuelEfficiencyKmpl: parseFloat(fuelEfficiencyKmpl.toFixed(2)),
        costPerKm: parseFloat(costPerKm.toFixed(2)),
        breakdownFrequency: breakdowns,
        vehicleAvailabilityPercentage: parseFloat(
          availabilityPercentage.toFixed(2),
        ),
      };
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../../prisma/prisma.service';
import { MaintenanceEngine } from './maintenance.engine';
import { ComplianceEngine } from './compliance.engine';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

/**
 * Enterprise Fleet Management System Orchestrator.
 * Connects operational events (Dispatch) to Asset Management workflows.
 */
@Injectable()
export class FleetOrchestratorService {
  private readonly logger = new Logger(FleetOrchestratorService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly maintenanceEngine: MaintenanceEngine,
    private readonly complianceEngine: ComplianceEngine,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  @OnEvent('EventStore.*')
  async handleFleetEvents(payload: any) {
    if (!payload || !payload.eventType) return;

    try {
      switch (payload.eventType) {
        // AI Integration: Predictive Maintenance
        case 'BreakdownPredicted':
        case 'MaintenanceRecommended':
          await this.handlePredictiveMaintenance(
            payload.tenantId,
            payload.streamId,
            payload.payload,
            payload.userId,
          );
          break;

        // Trip Completion: Triggers Preventive Maintenance Odometer Checks
        case 'LifecycleStateChangedToCOMPLETED':
          if (payload.streamType === 'TRIP') {
            await this.handleTripCompleted(
              payload.tenantId,
              payload.streamId,
              payload.userId,
            );
          }
          break;

        case 'VehicleYardEntry':
          // Entry triggers automated compliance scans (FASTag, Permits, Insurance)
          // Mock data passed from Yard Management
          const docs = payload.payload.documents || [];
          await this.complianceEngine.evaluateDocumentCompliance(
            payload.tenantId,
            'VEHICLE',
            payload.streamId,
            docs,
          );
          break;
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      this.logger.error(
        `Fleet Orchestration Error: [${payload.eventType}] ${errorMessage}`,
      );
    }
  }

  private async handlePredictiveMaintenance(
    companyId: string,
    vehicleId: string,
    aiPayload: any,
    userId: string,
  ) {
    this.logger.warn(
      `AI Predicts Breakdown/Maintenance for Vehicle ${vehicleId}. Orchestrating response.`,
    );

    // 1. Log Event
    await this.eventStore.append({
      tenantId: companyId,
      streamId: vehicleId,
      streamType: 'VEHICLE',
      eventType: 'VehicleMaintenanceDue',
      payload: { reason: 'AI_PREDICTION', details: aiPayload },
      userId,
    });

    // 2. Transition Vehicle to PAUSED or UNDER_MAINTENANCE to prevent dispatch allocation
    if (aiPayload.severity === 'CRITICAL') {
      const vehicle = await (this.prisma as any).vehicle.findUnique({
        where: { id: vehicleId },
        select: { status: true },
      });
      if (vehicle && vehicle.status === 'ACTIVE') {
        await this.lifecycle.transitionState({
          companyId,
          entityType: 'Vehicle',
          entityId: vehicleId,
          fromState: vehicle.status,
          toState: 'BLOCKED',
          userId: 'SYSTEM',
          reason: 'AI Predicted Critical Breakdown',
        });
      }
    }
  }

  private async handleTripCompleted(
    companyId: string,
    tripId: string,
    _userId: string,
  ) {
    // 1. Extract Trip Vehicle & Odometer
    const trip = await this.prisma.runAsTenant(companyId, async (tx) =>
      tx.trip.findUnique({
        where: { id: tripId },
        select: { vehicleId: true, endOdometer: true },
      }),
    );

    if (trip && trip.vehicleId && trip.endOdometer) {
      // 2. Trigger Preventive Maintenance Checks
      await this.maintenanceEngine.checkPreventiveMaintenance(
        companyId,
        trip.vehicleId,
        trip.endOdometer,
      );
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';

@Injectable()
export class MaintenanceEngine {
  private readonly logger = new Logger(MaintenanceEngine.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventStore: EventStoreService,
    private readonly lifecycle: LifecycleEngineService,
  ) {}

  /**
   * Tracks Preventive Maintenance intervals (Odometer/Calendar).
   */
  async checkPreventiveMaintenance(
    companyId: string,
    vehicleId: string,
    currentOdometer: number,
  ) {
    this.logger.log(
      `Evaluating maintenance schedules for vehicle ${vehicleId}`,
    );

    return this.prisma.runAsTenant(companyId, async (tx) => {
      const vehicle = await tx.vehicle.findUnique({ where: { id: vehicleId } });
      if (!vehicle) return;

      // Dynamic rule checks (In reality, fetch from MaintenanceSchedule table)
      // E.g., Service every 10,000 km
      const lastServiceOdometer = 50000; // Mocked value
      const serviceInterval = 10000;

      if (currentOdometer >= lastServiceOdometer + serviceInterval) {
        this.logger.warn(`Maintenance due for Vehicle ${vehicleId}`);

        await this.eventStore.append({
          tenantId: companyId,
          streamId: vehicleId,
          streamType: 'VEHICLE',
          eventType: 'VehicleMaintenanceDue',
          payload: { reason: 'ODOMETER_INTERVAL', currentOdometer },
          userId: 'SYSTEM',
        });

        // Potentially shift status to 'MAINTENANCE_DUE'
      }
    });
  }

  async completeMaintenance(
    companyId: string,
    vehicleId: string,
    cost: number,
    details: any,
    userId: string,
  ) {
    this.logger.log(`Completing maintenance for ${vehicleId}`);

    // Auto-resume vehicle status via Lifecycle
    const vehicle = await (this.prisma as any).vehicle.findUnique({
      where: { id: vehicleId },
      select: { status: true },
    });
    if (vehicle && vehicle.status === 'UNDER_MAINTENANCE') {
      await this.lifecycle.transitionState({
        companyId,
        entityType: 'Vehicle',
        entityId: vehicleId,
        fromState: vehicle.status,
        toState: 'APPROVED',
        userId,
        reason: 'Maintenance Completed',
      });
    }

    await this.eventStore.append({
      tenantId: companyId,
      streamId: vehicleId,
      streamType: 'VEHICLE',
      eventType: 'MaintenanceCompleted',
      payload: { cost, details },
      userId,
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';

export interface TyreRotationDto {
  companyId: string;
  vehicleId: string;
  tyreId: string;
  oldPosition: string;
  newPosition: string;
  currentOdometer: number;
}

@Injectable()
export class TyreManagementService {
  private readonly logger = new Logger(TyreManagementService.name);

  constructor(
    // @ts-ignore: DI dependency reserved for future use
    private readonly _prisma: PrismaService,
    private readonly eventStore: EventStoreService,
  ) {}

  async logTyreRotation(dto: TyreRotationDto, userId: string) {
    this.logger.log(
      `Logging tyre rotation for Tyre ${dto.tyreId} on Vehicle ${dto.vehicleId}`,
    );

    // Track wear analysis based on position history
    await this.eventStore.append({
      tenantId: dto.companyId,
      streamId: dto.tyreId,
      streamType: 'TYRE',
      eventType: 'TyreRotated',
      payload: {
        vehicleId: dto.vehicleId,
        oldPosition: dto.oldPosition,
        newPosition: dto.newPosition,
        odometer: dto.currentOdometer,
      },
      userId,
    });

    return { status: 'RECORDED' };
  }

  async replaceTyre(
    companyId: string,
    vehicleId: string,
    oldTyreId: string,
    newTyreId: string,
    position: string,
    reason: string,
    userId: string,
  ) {
    this.logger.log(
      `Replacing Tyre ${oldTyreId} with ${newTyreId} on ${vehicleId}`,
    );

    await this.eventStore.append({
      tenantId: companyId,
      streamId: oldTyreId,
      streamType: 'TYRE',
      eventType: 'TyreRemoved',
      payload: { vehicleId, position, reason },
      userId,
    });

    await this.eventStore.append({
      tenantId: companyId,
      streamId: newTyreId,
      streamType: 'TYRE',
      eventType: 'TyreInstalled',
      payload: { vehicleId, position },
      userId,
    });

    return { status: 'REPLACED' };
  }
}

