          phone: data.phone,
          skills: data.skills || [],
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Maintenance',
          entityType: 'Mechanic',
          entityId: mechanic.id,
          action: 'CREATE',
          details: { name: mechanic.name },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'MAINTENANCE_MECHANIC',
        streamId: mechanic.id,
        eventType: 'MechanicCreated',
        payload: { name: mechanic.name },
        userId,
      });

      return mechanic;
    });
  }

  async getMechanics(companyId: string, workshopId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (workshopId) where.workshopId = workshopId;
      return tx.mechanic.findMany({ where });
    });
  }

  async createJobCard(companyId: string, data: any, userId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const jobCard = await tx.jobCard.create({
        data: {
          companyId,
          vehicleId: data.vehicleId,
          workshopId: data.workshopId,
          mechanicId: data.mechanicId,
          issueReported: data.issueReported,
          status: 'OPEN',
        },
      });

      if (data.parts && data.parts.length > 0) {
        let totalCost = 0;
        const partsData = data.parts.map((p: any) => {
          const cost = p.quantity * p.unitCost;
          totalCost += cost;
          return {
            jobCardId: jobCard.id,
            partName: p.partName,
            quantity: p.quantity,
            unitCost: p.unitCost,
            totalCost: cost,
          };
        });

        await tx.jobCardPart.createMany({ data: partsData });
        await tx.jobCard.update({
          where: { id: jobCard.id },
          data: { totalCost },
        });
      }

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Maintenance',
          entityType: 'JobCard',
          entityId: jobCard.id,
          action: 'CREATE',
          details: { vehicleId: jobCard.vehicleId },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'MAINTENANCE_JOB_CARD',
        streamId: jobCard.id,
        eventType: 'JobCardCreated',
        payload: { vehicleId: jobCard.vehicleId },
        userId,
      });

      return jobCard;
    });
  }

  async getJobCards(companyId: string, vehicleId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (vehicleId) where.vehicleId = vehicleId;
      return tx.jobCard.findMany({
        where,
        include: { parts: true, mechanic: true, workshop: true },
      });
    });
  }

  async closeJobCard(
    companyId: string,
    jobCardId: string,
    data: any,
    userId?: string,
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const updatedJobCard = await tx.jobCard.update({
        where: { id: jobCardId, companyId },
        data: {
          status: 'CLOSED',
          workDone: data.workDone,
          closedAt: new Date(),
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Maintenance',
          entityType: 'JobCard',
          entityId: jobCardId,
          action: 'CLOSE',
          details: { workDone: data.workDone },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'MAINTENANCE_JOB_CARD',
        streamId: jobCardId,
        eventType: 'JobCardClosed',
        payload: { workDone: data.workDone },
        userId,
      });

      return updatedJobCard;
    });
  }

  async createSchedule(companyId: string, data: any, userId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const schedule = await tx.maintenanceSchedule.create({
        data: {
          companyId,
          vehicleId: data.vehicleId,
          taskName: data.taskName,
          intervalDays: data.intervalDays,
          intervalKm: data.intervalKm,
        },
      });

      await this.auditService.logEvent(
        {
          companyId,
          entity: 'Maintenance',
          entityType: 'MaintenanceSchedule',
          entityId: schedule.id,
          action: 'CREATE',
          details: { taskName: schedule.taskName },
          source: 'API',
        },
        null,
        tx,
      );

      await this.eventStore.append({
        tenantId: companyId,
        streamType: 'MAINTENANCE_SCHEDULE',
        streamId: schedule.id,
        eventType: 'ScheduleCreated',
        payload: { taskName: schedule.taskName },
        userId,
      });

      return schedule;
    });
  }

  async getSchedules(companyId: string, vehicleId?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (vehicleId) where.vehicleId = vehicleId;
      return tx.maintenanceSchedule.findMany({ where });
    });
  }

  async getVehicleKundali(companyId: string, vehicleId: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const jobCards = await tx.jobCard.findMany({
        where: { companyId, vehicleId },
        include: { parts: true, workshop: true, mechanic: true },
        orderBy: { createdAt: 'desc' },
      });

      const maintenanceJobs = await tx.maintenanceJob.findMany({
        where: { companyId, vehicleId },
        include: { parts: true, vendor: true },
        orderBy: { openedAt: 'desc' },
      });

      const tyreLogs = await tx.tyreLog.findMany({
        where: { companyId, vehicleId },
        orderBy: { createdAt: 'desc' },
      });

      const timeline = [];

      for (const jc of jobCards) {
        timeline.push({
          type: 'JOB_CARD',
          id: jc.id,
          date: jc.closedAt || jc.createdAt,
          status: jc.status,
          title: `Job Card: ${jc.issueReported}`,
          cost: jc.totalCost,
          details: {
            workshop: jc.workshop?.name,
            mechanic: jc.mechanic?.name,
            workDone: jc.workDone,
            parts: jc.parts.map((p) => `${p.partName} (x${p.quantity})`),
          },
        });
      }

      for (const mj of maintenanceJobs) {
        timeline.push({
          type: 'MAINTENANCE_JOB',
          id: mj.id,
          date: mj.closedAt || mj.openedAt,
          status: mj.status,
          title: `Maintenance: ${mj.type}`,
          cost:
            mj.labourCost +
            mj.parts.reduce((sum: number, p: any) => sum + p.amount, 0),
          details: {
            vendor: mj.vendor?.name,
            odometer: mj.odometer,
            parts: mj.parts.map((p: any) => `${p.name} (x${p.qty})`),
          },
        });
      }

      for (const tl of tyreLogs) {
        timeline.push({
          type: 'TYRE_LOG',
          id: tl.id,
          date: tl.createdAt,
          status: 'COMPLETED',
          title: `Tyre Action: ${tl.action}`,
          cost: tl.cost,
          details: {
            position: tl.newPosition || tl.oldPosition,
            reason: tl.reason,
            odometer: tl.odometer,
            treadDepthMm: tl.treadDepthMm,
          },
        });
      }

      timeline.sort((a, b) => b.date.getTime() - a.date.getTime());

      return timeline;
    });
  }
}

