import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class PurchaseOrderService {
  constructor(private readonly prisma: PrismaService) {}

  async createPurchaseOrder(companyId: string, data: any) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      let totalAmount = 0;
      if (data.items && Array.isArray(data.items)) {
        totalAmount = data.items.reduce(
          (sum: number, item: any) => sum + item.quantity * item.unitPrice,
          0,
        );
      }

      return tx.purchaseOrder.create({
        data: {
          companyId,
          vendorId: data.vendorId,
          poNumber: data.poNumber,
          date: new Date(data.date),
          expectedDate: data.expectedDate
            ? new Date(data.expectedDate)
            : undefined,
          status: 'DRAFT',
          totalAmount,
          notes: data.notes,
          items: {
            create: (data.items || []).map((item: any) => ({
              companyId,
              description: item.description,
              quantity: item.quantity,
              unitPrice: item.unitPrice,
              totalPrice: item.quantity * item.unitPrice,
            })),
          },
        },
        include: { items: true },
      });
    });
  }

  async getPurchaseOrders(companyId: string, status?: string) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const where: any = { companyId };
      if (status) where.status = status;
      return tx.purchaseOrder.findMany({
        where,
        include: { vendor: true },
        orderBy: { date: 'desc' },
      });
    });
  }

  async receivePurchaseOrderItems(
    companyId: string,
    poId: string,
    receivedItems: any[],
  ) {
    return this.prisma.runAsTenant(companyId, async (tx) => {
      const po = await tx.purchaseOrder.findUnique({
        where: { id: poId, companyId },
        include: { items: true },
      });

      if (!po) throw new NotFoundException('Purchase order not found');

      let allReceived = true;
      let anyReceived = false;

      for (const reqItem of receivedItems) {
        const item = po.items.find((i) => i.id === reqItem.itemId);
        if (item) {
          const newReceivedQty = item.receivedQty + reqItem.quantity;
          await tx.purchaseOrderItem.update({
            where: { id: item.id },
            data: { receivedQty: newReceivedQty },
          });

          if (newReceivedQty > 0) anyReceived = true;
          if (newReceivedQty < item.quantity) allReceived = false;
        }
      }

      // Check remaining items to determine status
      const updatedPoItems = await tx.purchaseOrderItem.findMany({
        where: { purchaseOrderId: poId },
      });
      const fullyReceived = updatedPoItems.every(
        (i) => i.receivedQty >= i.quantity,
      );

      const newStatus = fullyReceived
        ? 'RECEIVED'
        : anyReceived
          ? 'PARTIAL_RECEIVED'
          : po.status;

      return tx.purchaseOrder.update({
        where: { id: poId },
        data: { status: newStatus },
        include: { items: true },
      });
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EventStoreService } from '../../platform/digital-twin/event-store.service';
import { LifecycleEngineService } from '../../platform/lifecycle/lifecycle-engine.service';
import { ResourceOrchestratorService } from '../../platform/runtime/resource-orchestrator.service';
import { PredictionEngineService } from '../../ai/prediction/prediction.service';

@Injectable()
export class InboundOutboundEngine {
  private readonly logger = new Logger(InboundOutboundEngine.name);

  constructor(
    private readonly eventStore: EventStoreService,
    // @ts-ignore: DI dependency reserved for future use
    private readonly _lifecycle: LifecycleEngineService,
    private readonly resourceOrchestrator: ResourceOrchestratorService,
    // @ts-ignore: DI dependency reserved for future use
    private readonly _aiPrediction: PredictionEngineService,
  ) {}

  /**
   * Processes Advance Shipping Notice (ASN) for Inbound.
   */
  async processAsn(
    companyId: string,
    asnId: string,
    payload: any,
    userId: string,
  ) {
    this.logger.log(`Processing ASN ${asnId}`);

    // Cross-Dock Evaluation (AI Integration)
    // In production, we'd call AI to check if inbound stock matches pending outbound orders exactly
    let isCrossDock = false;
    if (payload.priority === 'URGENT') {
      isCrossDock = true; // Simulated ML trigger
      await this.eventStore.append({
        tenantId: companyId,
        streamId: asnId,
        streamType: 'ASN',
        eventType: 'CrossDockTriggered',
        payload: { matchScore: 0.98, targetOutboundOrder: 'ORD-1002' },
        userId,
      });
    }

    // Schedule Dock
    await this.resourceOrchestrator.allocateResource({
      companyId,
      resourceType: 'DOCK',
      resourceId: payload.dockId || 'DOCK-1',
      entityType: 'ASN',
      entityId: asnId,
      startTime: new Date(),
      endTime: new Date(Date.now() + 2 * 60 * 60 * 1000), // 2 hour block
    });

    await this.eventStore.append({
      tenantId: companyId,
      streamId: asnId,
      streamType: 'ASN',
      eventType: 'InventoryReceived',
      payload: { ...payload, isCrossDock },
      userId,
    });

    return { status: 'RECEIVED', isCrossDock };
  }

  /**
   * Generates optimal pick waves for Outbound orders.
   */
  async generatePickWave(
    companyId: string,
    orderIds: string[],
    userId: string,
  ) {
    this.logger.log(`Generating Pick Wave for ${orderIds.length} orders`);

    // Call AI for Optimal Picking Route & Cluster optimization
    // Mocked response for scale
    const waveId = `WAVE-${Date.now()}`;

    // Assuming lifecycle engine transitions orders to ALLOCATED / IN_PROGRESS
    for (const orderId of orderIds) {
      // Mock Transition
      this.logger.log(`Routing ${orderId} to Wave ${waveId}`);
    }

    await this.eventStore.append({
      tenantId: companyId,
      streamId: waveId,
      streamType: 'WAVE',
      eventType: 'WavePlanned',
      payload: { orderIds, estimatedTimeSec: 1200 },
