        .set('Authorization', `Bearer ${adminToken}`)
        .send({});
      console.log(`[WMS/CRM] POST ${ep} -> ${res.status}`);
      expect(res.status).not.toBe(200);
      expect(res.status).not.toBe(201);
    }
  });
});

