async function seedTrip(
  prisma: PrismaService,
  cid: string,
  vehicleId: string,
  driverId: string,
  distance = 1000,
) {
  return prisma.runAsSystem('e2e-setup', async (tx) => {
    const t = await tx.trip.create({
      data: {
        companyId: cid,
        vehicleId,
        driverId,
        tripNumber: `T-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        status: 'COMPLETED',
        estimatedDistance: distance,
        actualDistance: distance,
      },
    });
    return t.id;
  });
}

async function seedFuel(
  prisma: PrismaService,
  cid: string,
  tripId: string,
  vehicleId: string,
  driverId: string,
  litres: number,
  expectedLitres: number,
  originCity: string,
  destinationCity: string,
) {
  const variancePct = ((litres - expectedLitres) / expectedLitres) * 100;
  return prisma.runAsSystem('e2e-setup', (tx) =>
    tx.fuelEntry.create({
      data: {
        companyId: cid,
        tripId,
        vehicleId,
        driverId,
        litres,
        amount: litres * 85,
        expectedLitres,
        variancePct,
        originCity,
        destinationCity,
      },
    }),
  );
}

// ── Test Suite ────────────────────────────────────────────────────────────────

describe('Fuel Variance Root-Cause (E2E)', () => {
  let app: INestApplication;
  let prisma: PrismaService;
  let jwt: JwtService;
  let config: ConfigService;

  let tenantA: Awaited<ReturnType<typeof setupTenant>>;
  let tenantB: Awaited<ReturnType<typeof setupTenant>>;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api/v1');
    app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true }),
    );
    await app.init();

    prisma = app.get(PrismaService);
    jwt = app.get(JwtService);
    config = app.get(ConfigService);

    const stamp = Date.now().toString().slice(-6);
    tenantA = await setupTenant(prisma, jwt, config, `A${stamp}`);
    tenantB = await setupTenant(prisma, jwt, config, `B${stamp}`);
  }, 60000);

  afterAll(async () => {
    // Cascade delete via FuelEntry -> Trip -> Driver/Vehicle, then Company
    for (const cid of [tenantA?.companyId, tenantB?.companyId].filter(
      Boolean,
    )) {
      try {
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "FuelEntry" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "TripExpense" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "Trip" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "Driver" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "Vehicle" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "User" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.$executeRawUnsafe(
            `DELETE FROM "Role" WHERE "companyId" = '${cid}'`,
          ),
        );
        await prisma.runAsSystem('e2e-cleanup', (tx) =>
          tx.company.delete({ where: { id: cid } }),
        );
      } catch (_) {
        /* best-effort */
      }
    }
    await app.close();
  });

  // ── 1. DRIVER isolation ──────────────────────────────────────────────────
