    // Users — assign each user the role for their own company
    await prisma.runAsSystem('e2e test seed', async (tx) => {
      await tx.user.createMany({
        data: [
          {
            id: USER_A_ID,
            email: EMAIL_A,
            password: passwordHash,
            firstName: 'IntegA',
            lastName: 'User',
