      await tx.integrationConnection.createMany({
        data: [
          {
            id: CONN_A_ID,
            companyId: COMPANY_A_ID,
            connectorId: CONNECTOR_ID,
            credentials:
              '{"iv":"ecdea2a5e7936ce04d72faf87b1c3380","content":"01fb4ad13911e18e2d920f4c35b0a2be71cac959a32fa2423aa2ed0371a29069e3e06b78a4c05c041273abc1068b70bbc7ae8e0ee43ebfd18515d5b1f2ab2850399ceff44917f5aebeb8ef3bb44432791b556b1d12daee398df8dafd22ebc75e69b1ed2417a9b3b780ffcb6b97945e5d0f6a3c5219e3066274bfa676af","tag":"a2c0f03abc86d3eac76d50a412bc4032"}',
            settings: {},
            status: 'ENABLED',
          },
          {
            id: CONN_B_ID,
            companyId: COMPANY_B_ID,
            connectorId: CONNECTOR_ID,
            credentials:
              '{"iv":"098efaa791d6795393f8b1f81fb8069c","content":"8e8e45dd56d8d7cf9deb66368a17156fcdf190f9a19e938c9e05602c7ebfcec0f19df8d5a23c3e6a2f04438c4e338e5394e10311f61d37f523a608774655b9f25ab15191e90ac0b1e7bc5a5ad559e897be82d6da9c60c68bb0d08a294dee54e8a73afa9dd1ae442a0a3a716959f923fe0cb343371e49ce65677bf2854af53f91bed6cafc","tag":"6bc877cdab4ccc1bc5e58f7e25a3ef07"}',
