    });

    it('Tenant B cannot disable Tenant A connection (must be 403 or 404)', async () => {
      const res = await request(app.getHttpServer())
        .post(`/integration/hub/connections/${CONN_A_ID}/disable`)
        .set('Authorization', `Bearer ${tokenB}`)
        .send();

      expect([403, 404]).toContain(res.status);
    });

    it('Tenant A CAN enable own connection (positive control)', async () => {
      const res = await request(app.getHttpServer())
        .post(`/integration/hub/connections/${CONN_A_ID}/enable`)
        .set('Authorization', `Bearer ${tokenA}`)
        .send();

      console.log('\n--- AJ1 A enables OWN connection ---');
      console.log('Status:', res.status);
      console.log('------------------------------------\n');
      expect(res.status).toBeLessThan(300);
    });
  });

  // ─── AI1(c): Unsigned webhook writes ──────────────────────
  describe('Webhook signature enforcement', () => {
    it('POST /webhooks/v1/incoming with no signature must NOT return 2xx', async () => {
      const res = await request(app.getHttpServer())
        .post(`/webhooks/v1/incoming/quickbooks/${CONN_A_ID}`)
        .send({ payload: { data: 'test' } })
        .set('Content-Type', 'application/json');

      console.log('\n--- AJ2 no signature ---');
      console.log('Status:', res.status);
      console.log('------------------------\n');
      expect(res.status).toBe(401);
    });

    it('POST /webhooks/v1/incoming with wrong signature must NOT return 2xx', async () => {
      const payload = { payload: { event_type: 'test.event', data: {} } };
      const res = await request(app.getHttpServer())
        .post(`/webhooks/v1/incoming/quickbooks/${CONN_A_ID}`)
        .send(payload)
        .set('x-webhook-signature', 'wrong-signature')
        .set('Content-Type', 'application/json');

      console.log('\n--- AJ2 wrong signature ---');
      console.log('Status:', res.status);
      console.log('---------------------------\n');
      expect(res.status).toBe(401);
    });

    it('POST /webhooks/v1/incoming with valid signature MUST return 201', async () => {
      const payload = { payload: { event_type: 'test.event', data: {} } };
      const signatureA = crypto
        .createHmac('sha256', 'hmac-secret-123')
        .update(JSON.stringify(payload))
        .digest('hex');
      const res = await request(app.getHttpServer())
        .post(`/webhooks/v1/incoming/E2E_TEST_CONNECTOR/${CONN_A_ID}`)
        .set('x-webhook-signature', signatureA)
        .send(payload);

      expect(res.status).toBe(201);
    });

    it('POST /webhooks/v1/incoming with signature A for connection B MUST return 401', async () => {
      const payload = { payload: { event_type: 'test.event', data: {} } };
      const signatureA = crypto
        .createHmac('sha256', 'hmac-secret-123')
        .update(JSON.stringify(payload))
        .digest('hex');
      const res = await request(app.getHttpServer())
        .post(`/webhooks/v1/incoming/quickbooks/${CONN_B_ID}`)
        .send(payload)
        .set('x-webhook-signature', signatureA)
        .set('Content-Type', 'application/json');

      console.log('\n--- AJ2 valid-sig-for-A against B ---');
      console.log('Status:', res.status);
      console.log('-------------------------------------\n');
      expect(res.status).toBe(401);
    });
  });

  // ─── AI1(b): Event replay with empty payload ──────────────
  describe('Event replay input validation', () => {
    it('POST /integration/events/replay with {} must return 400, not replay all events', async () => {
      const res = await request(app.getHttpServer())
        .post('/integration/events/replay')
        .set('Authorization', `Bearer ${tokenA}`)
        .send({});

      console.log('\n--- AJ3 replay {} ---');
      console.log('Status:', res.status);
      console.log('---------------------\n');
      expect(res.status).toBe(400);
    });
  });

  // ─── AI1(b): Export crash on empty payload ────────────────
  describe('Export execute input validation', () => {
    it('POST /integration/export/execute with {} must return 400, not 500', async () => {
      const res = await request(app.getHttpServer())
        .post('/integration/export/execute')
        .set('Authorization', `Bearer ${tokenA}`)
        .send({});

      console.log('\n--- AJ3 export {} ---');
      console.log('Status:', res.status);
      console.log('---------------------\n');
      expect(res.status).toBe(400);
    });
  });
});

import { PrismaService } from '../src/prisma/prisma.service';

describe('A1 Lock Monitor (Real Database RLS)', () => {
  let prisma: PrismaService;

  beforeAll(async () => {
    // Drop NestJS mocks and connect directly to the real database
    prisma = new PrismaService();
    await prisma.onModuleInit();
  });

  afterAll(async () => {
    await prisma.onModuleDestroy();
  });

  it('runAsTenant should strictly isolate data via Postgres RLS', async () => {
    // 1. Seed test data using system bypass
    await prisma.runAsSystem('[IsolationTest] Seed Data', async (tx) => {
      await tx.company.upsert({
        where: { id: 'tenant-a' },
        update: {},
        create: { id: 'tenant-a', name: 'Tenant A' },
      });
      await tx.company.upsert({
        where: { id: 'tenant-b' },
        update: {},
        create: { id: 'tenant-b', name: 'Tenant B' },
      });
      await tx.customer.upsert({
        where: { id: 'cust-a-123' },
        update: {},
        create: { id: 'cust-a-123', name: 'Cust A', companyId: 'tenant-a' },
      });
      await tx.customer.upsert({
        where: { id: 'cust-b-456' },
        update: {},
        create: { id: 'cust-b-456', name: 'Cust B', companyId: 'tenant-b' },
      });
    });

    // 2. Test runAsTenant with tenant-a
    await prisma.runAsTenant('tenant-a', async (tx) => {
      // Verify app.current_company_id is set
      const rlsCheck =
        await tx.$queryRaw<any>`SELECT current_setting('app.current_company_id', true) as cid`;
      expect(rlsCheck[0].cid).toBe('tenant-a');

      // Attempt to read own data (Should Succeed)
      const custA = await (tx as any).customer.findUnique({
        where: { id: 'cust-a-123' },
      });
      expect(custA).toBeDefined();
      expect(custA?.id).toBe('cust-a-123');

      // ORM CROSS-TENANT READ (Should Fail/Return Null)
      const custB = await (tx as any).customer.findUnique({
        where: { id: 'cust-b-456' },
      });
      expect(custB).toBeNull();

      // RAW SQL CROSS-TENANT READ (Should Return 0 rows due to RLS)
      const rawCustB =
        await tx.$queryRaw<any>`SELECT * FROM "Customer" WHERE id = 'cust-b-456'`;
      expect(rawCustB.length).toBe(0);

      // GUC RE-POINT ATTACK (Should trigger Interceptor Exception)
      expect(() => {
        tx.$executeRawUnsafe(
          `SELECT set_config('app.current_company_id', 'tenant-b', true)`,
        );
      }).toThrow('Forbidden raw query pattern');
    });

    // 3. Test runAsTenant with tenant-b
    await prisma.runAsTenant('tenant-b', async (tx) => {
      const custA = await (tx as any).customer.findUnique({
        where: { id: 'cust-a-123' },
      });
      expect(custA).toBeNull();
    });
  });
});

