        originState: 'Maharashtra',
        destinationAddress: '456 Park Ave',
        destinationCity: 'Delhi',
        destinationState: 'Delhi',
        pickupDate: new Date().toISOString(),
        deliveryDate: new Date(Date.now() + 86400000).toISOString(),
        rate: 1000,
      });
