      expect(res.status).toBe(200);
      expect(res.body.distanceSource).toBe('OSRM_PUBLIC');
      expect(res.body.tollEstimateType).toBe('CALCULATED_AVERAGE');
      expect(res.body.distanceKm).toBeGreaterThan(100);
